];

# Common Medicare Part D coverage gap thresholds (2026)
glob PART_D_THRESHOLDS: dict = {
    "deductible": 590.0,          # 2026 Part D deductible
    "initial_coverage_limit": 5030.0,
    "catastrophic_threshold": 8000.0,
    "coverage_gap_oop_threshold": 8000.0
};

# Drug tier levels (typical formulary)
glob DRUG_TIERS: dict = {
    1: "Preferred Generic",
    2: "Non-Preferred Generic",
    3: "Preferred Brand",
    4: "Non-Preferred Brand",
    5: "Specialty"
};

def check_drug_interaction(drug_a: str, drug_b: str) -> dict {
    """
    Simple interaction check between two drug names (lowercased keywords).
    Returns interaction dict if found, or empty dict.
    Note: Not for clinical use — use a proper drug database in production.
    """
    a_lower = drug_a.lower();
    b_lower = drug_b.lower();
    for interaction in HIGH_RISK_INTERACTIONS {
        if ((interaction["drug_a"] in a_lower and interaction["drug_b"] in b_lower) or
            (interaction["drug_a"] in b_lower and interaction["drug_b"] in a_lower)) {
            return interaction;
        }
    }
    return {};
}

def estimate_part_d_cost_stage(ytd_drug_spend: float) -> str {
    """
    Estimate which Part D coverage stage a patient is in based on YTD drug spend.
    """
    if ytd_drug_spend < PART_D_THRESHOLDS["deductible"] {
        return "DEDUCTIBLE";
    } elif ytd_drug_spend < PART_D_THRESHOLDS["initial_coverage_limit"] {
        return "INITIAL_COVERAGE";
    } elif ytd_drug_spend < PART_D_THRESHOLDS["catastrophic_threshold"] {
        return "COVERAGE_GAP";
    } else {
        return "CATASTROPHIC";
    }
}

def parse_sig_code(sig: str) -> dict {
    """
    Parse a prescription sig (directions) into structured components.
    e.g. 'Take 1 tablet by mouth twice daily with food'
    Returns dict with dose, route, frequency, notes.
    """
    sig_lower = sig.lower();
    # Frequency detection
    frequency = "unknown";
    if "once daily" in sig_lower or "qd" in sig_lower or "every day" in sig_lower {
        frequency = "once_daily";
    } elif "twice daily" in sig_lower or "bid" in sig_lower {
        frequency = "twice_daily";
    } elif "three times" in sig_lower or "tid" in sig_lower {
        frequency = "three_times_daily";
    } elif "four times" in sig_lower or "qid" in sig_lower {
        frequency = "four_times_daily";
    } elif "as needed" in sig_lower or "prn" in sig_lower {
        frequency = "as_needed";
    }
    # Route detection
    route = "oral";
    if "injection" in sig_lower or "inject" in sig_lower {
        route = "injection";
    } elif "topical" in sig_lower or "apply" in sig_lower {
        route = "topical";
    } elif "inhale" in sig_lower or "inhal" in sig_lower {
        route = "inhalation";
    }
    return {
        "raw": sig,
        "frequency": frequency,
        "route": route
    };
}

"""Money and billing amount utility functions."""

def parse_dollar_amount(amount_str: str) -> float {
    """
    Parse a dollar amount string to float.
    Handles: '$1,234.56', '1234.56', '($500.00)', '-$500.00'
    """
    try {
        cleaned = amount_str.strip();
        # Handle parenthetical negatives like (500.00)
        negative = cleaned.startswith("(") and cleaned.endswith(")");
        # Remove currency symbols, commas, parentheses
        cleaned = cleaned.replace("$", "").replace(",", "").replace("(", "").replace(")", "").strip();
        value = float(cleaned);
        return -value if negative else value;
    } except Exception {
        return 0.0;
    }
}

def format_currency(amount: float) -> str {
    """Format a float as USD currency string."""
    if amount < 0 {
        return f"(${abs(amount):,.2f})";
    }
    return f"${amount:,.2f}";
}

def calc_coinsurance(allowed_amount: float, coinsurance_rate: float = 0.20) -> float {
    """Calculate patient coinsurance (default 20% Medicare Part B)."""
    return round(allowed_amount * coinsurance_rate, 2);
}

def calc_patient_responsibility(
    allowed_amount: float,
    paid_amount: float,
    deductible_remaining: float = 0.0
) -> float {
    """
    Calculate patient's total out-of-pocket for a service.
    = deductible_applied + coinsurance on remaining balance.
    """
    deductible_applied = min(deductible_remaining, allowed_amount);
    post_deductible = allowed_amount - deductible_applied;
    coinsurance = calc_coinsurance(post_deductible);
    return round(deductible_applied + coinsurance, 2);
}

def is_balance_billing(charge_amount: float, allowed_amount: float, paid_amount: float, patient_paid: float) -> bool {
    """
    Detect potential balance billing (provider charging more than allowed).
    Returns True if patient seems to have been billed more than their legal responsibility.
    """
    if allowed_amount <= 0 {
        return False;
    }
    patient_legal_max = calc_coinsurance(allowed_amount) + 240.0;  # 2026 Part B deductible
    return patient_paid > patient_legal_max * 1.1;  # 10% tolerance
}

def sum_disputed_amounts(disputes: list[dict]) -> float {
    """Sum amount_disputed across a list of dispute dicts."""
    total = 0.0;
    for d in disputes {
        total += d.get("amount_disputed", 0.0);
    }
    return round(total, 2);
}

"""Unified notification sender — routes to SMS, push, or email based on preferences."""

import from graph.nodes.notification { Notification }

def send_notification_to_patient(patient: object, notification: Notification) -> dict {
    """
    Send a notification to a patient using their preferred channel.
    Routes to Twilio SMS, Firebase push, or SendGrid email.
    Returns dict with delivery status per channel.
    """
    results = {};
    if notification.severity in ["CRITICAL", "URGENT"] {
        # Send to all channels for critical alerts
        if patient.phone != "" {
            results["sms"] = _send_sms_notification(patient.phone, notification);
        }
        if patient.email != "" {
            results["email"] = _send_email_notification(patient.email, notification);
        }
    } else {
        # Use preferred channel for non-critical
        channel = getattr(patient, "notification_preference", "sms");
        if channel == "sms" and patient.phone != "" {
            results["sms"] = _send_sms_notification(patient.phone, notification);
        } elif channel == "email" and patient.email != "" {
            results["email"] = _send_email_notification(patient.email, notification);
        } elif patient.phone != "" {
            results["sms"] = _send_sms_notification(patient.phone, notification);
        }
    }
    return results;
}

def _send_sms_notification(phone: str, notification: Notification) -> bool {
    """Send notification via SMS."""
    try {
        import from integrations.notifications.twilio_client { send_sms }
        msg = f"AgeWise Alert [{notification.severity}]: {notification.title}\n{notification.message}";
        result = send_sms(phone, msg);
        return "error" not in result;
    } except Exception as e {
        print(f"[NotificationSender] SMS failed: {e}");
        return False;
    }
}

def _send_email_notification(email: str, notification: Notification) -> bool {
    """Send notification via email."""
    try {
        import from integrations.email.email_sender { send_email }
        return send_email(
            to_address=email,
            subject=f"AgeWise — {notification.title}",
            body_text=notification.message
        );
    } except Exception as e {
        print(f"[NotificationSender] Email failed: {e}");
        return False;
    }
}

def send_notification(patient_id: str, channel: str, message: str, severity: str = "INFO") -> bool {
    """Simplified notification dispatch used by walkers.
    Logs the notification and routes to the appropriate channel.
    patient_id: patient name or ID for logging.
    channel: SMS | EMAIL | PUSH | IN_APP.
    severity: INFO | MEDIUM | HIGH | CRITICAL.
    """
    print(f"[Notification] [{severity}] To: {patient_id} via {channel}: {message}");
    # Production: route to Twilio/SendGrid/push based on channel
    return True;
}

def format_notification_message(notification_type: str, context: dict) -> str {
    """Generate a human-readable notification message from type and context."""
    templates = {
        "APPEAL_DEADLINE": "Your appeal deadline for dispute {dispute_id} is {days_remaining} days away (due {due_date}).",
        "BILL_DUE": "Your {biller} bill of {amount} is due in {days} days.",
        "SCAM_ALERT": "URGENT: Suspicious transaction detected — ${amount} to {payee}. Please review immediately.",
        "LEGAL_EXPIRY": "Your {doc_type} document expires in {days} days. Consider renewal.",
        "DIGEST_READY": "Your weekly AgeWise health & benefits summary is ready.",
        "ACTION_REQUIRED": "Action required: {action_description}"
    };
    template = templates.get(notification_type, "AgeWise notification: {message}");
    try {
        return template.format(**context);
    } except Exception {
        return template;
    }
}

