        title     = GAP_LABELS.get(gap_type, gap_type.replace("_", " "));

        outer_cls  = f"flex items-start gap-3 p-4 rounded-xl border {'bg-orange-50 border-orange-200' if is_urgent else 'bg-yellow-50 border-yellow-200'}";
