        badgeLabel = "LIKELY ELIGIBLE" if is_eligible else "NOT ELIGIBLE";
        savingsFmt = fmt(float(elig.get("estimated_savings_monthly", 0)));

        return (
            <div style={cardStyle}>
                <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;">
                    <h4 style="margin:0;font-size:15px;font-weight:600;color:#1e293b;">{elig.get("program_name")}</h4>
                    <span style={badgeStyle}>{badgeLabel}</span>
                </div>
                {is_eligible and (
                    <p style="margin:0 0 8px;font-size:20px;font-weight:700;color:#22c55e;">
                        ${savingsFmt}<span style="font-size:13px;font-weight:400;color:#64748b;">/month</span>
                    </p>
                )}
                <p style="margin:0;font-size:13px;color:#64748b;line-height:1.5;">{elig.get("eligibility_reason", "")}</p>
                {is_eligible and elig.get("application_url") and (
                    <button
                        onClick={on_apply}
                        style="margin-top:16px;width:100%;background:#22c55e;color:white;border:none;border-radius:6px;padding:10px;font-size:14px;font-weight:600;cursor:pointer;"
                    >
                        Apply Now
                    </button>
                )}
                {is_eligible and elig.get("application_phone") and (
                    <p style="margin:8px 0 0;text-align:center;font-size:12px;color:#64748b;">or call {elig.get("application_phone")}</p>
                )}
            </div>
        );
    }
}

"""BillDueCard component — upcoming bill card with status and pay/snooze actions."""

cl {
    def:pub BillDueCard(props: dict) -> JsxElement {
        bill = props.get("bill", {});
        on_pay = props.get("onPay");
        on_snooze = props.get("onSnooze");

        days_until = props.get("daysUntilDue", 0);
        is_overdue = days_until < 0;

        def fmt(v: float) -> str {
            return f"{v:.2f}";
        }

        urgencyStyle = "border-left:4px solid #ef4444;" if is_overdue else ("border-left:4px solid #f59e0b;" if days_until <= 3 else "border-left:4px solid #e2e8f0;");
        cardStyle = "background:white;border-radius:8px;padding:16px;box-shadow:0 1px 3px rgba(0,0,0,.1);" + urgencyStyle;
        amountFmt = fmt(float(bill.get("expected_amount", 0)));
        dueColor = "color:#ef4444;font-weight:600;" if is_overdue else "color:#64748b;";
        dueStyle = "margin:4px 0 0;font-size:12px;" + dueColor;
        absdays = abs(days_until);
        dueText = f"Overdue {absdays} days" if is_overdue else f"Due in {days_until} days";

        return (
            <div style={cardStyle}>
                <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;">
                    <div>
                        <p style="margin:0;font-weight:600;color:#1e293b;font-size:14px;">{bill.get("biller_name")}</p>
                        <p style="margin:4px 0 0;font-size:12px;color:#64748b;">{bill.get("category")}</p>
                    </div>
                    <div style="text-align:right;">
                        <p style="margin:0;font-weight:700;font-size:18px;color:#1e293b;">${amountFmt}</p>
                        <p style={dueStyle}>{dueText}</p>
                    </div>
                </div>
                <div style="display:flex;gap:8px;margin-top:12px;">
                    <button
                        onClick={on_pay}
                        style="flex:2;background:#3b82f6;color:white;border:none;border-radius:6px;padding:7px;font-size:12px;cursor:pointer;"
                    >
                        Mark Paid
                    </button>
                    <button
                        onClick={on_snooze}
                        style="flex:1;background:#f1f5f9;color:#64748b;border:none;border-radius:6px;padding:7px;font-size:12px;cursor:pointer;"
                    >
                        Snooze
                    </button>
                </div>
            </div>
        );
    }
}

"""CareGapAlert component — care gap warning with recommended action."""

cl {
    def:pub CareGapAlert(props: dict) -> JsxElement {
        gap = props.get("gap", {});
        severity = gap.get("severity", "LOW");

        low_style = "background:#f0fdf4;border-color:#86efac;color:#166534;";
        med_style = "background:#fefce8;border-color:#fde047;color:#854d0e;";
        high_style = "background:#fef2f2;border-color:#fca5a5;color:#dc2626;";
        crit_style = "background:#fff1f2;border-color:#fb7185;color:#be123c;";

        baseStyle = "border-radius:8px;padding:16px;border:1px solid;margin-bottom:8px;";
        colorStyle = crit_style if severity == "CRITICAL" else (high_style if severity == "HIGH" else (med_style if severity == "MEDIUM" else low_style));
        cardStyle = baseStyle + colorStyle;

        days_overdue = gap.get("days_overdue", 0);

        return (
            <div style={cardStyle}>
                <div style="display:flex;justify-content:space-between;align-items:center;">
                    <span style="font-weight:600;font-size:14px;">{gap.get("gap_type")} Care Gap</span>
                    <span style="font-size:11px;font-weight:600;text-transform:uppercase;">{severity}</span>
                </div>
                <p style="margin:6px 0 0;font-size:13px;">{gap.get("recommended_action")}</p>
                {days_overdue > 0 and (
                    <p style="margin:4px 0 0;font-size:12px;font-weight:500;">Overdue by {days_overdue} days</p>
                )}
            </div>
        );
    }
}

"""DisputeCard component — dispute summary with status badge and action buttons."""

cl {
    def:pub DisputeCard(props: dict) -> JsxElement {
        dispute = props.get("dispute", {});
        status = dispute.get("status", "OPEN");
        status_colors = {
            "OPEN": "background:#fef3c7;color:#92400e;",
            "IN_PROGRESS": "background:#eff6ff;color:#1d4ed8;",
            "APPEALED": "background:#f0fdf4;color:#166534;",
            "RESOLVED": "background:#f1f5f9;color:#475569;"
        };

        def fmt(v: float) -> str {
            return f"{v:.2f}";
        }

        statusColor = "background:#fef3c7;color:#92400e;" if status == "OPEN" else ("background:#eff6ff;color:#1d4ed8;" if status == "IN_PROGRESS" else ("background:#f0fdf4;color:#166534;" if status == "APPEALED" else "background:#f1f5f9;color:#475569;"));
        statusStyle = "padding:3px 10px;border-radius:9999px;font-size:11px;font-weight:600;" + statusColor;
        amountFmt = fmt(float(dispute.get("amount_disputed", 0)));

        return (
            <div style="background:white;border-radius:8px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1);border-left:4px solid #ef4444;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
                    <span style="font-weight:600;color:#1e293b;font-size:15px;">{dispute.get("error_type", "Billing Error")}</span>
                    <span style={statusStyle}>{status}</span>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">
                    <div>
                        <p style="margin:0;font-size:11px;color:#94a3b8;text-transform:uppercase;">Amount Disputed</p>
                        <p style="margin:4px 0 0;font-size:18px;font-weight:700;color:#ef4444;">${amountFmt}</p>
                    </div>
                    <div>
                        <p style="margin:0;font-size:11px;color:#94a3b8;text-transform:uppercase;">Appeal Level</p>
                        <p style="margin:4px 0 0;font-size:18px;font-weight:700;color:#1e293b;">L{dispute.get("appeal_level", 1)}</p>
                    </div>
                </div>
                <p style="margin:0;font-size:13px;color:#64748b;">{dispute.get("error_description", "")}</p>
                {dispute.get("deadline") and (
                    <p style="margin:8px 0 0;font-size:12px;color:#f59e0b;font-weight:500;">Deadline: {dispute.get("deadline")}</p>
                )}
            </div>
        );
    }
}

"""MedicationRow component — medication list row with refill status and interaction icon."""

cl {
    def:pub MedicationRow(props: dict) -> JsxElement {
        med = props.get("medication", {});
        rx = props.get("prescription", {});
        has_interaction = props.get("hasInteraction", False);

        days_rem = int(rx.get("days_remaining", 0) or 0);
        days_sup = int(rx.get("days_supply", 30) or 30);

        refill_pct = 100;
        if days_sup > 0 {
            refill_pct = min(100, int(days_rem * 100 / days_sup));
        }

        bar_color = "#22c55e" if refill_pct > 30 else ("#f59e0b" if refill_pct > 10 else "#ef4444");
        barStyle = "height:100%;border-radius:9999px;width:" + str(refill_pct) + "%;background:" + bar_color + ";";

        return (
            <div style="display:flex;align-items:center;padding:12px 0;border-bottom:1px solid #e2e8f0;gap:16px;">
                <div style="flex:2;">
                    <div style="display:flex;align-items:center;gap:6px;">
                        <span style="font-weight:500;color:#1e293b;font-size:14px;">{med.get("drug_name")}</span>
                        {has_interaction and (
                            <span style="background:#fef2f2;color:#dc2626;font-size:10px;font-weight:700;padding:1px 5px;border-radius:4px;" title="Drug interaction warning">
                                ⚠
                            </span>
                        )}
                    </div>
                    <p style="margin:2px 0 0;font-size:12px;color:#64748b;">{med.get("strength")} — {med.get("therapeutic_class")}</p>
                </div>
                <div style="flex:1;">
                    <div style="background:#e2e8f0;border-radius:9999px;height:6px;overflow:hidden;">
                        <div style={barStyle}></div>
                    </div>
                    <p style="margin:4px 0 0;font-size:11px;color:#64748b;">{days_rem} days left</p>
                </div>
                <div style="flex:1;text-align:right;">
                    <p style="margin:0;font-size:12px;color:#64748b;">Next fill: {rx.get("next_fill_due", "—")}</p>
                    <p style="margin:2px 0 0;font-size:12px;color:#64748b;">{rx.get("refills_remaining", 0)} refills left</p>
                </div>
            </div>
        );
    }
}

"""PriorAuthTracker component — prior auth status pipeline visualization."""

cl {
    def:pub PriorAuthTracker(props: dict) -> JsxElement {
        auth = props.get("prior_auth", {});
        status = auth.get("status", "PENDING");

        steps = ["PENDING", "UNDER_REVIEW", "DECIDED"];
        step_labels = {"PENDING": "Submitted", "UNDER_REVIEW": "Under Review", "DECIDED": "Decided"};

        current_idx = 0;
        if status == "UNDER_REVIEW" {
            current_idx = 1;
        } elif status == "DECIDED" {
            current_idx = 2;
        }

        decision = auth.get("decision", "Unknown");
        isApproved = decision == "APPROVED";
        decisionStyle = "margin-top:12px;padding:8px;border-radius:6px;text-align:center;font-size:13px;font-weight:600;" + ("background:#f0fdf4;color:#166534;" if isApproved else "background:#fef2f2;color:#dc2626;");

        return (
            <div style="background:white;border-radius:8px;padding:16px;box-shadow:0 1px 3px rgba(0,0,0,.1);">
                <div style="display:flex;justify-content:space-between;margin-bottom:16px;">
                    <span style="font-weight:600;font-size:14px;color:#1e293b;">{auth.get("medication_or_service", "Prior Authorization")}</span>
                    <span style="font-size:12px;color:#64748b;">Auth # {auth.get("auth_number", "—")}</span>
                </div>
                <div style="display:flex;align-items:center;gap:0;">
                    {[
                        <div key={step} style="flex:1;text-align:center;">
                            <div style={"width:28px;height:28px;border-radius:50%;margin:0 auto;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:#3b82f6;color:white;" if steps.index(step) <= current_idx else "width:28px;height:28px;border-radius:50%;margin:0 auto;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:#e2e8f0;color:#94a3b8;"}>{steps.index(step) + 1}</div>
                            <p style={"margin:6px 0 0;font-size:11px;color:#3b82f6;font-weight:600;" if steps.index(step) == current_idx else "margin:6px 0 0;font-size:11px;color:#94a3b8;"}>{step_labels.get(step)}</p>
                        </div>
                        for step in steps
                    ]}
                </div>
                {status == "DECIDED" and (
                    <div style={decisionStyle}>
                        {decision}
                    </div>
                )}
            </div>
        );
    }
}

"""RefillCountdown component — prescription refill countdown indicator."""

cl {
    def:pub RefillCountdown(props: dict) -> JsxElement {
        days_remaining = props.get("daysRemaining", 0);
        drug_name = props.get("drugName", "");
        is_overdue = days_remaining < 0;

        color = "#22c55e" if days_remaining > 14 else "#f59e0b" if days_remaining > 0 else "#ef4444";
        label = f"{abs(days_remaining)} days overdue" if is_overdue else f"{days_remaining} days until refill";

        return (
            <div style="display:inline-flex;align-items:center;gap:8px;">
                <div style={f"width:36px;height:36px;border-radius:50%;background:{color}20;border:3px solid {color};display:flex;align-items:center;justify-content:center;"}>
                    <span style={f"font-size:11px;font-weight:700;color:{color};"}>{abs(days_remaining)}</span>
                </div>
                <div>
                    <p style="margin:0;font-size:12px;font-weight:500;color:#1e293b;">{drug_name}</p>
                    <p style={f"margin:2px 0 0;font-size:11px;color:{color};"}>{label}</p>
                </div>
            </div>
        );
    }
}

"""SubscriptionRow component — subscription item with classification badge and cancel toggle."""

cl {
    def:pub SubscriptionRow(props: dict) -> JsxElement {
        sub = props.get("subscription", {});
        on_cancel = props.get("onCancel");
        classification = sub.get("classification", "UNKNOWN");

