        def fmt(v: float) -> str {
            return f"{v:.2f}";
        }

        badgeBaseStyle = "padding:3px 8px;border-radius:9999px;font-size:11px;font-weight:600;";
        badgeColor = "background:#f0fdf4;color:#166534;" if classification == "ESSENTIAL" else ("background:#eff6ff;color:#1d4ed8;" if classification == "USEFUL" else ("background:#fef2f2;color:#dc2626;" if classification == "WASTEFUL" else "background:#f1f5f9;color:#64748b;"));
        badgeFullStyle = badgeBaseStyle + badgeColor;
        monthlyCostFmt = fmt(float(sub.get("monthly_cost", 0)));
