"""appointment_with edge — Appointment links to Provider."""

edge appointment_with {
    has department: str = "",
        reason_for_visit: str = "",
        referral_source: str = "";
}

"""authorized_by_hipaa edge — RecordsTransfer authorized by a HIPAA legal document."""

edge authorized_by_hipaa {
    has authorization_date: str = "",
        expiry_date: str = "";
}

"""covered_by edge — Patient → Policy."""

edge covered_by {
    has enrollment_date: str = "",
        termination_date: str = "";
}

"""escalated_to edge — Dispute → Appeal."""

edge escalated_to {
    has escalation_date: str = "",
        appeal_level: int = 1;
}

"""filled_at edge — Prescription filled at a Pharmacy."""

edge filled_at {
    has fill_date: str = "",
        fill_number: int = 1,
        copay_amount: float = 0.0;
}

"""Edge: Patient/Provider → Appointment."""

edge has_appointment {
    has scheduled_at: str = "",
        reminder_sent: bool = False;
}

"""has_beneficiary edge — Patient → BeneficiaryDesignation."""

edge has_beneficiary {
    has account_type: str = "";
}

"""has_benefits_eligibility edge — Patient linked to a BenefitsEligibility screening."""

edge has_benefits_eligibility {
    has screening_date: str = "",
        screening_method: str = "AUTOMATED";  # AUTOMATED | MANUAL
}

"""Edge: Patient → CareGap."""

edge has_care_gap {
    has detected_date: str = "",
        acknowledged: bool = False;
}

"""has_claim edge — Patient → Claim."""

edge has_claim {
    has service_period: str = "";
}

"""has_dispute edge — LineItem → Dispute."""

edge has_dispute {
    has flagged_date: str = "",
        error_category: str = "";
}

"""has_document edge — Patient → Document."""

edge has_document {
    has received_date: str = "",
        source_channel: str = "email";
}

"""Edge: Patient → BenefitsEligibility."""

edge has_eligibility {
    has screened_at: str = "";
}

"""has_eob edge — Claim → EOB."""

edge has_eob {
    has processing_date: str = "";
