"""Appointment tracking walker exports."""

import from graph.walkers.appointments.care_gap_detector { CareGapDetector }
import from graph.walkers.appointments.appointment_email_parser { AppointmentEmailParser }
import from graph.walkers.appointments.appointment_reminder { AppointmentReminder }

import from graph.nodes.patient { Patient }
import from graph.nodes.document { Document }
import from graph.nodes.appointment { Appointment }
import from abilities.llm_abilities { parse_appointment_email }

import from datetime { datetime }
import from uuid { uuid4 }


walker AppointmentEmailParser {
    """Walks Patient -> Documents, parses appointment confirmations."""

    has parsed: int = 0,
        skipped: int = 0,
        patient_ref: Patient = Patient(name="");

    can start with Patient entry {
        self.patient_ref = here;
        visit [-->];
    }

    can check_doc with Document entry {
        # Only process likely appointment-related documents
        classification = here.classification.upper();
        relevant_types = {"APPOINTMENT_CONFIRMATION", "EMAIL", "UNKNOWN"};
        if classification not in relevant_types and "APPOINTMENT" not in classification {
            disengage;
        }

        raw = here.raw_content if here.raw_content else here.plain_english_summary;
        if not raw {
            disengage;
        }

        email_subject: str = "";
        email_sender: str = "";
        result = parse_appointment_email(
            email_subject=email_subject,
            email_body=raw[:4000],
            sender=email_sender
        );

        if not result or not result.get("is_appointment_related", True) {
            self.skipped += 1;
            disengage;
        }

        appt_date = result.get("appointment_date", "");
        provider = result.get("provider_name", "");
        if not appt_date or not provider {
            self.skipped += 1;
            disengage;
        }

        # Check for duplicate (same provider + date)
        existing = [
            n for n in [self.patient_ref-->]
            if isinstance(n, Appointment)
            and n.appointment_date == appt_date
            and n.provider_name == provider
        ];
        if existing {
            self.skipped += 1;
            disengage;
        }

        appt = Appointment(
            appointment_id=str(uuid4()),
            appointment_date=appt_date,
            appointment_time=result.get("appointment_time", ""),
            provider_name=provider,
            facility_name=result.get("facility_name", ""),
            facility_address=result.get("facility_address", ""),
            specialty=result.get("specialty", ""),
            purpose=result.get("visit_purpose", ""),
            status="SCHEDULED",
            reminder_sent=False,
            notes=result.get("prep_instructions", ""),
            created_at=str(datetime.utcnow())
        );
        self.patient_ref ++> appt;
        self.parsed += 1;
        print(f"[AppointmentEmailParser] Parsed: {provider} on {appt_date}");
    }

    can finish with Patient entry {
        report {"parsed": self.parsed, "skipped": self.skipped};
    }
}

import from graph.nodes.patient { Patient }
import from graph.nodes.appointment { Appointment }
import from graph.nodes.notification { Notification }

import from datetime { datetime }
import from uuid { uuid4 }


walker AppointmentReminder {
    """Generates reminder notifications for upcoming appointments."""

    has reminders_sent: int = 0,
        lookahead_days: int = 14;

    can start with Patient entry {
        today_str: str = str(datetime.utcnow())[:10];
        appointments = [n for n in [here-->] if isinstance(n, Appointment) and n.status == "SCHEDULED"];

        for appt in appointments {
            if not appt.appointment_date {
                continue;
            }

            appt_date_str: str = str(appt.appointment_date);
            if appt_date_str < today_str {
                continue;
            }

            # Compute days_until by parsing dates
            now_dt: datetime = datetime.utcnow();
            appt_dt: datetime = datetime.strptime(appt_date_str, "%Y-%m-%d");
            delta = appt_dt - now_dt;
            days_until = delta.days;

            if days_until > self.lookahead_days {
                continue;
            }

            if days_until <= 3 and not appt.reminder_sent {
                if days_until <= 1 {
                    severity = "HIGH";
                    title = f"Appointment TOMORROW: {appt.provider_name}";
                } elif days_until == 0 {
                    severity = "CRITICAL";
                    title = f"Appointment TODAY: {appt.provider_name}";
                } else {
                    severity = "MEDIUM";
                    title = f"Upcoming Appointment in {days_until} days: {appt.provider_name}";
                }

                time_str = f" at {appt.appointment_time}" if appt.appointment_time else "";
                location_str = f" — {appt.facility_name}" if appt.facility_name else "";
                message = (
                    f"{appt.purpose or appt.specialty or 'Appointment'} with {appt.provider_name}"
                    f" on {appt.appointment_date}{time_str}{location_str}."
                );
                if appt.notes {
                    message += f" Notes: {appt.notes}";
                }

                notif = Notification(
                    notification_id=str(uuid4()),
                    notification_type="APPOINTMENT_REMINDER",
                    severity=severity,
                    title=title,
                    message=message,
                    metadata=str(appt.appointment_id),
                    created_at=str(datetime.utcnow()),
                    delivered_at="",
                    read_at=""
                );
                here ++> notif;
                appt.reminder_sent = True;
                self.reminders_sent += 1;
                print(f"[AppointmentReminder] Reminder created: {appt.provider_name} in {days_until} day(s)");
            }
        }

        report {"patient": here.name, "reminders_sent": self.reminders_sent};
    }
}

