"""BillDueDateTracker walker — tracks upcoming/overdue bills and alerts.

Walks all RecurringBill nodes, computes days until next payment,
flags overdue bills, and creates Notification nodes for the adult child.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.notification { Notification }
import from graph.walkers.bills.recurring_bill_detector { RecurringBill }

import from datetime { datetime, date }
import from uuid { uuid4 }

glob UPCOMING_WARNING_DAYS = 5;

walker BillDueDateTracker {

    can start with Patient entry {
        self.today = date.today();
        visit [-->];
    }

    can check_account with FinancialAccount entry {
        visit [-->];
    }

    can check_bill with RecurringBill entry {
        if here.due_day_of_month == 0 {
            disengage;
        }

        today = self.today;
        due_day = here.due_day_of_month;

        # Compute next due date
        if today.day <= due_day {
            next_due = date(today.year, today.month, due_day);
        } else {
            # Next month
            if today.month == 12 {
                next_due = date(today.year + 1, 1, due_day);
            } else {
                next_due = date(today.year, today.month + 1, due_day);
            }
        }

        days_until = (next_due - today).days;
        here.days_until_due = days_until;

        if days_until < 0 {
            here.status = "overdue";
            notif = Notification(
                notification_id=str(uuid4()),
                notification_type="BILL_OVERDUE",
                severity="URGENT",
                title=f"Bill Overdue: {here.biller_name}",
                message=(
                    f"{here.biller_name} bill of ${here.expected_amount:.2f} "
                    f"was due on the {due_day}th and hasn't been detected as paid."
                ),
                created_at=datetime.utcnow().isoformat()
            );
            here ++> notif;
            print(f"[BillDueDateTracker] OVERDUE: {here.biller_name} ${here.expected_amount:.2f}");

        } elif days_until <= UPCOMING_WARNING_DAYS {
            here.status = "upcoming";
            notif = Notification(
                notification_id=str(uuid4()),
                notification_type="BILL_OVERDUE",
                severity="WARNING",
                title=f"Bill Due Soon: {here.biller_name}",
                message=(
                    f"{here.biller_name} bill of ${here.expected_amount:.2f} "
                    f"is due in {days_until} day(s) (on the {due_day}th)."
                ),
                created_at=datetime.utcnow().isoformat()
            );
            here ++> notif;
        } else {
            here.status = "current";
        }
    }
}

"""MissedPaymentDetector walker — detects missed payments and late fees from transactions."""

import from graph.nodes.patient { Patient }
import from graph.nodes.recurring_bill { RecurringBill }
import from graph.nodes.transaction { Transaction }
import from graph.nodes.financial_account { FinancialAccount }
import from abilities.notification_sender { send_notification }
import from datetime { datetime }

walker MissedPaymentDetector {
    has missed_count: int = 0;

    can detect with Patient entry {
        bills = [n for n in [here-->] if isinstance(n, RecurringBill)];
        today = datetime.utcnow().isoformat()[:10];

        for bill in bills {
            if not bill.next_due_date or bill.next_due_date > today {
                continue;
            }
            # Check if a matching payment exists in transaction history
            found_payment = False;
            for acct in [here-->] {
                if not isinstance(acct, FinancialAccount) {
                    continue;
                }
                for txn in [acct-->] {
                    if not isinstance(txn, Transaction) {
                        continue;
                    }
                    if bill.biller_name.lower() in txn.merchant.lower() {
                        if txn.transaction_date >= bill.last_paid_date {
                            found_payment = True;
                            break;
                        }
                    }
                }
                if found_payment {
                    break;
                }
            }
            if not found_payment {
                self.missed_count += 1;
                send_notification(
                    patient_id=here.name,
                    channel="SMS",
                    message=f"Missed payment alert: {bill.biller_name} was due {bill.next_due_date}.",
                    severity="HIGH"
                );
            }
        }
        report {"patient": here.name, "missed_payments": self.missed_count};
    }
}

"""PaymentAnomalyDetector walker — flags unusual payment amounts or unexpected billers."""

import from graph.nodes.patient { Patient }
import from graph.nodes.recurring_bill { RecurringBill }
import from graph.nodes.transaction { Transaction }
import from graph.nodes.financial_account { FinancialAccount }
import from graph.nodes.scam_alert { ScamAlert }
import from abilities.notification_sender { send_notification }
import from datetime { datetime }
import from uuid { uuid4 }

walker PaymentAnomalyDetector {
    has anomalies_found: int = 0,
        threshold_multiplier: float = 2.0;

    can detect with Patient entry {
        bills = [n for n in [here-->] if isinstance(n, RecurringBill)];
        bill_map: dict = {b.biller_name.lower(): b.expected_amount for b in bills};

        for acct in [here-->] {
            if not isinstance(acct, FinancialAccount) {
                continue;
            }
            for txn in [acct-->] {
                if not isinstance(txn, Transaction) or txn.amount >= 0 {
                    continue;
                }
                amt = abs(txn.amount);
                merchant_lower = txn.merchant.lower();
                matched_biller = None;
                for biller in bill_map {
                    if biller in merchant_lower {
                        matched_biller = biller;
                        break;
                    }
                }
                if matched_biller {
                    expected = bill_map[matched_biller];
                    if expected > 0 and amt > expected * self.threshold_multiplier {
                        self.anomalies_found += 1;
                        alert = ScamAlert(
                            alert_id=str(uuid4()),
                            alert_type="PAYMENT_ANOMALY",
                            description=f"Unusual charge: {txn.merchant} charged ${amt:.2f} (expected ~${expected:.2f})",
                            confidence_score=0.8,
                            detected_date=datetime.utcnow().isoformat()
                        );
                        root ++> alert;
                    }
                }
            }
        }

        report {"patient": here.name, "anomalies_found": self.anomalies_found};
    }
}

"""PriorAuthTracker walker — tracks expiring prior authorizations and denied auths."""

import from graph.nodes.patient { Patient }
import from graph.nodes.prior_auth { PriorAuth }
import from graph.nodes.notification { Notification }

import from datetime { datetime, timedelta }
import from uuid { uuid4 }

glob EXPIRY_WARN_DAYS: int = 14;

walker PriorAuthTracker {

    can start with Patient entry {
        self.today = datetime.utcnow();
        self.alerts = 0;
        visit [-->];
    }

    can track with PriorAuth entry {
        if here.status == "EXPIRED" or here.status == "WITHDRAWN" {
            disengage;
        }

        # Check for expiring approved auths
        if here.status == "APPROVED" and here.expiry_date != "" {
            try {
                expiry = datetime.strptime(here.expiry_date, "%Y-%m-%d");
                days_left = (expiry - self.today).days;
                if 0 <= days_left <= EXPIRY_WARN_DAYS {
                    notif = Notification(
                        notification_id=str(uuid4()),
                        notification_type="ACTION_REQUIRED",
                        severity="URGENT" if days_left <= 7 else "WARNING",
                        title=f"Prior Auth Expiring: {here.service_requested}",
                        message=(
                            f"Prior authorization #{here.auth_number} for {here.service_requested} "
                            f"expires in {days_left} day(s) on {here.expiry_date}. "
                            f"Contact {here.requesting_provider} to renew if still needed."
                        ),
                        created_at=datetime.utcnow().isoformat()
                    );
                    here ++> notif;
                    self.alerts += 1;
                    print(f"[PriorAuthTracker] Auth expiring in {days_left} days: {here.auth_number}");
                }
            } except Exception as e {
                print(f"[PriorAuthTracker] Date error: {e}");
            }
        }

        # Check for denied auths still within appeal window
        if here.status == "DENIED" and here.appeal_deadline != "" {
            try {
                deadline = datetime.strptime(here.appeal_deadline, "%Y-%m-%d");
                days_left = (deadline - self.today).days;
                if 0 < days_left <= 30 {
                    notif = Notification(
                        notification_id=str(uuid4()),
                        notification_type="APPEAL_DEADLINE",
                        severity="URGENT" if days_left <= 7 else "WARNING",
                        title=f"Prior Auth Appeal Deadline: {here.service_requested}",
                        message=(
                            f"Prior authorization for {here.service_requested} was denied by {here.insurer_name}. "
                            f"Appeal deadline: {here.appeal_deadline} ({days_left} days). "
                            f"Reason: {here.denial_reason}"
                        ),
                        created_at=datetime.utcnow().isoformat()
                    );
                    here ++> notif;
                    self.alerts += 1;
                    print(f"[PriorAuthTracker] Appeal window closing: {here.auth_number}");
                }
            } except Exception as e {
                print(f"[PriorAuthTracker] Date error: {e}");
            }
        }
    }

    can finish with Patient entry {
        report {"alerts_generated": self.alerts};
    }
}

"""RecurringBillDetector walker — identifies recurring bills from Plaid transactions.

Walks a patient's FinancialAccount nodes, analyzes the transaction history
to identify recurring charges (same merchant, similar amount, regular cadence),
and creates RecurringBill nodes for each.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.financial_account { FinancialAccount }
import from graph.nodes.transaction { Transaction }

import from collections { defaultdict }
import from datetime { datetime }
import from uuid { uuid4 }
import from statistics { mean }

# A charge is considered recurring if it appears ≥ 2 times
# with similar amounts (within 20%)
glob MIN_OCCURRENCES = 2;
glob AMOUNT_VARIANCE_THRESHOLD = 0.20;

node RecurringBill {
    has bill_id: str = "",
        biller_name: str = "",
        category: str = "subscription",
        expected_amount: float = 0.0,
        amount_variance_pct: float = 0.0,
        due_day_of_month: int = 0,
        frequency: str = "monthly",
        last_paid_date: str = "",
        last_paid_amount: float = 0.0,
        status: str = "current",
        days_until_due: int = 0,
        source_account_id: str = "";
}

walker RecurringBillDetector {

    can start with Patient entry {
        visit [-->];
    }

    can scan_account with FinancialAccount entry {
        transactions = [__n for __n in [t for t in [here-->] if isinstance(__n, Transaction)]];
        if len(transactions) == 0 {
            disengage;
        }

        # Group transactions by merchant
        by_merchant = defaultdict(list);
        for t in transactions {
            merchant = t.merchant_name.strip().upper()[:50];
            if merchant {
                by_merchant[merchant].append(t);
            }
        }

        # Identify recurring charges
        for merchant, txns in by_merchant.items() {
            if len(txns) < MIN_OCCURRENCES {
                continue;
            }

            amounts = [abs(t.amount) for t in txns if t.amount != 0];
            if len(amounts) == 0 {
                continue;
            }

            avg_amount = mean(amounts);
            if avg_amount < 1.0 {
                continue;
            }

            # Check variance (all amounts within 20% of mean)
            variance = max(abs(a - avg_amount) / avg_amount for a in amounts) if avg_amount > 0 else 1;
            if variance > AMOUNT_VARIANCE_THRESHOLD {
                continue;  # Too variable — not a regular bill
            }

            # Find payment day of month
            dates = sorted([t.date for t in txns]);
            day = int(dates[-1].split("-")[2]) if dates else 1;

            # Check if already tracked
            existing = [__n for __n in [b for b in [here-->] if isinstance(__n, RecurringBill)] if b.biller_name.upper() == merchant];
            if len(existing) > 0 {
                # Update existing
                existing[0].last_paid_date = dates[-1];
                existing[0].last_paid_amount = amounts[-1] if amounts else 0;
                continue;
            }

            bill = RecurringBill(
                bill_id=str(uuid4()),
                biller_name=txns[0].merchant_name or merchant,
                category="subscription",
                expected_amount=round(avg_amount, 2),
                amount_variance_pct=round(variance * 100, 1),
                due_day_of_month=day,
                frequency="monthly",
                last_paid_date=dates[-1] if dates else "",
                last_paid_amount=round(amounts[-1] if amounts else 0, 2),
                status="current",
                source_account_id=here.plaid_account_id
            );
            here ++> bill;
            print(f"[RecurringBillDetector] Found recurring: {merchant} ~${avg_amount:.2f}/mo");
        }
    }
}

