"""Prescription & medication walker exports."""

import from graph.walkers.prescriptions.medication_list_builder { MedicationListBuilder }
import from graph.walkers.prescriptions.drug_interaction_checker { DrugInteractionChecker }
import from graph.walkers.prescriptions.refill_monitor { RefillMonitor }

import from graph.nodes.patient { Patient }
import from graph.nodes.medication { Medication }
import from graph.nodes.notification { Notification }
import from abilities.llm_abilities { check_drug_interactions }

import from datetime { datetime }
import from uuid { uuid4 }

glob SEVERITY_TO_NOTIFICATION_LEVEL: dict = {
    "CONTRAINDICATED": "CRITICAL",
    "SERIOUS": "HIGH",
    "MODERATE": "MEDIUM",
    "MINOR": "LOW"
};


walker DrugInteractionChecker {
    has interactions_found: int = 0;

    can start with Patient entry {
        medications = [n for n in [here-->] if isinstance(n, Medication) and n.active];

        if len(medications) < 2 {
            report {"patient": here.name, "interactions_found": 0, "message": "Fewer than 2 active medications"};
            disengage;
        }

        med_names = [f"{m.drug_name} ({m.generic_name}) {m.strength}".strip("() ") for m in medications];

        interactions = check_drug_interactions(medication_names=med_names);

        if not interactions {
            print(f"[DrugInteractionChecker] No interactions found for {here.name}");
            report {"patient": here.name, "interactions_found": 0};
            disengage;
        }

        for interaction in interactions {
            drug_a: str = str(interaction.get("drug_a", ""));
            drug_b: str = str(interaction.get("drug_b", ""));
            severity: str = str(interaction.get("severity", "MODERATE"));
            mechanism: str = str(interaction.get("mechanism", ""));
            clinical_effect: str = str(interaction.get("clinical_effect", ""));
            recommendation: str = str(interaction.get("recommendation", "Contact prescriber."));

            notif_level = SEVERITY_TO_NOTIFICATION_LEVEL.get(severity, "MEDIUM");
            title = f"Drug Interaction ({severity}): {drug_a} + {drug_b}";
            message = (
                f"Potential {severity.lower()} interaction between {drug_a} and {drug_b}. "
                f"{clinical_effect} {recommendation}"
            );
            if mechanism {
                message += f" Mechanism: {mechanism}";
            }

            notif = Notification(
                notification_id=str(uuid4()),
                notification_type="DRUG_INTERACTION",
                severity=notif_level,
                title=title,
                message=message,
                created_at=str(datetime.utcnow()),
                delivered_at="",
                read_at=""
            );
            here ++> notif;
            self.interactions_found += 1;
            print(f"[DrugInteractionChecker] {severity} interaction: {drug_a} + {drug_b}");
        }

        report {"patient": here.name, "interactions_found": self.interactions_found};
    }
}

import from graph.nodes.patient { Patient }
import from graph.nodes.prescription { Prescription }
import from graph.nodes.medication { Medication }

import from datetime { datetime }
import from uuid { uuid4 }


def _compute_next_fill(last_filled: str, days_supply: int) -> list {
    if not last_filled {
        return ["", -1];
    }
    try {
        filled_dt: datetime = datetime.strptime(last_filled, "%Y-%m-%d");
        now_dt: datetime = datetime.utcnow();
        delta = now_dt - filled_dt;
        days_since: int = delta.days;
        days_until: int = days_supply - days_since;
        next_fill_str: str = str(filled_dt)[:10];
        return [next_fill_str, days_until];
    } except Exception {
        return ["", 0];
    }
}


walker MedicationListBuilder {
    has built: int = 0,
        updated: int = 0;

    can start with Patient entry {
        prescriptions = [n for n in [here-->] if isinstance(n, Prescription) and n.status == "ACTIVE"];

        existing_meds: dict = {};
        for n in [here-->] {
            if isinstance(n, Medication) {
                existing_meds[n.generic_name.lower()] = n;
            }
        }

        for rx in prescriptions {
            key = (rx.generic_name or rx.drug_name).lower().strip();
            if not key {
                continue;
            }

            fill_result = _compute_next_fill(str(rx.fill_date), int(rx.days_supply));
            next_fill_date: str = str(fill_result[0]);
            days_until: int = int(fill_result[1]);

            if key in existing_meds {
                med = existing_meds[key];
                med.last_filled = str(rx.fill_date) or med.last_filled;
                med.days_supply = int(rx.days_supply);
                med.refills_remaining = int(rx.refills_remaining);
                med.next_fill_due = next_fill_date;
                med.days_until_refill = days_until;
                med.prescribing_provider = str(rx.prescriber_name) or med.prescribing_provider;
                med.pharmacy_name = str(rx.pharmacy_name) or med.pharmacy_name;
                self.updated += 1;
            } else {
                med = Medication(
                    medication_id=str(uuid4()),
                    drug_name=str(rx.drug_name),
                    generic_name=str(rx.generic_name or rx.drug_name),
                    ndc=str(rx.ndc_code),
                    strength=str(rx.dosage),
                    form="",
                    therapeutic_class="",
                    active_ingredient=str(rx.generic_name or rx.drug_name),
                    prescribing_provider=str(rx.prescriber_name),
                    pharmacy_name=str(rx.pharmacy_name),
                    last_filled=str(rx.fill_date),
                    days_supply=int(rx.days_supply),
                    refills_remaining=int(rx.refills_remaining),
                    next_fill_due=next_fill_date,
                    days_until_refill=days_until,
                    known_interactions=[],
                    active=True,
                    created_at=str(datetime.utcnow())
                );
                here ++> med;
                existing_meds[key] = med;
                self.built += 1;
                print(f"[MedicationListBuilder] Added: {med.drug_name} ({med.generic_name})");
            }
        }

        report {"patient": here.name, "built": self.built, "updated": self.updated};
    }
}

"""PharmacyBenefitChecker walker — checks prescriptions against Part D formulary."""

import from graph.nodes.patient { Patient }
import from graph.nodes.prescription { Prescription }
import from abilities.llm_abilities { check_formulary_coverage }
import from abilities.notification_sender { send_notification }

walker PharmacyBenefitChecker {
    has issues_found: int = 0;

    can check with Patient entry {
        for med in [here-->] {
            for rx in [med-->] {
                if not isinstance(rx, Prescription) or not rx.is_active {
                    continue;
                }
                result = check_formulary_coverage(
                    drug_name=rx.drug_name,
                    ndc=rx.ndc,
                    plan_type="PART_D"
                );
                if result.get("tier_changed") or result.get("not_covered") {
                    self.issues_found += 1;
                    send_notification(
                        patient_id=here.name,
                        channel="EMAIL",
                        message=f"Formulary alert for {rx.drug_name}: {result.get('message', '')}",
                        severity="MEDIUM"
                    );
            }
        }
        }
        report {"patient": here.name, "formulary_issues": self.issues_found};
    }
}

"""PrescriptionEmailParser walker — detects pharmacy notifications in emails."""

import from graph.nodes.patient { Patient }
import from graph.nodes.document { Document }
import from abilities.llm_abilities { extract_pharmacy_notification }

walker PrescriptionEmailParser {
    has notifications_processed: int = 0;

    can parse with Patient entry {
        docs = [
            n for n in [here-->]
            if isinstance(n, Document)
            and n.classification in ["PHARMACY_NOTIFICATION", "REFILL_REMINDER"]
            and not n.processed
        ];
        for doc in docs {
            result = extract_pharmacy_notification(email_text=doc.raw_text);
            if result.get("drug_name") {
                # Update matching prescription if found
                drug = result.get("drug_name", "");
                action = result.get("action", "");  # READY_FOR_PICKUP | REFILL_REMINDER | SHIPPED
                print(f"[PrescriptionEmailParser] {drug}: {action}");
                doc.processed = True;
                self.notifications_processed += 1;
            }
        }
        report {"notifications_processed": self.notifications_processed};
    }
}

"""PriorAuthFollowup walker — follows up on stalled prior authorization requests."""

import from graph.nodes.patient { Patient }
import from graph.nodes.prior_auth { PriorAuth }
import from graph.nodes.phone_call { PhoneCall }
import from datetime { datetime, timedelta }
import from uuid { uuid4 }

walker PriorAuthFollowup {
    has stall_days: int = 5,
        followups_queued: int = 0;

    can followup with Patient entry {
        today = datetime.utcnow().date();
        cutoff = (today - timedelta(days=self.stall_days)).isoformat();

        for med in [here-->] {
            for rx in [med-->] {
                for pa in [rx-->] {
                    if not isinstance(pa, PriorAuth) {
                        continue;
                    }
                    if pa.status != "PENDING" {
                        continue;
                    }
                    if pa.requested_date and pa.requested_date <= cutoff {
                        call = PhoneCall(
                            call_id=str(uuid4()),
                            call_type="PRIOR_AUTH_FOLLOWUP",
                            purpose=f"Follow up on prior auth {pa.auth_number} for {here.name}",
                            status="QUEUED",
                            created_at=datetime.utcnow().isoformat()
                        );
                        root ++> call;
                        self.followups_queued += 1;
                    }
                }
            }
        }

        report {"patient": here.name, "followups_queued": self.followups_queued};
    }
}

"""RefillMonitor walker — flags prescriptions approaching or past their refill date.

Walks Patient -> Prescription nodes, computes days until refill based on
fill_date + days_supply, and creates Notification nodes for anything due
within 7 days or already overdue.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.prescription { Prescription }
import from graph.nodes.medication { Medication }
import from graph.nodes.notification { Notification }

import from datetime { datetime, timedelta }
import from uuid { uuid4 }

glob WARN_DAYS: int = 7;   # Alert when refill is due within this many days
glob URGENT_DAYS: int = 0; # Alert as URGENT when at or past due date


def _days_until_refill(fill_date: str, days_supply: int) -> int {
    """Returns days until refill is due. Negative = overdue."""
    if not fill_date {
        return 999;
    }
    try {
        filled_dt = datetime.strptime(fill_date, "%Y-%m-%d");
        refill_due = filled_dt + timedelta(days=days_supply);
        return (refill_due - datetime.utcnow()).days;
    } except Exception {
        return 999;
    }
}


walker RefillMonitor {
    """Creates notifications for prescriptions due for refill soon or overdue."""

    has overdue_count: int = 0,
        due_soon_count: int = 0;

    can start with Patient entry {
        prescriptions = [n for n in [here-->] if isinstance(n, Prescription) and n.status == "ACTIVE"];

        # Also check Medication nodes (in case MedicationListBuilder ran first)
        medications = [n for n in [here-->] if isinstance(n, Medication) and n.active];

        checked = set();

        for rx in prescriptions {
            key = (rx.generic_name or rx.drug_name or rx.prescription_id).lower();
            if key in checked {
                continue;
            }
            checked.add(key);

            days_left = _days_until_refill(rx.fill_date, rx.days_supply);

            if days_left > WARN_DAYS {
                continue;
            }

            drug_label = rx.drug_name or rx.generic_name or "medication";

            if days_left < 0 {
                severity = "HIGH";
                title = f"Refill Overdue: {drug_label}";
                message = (
                    f"{drug_label} ({rx.dosage}) was due for refill {abs(days_left)} day(s) ago. "
                    f"Refills remaining: {rx.refills_remaining}. "
                    f"Pharmacy: {rx.pharmacy_name or 'on file'}."
                );
                self.overdue_count += 1;
            } else {
                severity = "MEDIUM";
                title = f"Refill Due Soon: {drug_label}";
                message = (
                    f"{drug_label} ({rx.dosage}) is due for refill in {days_left} day(s). "
                    f"Refills remaining: {rx.refills_remaining}. "
                    f"Pharmacy: {rx.pharmacy_name or 'on file'}."
                );
                self.due_soon_count += 1;
            }

            notif = Notification(
                notification_id=str(uuid4()),
                notification_type="REFILL_REMINDER",
                severity=severity,
                title=title,
                message=message,
                reference_id=rx.prescription_id,
                created_at=datetime.utcnow().isoformat(),
                delivered_at="",
                read_at=""
            );
            here ++> notif;
            print(f"[RefillMonitor] {title} (days_left={days_left})");
        }

        report {
            "patient": here.name,
            "overdue": self.overdue_count,
            "due_soon": self.due_soon_count
        };
    }
}

"""RefillTracker walker — monitors active prescriptions and flags overdue refills."""

import from graph.nodes.patient { Patient }
import from graph.nodes.prescription { Prescription }
import from abilities.notification_sender { send_notification }
import from datetime { datetime }

walker RefillTracker {
    has overdue_count: int = 0,
        due_soon_count: int = 0,
        days_warning: int = 7;

    can track with Patient entry {
        today = datetime.utcnow().isoformat()[:10];

        for med in [here-->] {
            for rx in [med-->] {
                if not isinstance(rx, Prescription) {
                    continue;
                }
                if rx.refills_remaining <= 0 or not rx.is_active {
                    continue;
                }
                if rx.next_fill_due and rx.next_fill_due < today {
                    self.overdue_count += 1;
                    send_notification(
                        patient_id=here.name,
                        channel="SMS",
                        message=f"Refill overdue: {rx.drug_name}. Last filled: {rx.last_fill_date}.",
                        severity="HIGH"
                    );
                }
            }
        }

        report {
            "patient": here.name,
            "overdue_refills": self.overdue_count,
            "due_soon": self.due_soon_count
        };
    }
}

