"""Embedding generator — creates vector embeddings for documents via OpenAI."""

import from os { environ }

glob EMBEDDING_MODEL: str = "text-embedding-3-small";
glob EMBEDDING_DIM: int = 1536;
glob MAX_CHARS: int = 32000;

def generate_embedding(text: str) -> list[float] {
    """
    Generate a vector embedding for a text chunk.
    Returns list of floats (embedding vector) or empty list on failure.
    """
    if text.strip() == "" {
        return [];
    }
    truncated = text[:MAX_CHARS];
    try {
        import from openai { OpenAI }
        client = OpenAI(api_key=environ.get("OPENAI_API_KEY", ""));
        resp = client.embeddings.create(input=truncated, model=EMBEDDING_MODEL);
        return resp.data[0].embedding;
    } except Exception as e {
        print(f"[Embedding] Generation failed: {e}");
        return [];
    }
}

def generate_batch_embeddings(texts: list[str]) -> list[list[float]] {
    """
    Generate embeddings for a batch of texts.
    Returns list of embedding vectors (empty list for failed items).
    """
    if len(texts) == 0 {
        return [];
    }
    try {
        import from openai { OpenAI }
        client = OpenAI(api_key=environ.get("OPENAI_API_KEY", ""));
        cleaned = [];
        for t in texts {
            if len(t) > MAX_CHARS {
                cleaned.append(t[:MAX_CHARS]);
            } else {
                cleaned.append(t);
            }
        }
        resp = client.embeddings.create(input=cleaned, model=EMBEDDING_MODEL);
        result = [];
        for item in resp.data {
            result.append(item.embedding);
        }
        return result;
    } except Exception as e {
        print(f"[Embedding] Batch generation failed: {e}");
        empty = [];
        for _ in texts {
            empty.append([]);
        }
        return empty;
    }
}

def cosine_similarity(vec_a: list[float], vec_b: list[float]) -> float {
    """Compute cosine similarity between two embedding vectors."""
    if len(vec_a) == 0 or len(vec_b) == 0 or len(vec_a) != len(vec_b) {
        return 0.0;
    }
    try {
        import from math { sqrt }
        dot = 0.0;
        for i in range(len(vec_a)) {
            dot += vec_a[i] * vec_b[i];
        }
        sum_a = 0.0;
        for val in vec_a {
            sum_a += val * val;
        }
        sum_b = 0.0;
        for val in vec_b {
            sum_b += val * val;
        }
        mag_a = sqrt(sum_a);
        mag_b = sqrt(sum_b);
        if mag_a == 0.0 or mag_b == 0.0 {
            return 0.0;
        }
        return dot / (mag_a * mag_b);
    } except Exception {
        return 0.0;
    }
}

"""OCR processor — converts scanned document images to text via Tesseract or AWS Textract."""

import from os { environ }

glob OCR_ENGINE: str = "tesseract";

def ocr_image_file(file_path: str) -> str {
    """Run OCR on an image file and return extracted text."""
    engine = environ.get("OCR_ENGINE", OCR_ENGINE);
    if engine == "textract" {
        return _textract_ocr(file_path);
    }
    return _tesseract_ocr(file_path);
}

def _tesseract_ocr(file_path: str) -> str {
    """Run Tesseract OCR on a file."""
    try {
        import from pytesseract { image_to_string }
        import from PIL.Image { open as pil_open }
        img = pil_open(file_path);
        text = image_to_string(img, config="--oem 3 --psm 6");
        return text.strip();
    } except Exception as e {
        print(f"[OCR] Tesseract failed for {file_path}: {e}");
        return "";
    }
}

def _textract_ocr(file_path: str) -> str {
    """Run AWS Textract OCR on a file."""
    try {
        import from boto3 { client }
        textract = client("textract", region_name=environ.get("AWS_REGION", "us-east-1"));
        file_bytes = open(file_path, "rb").read();
        response = textract.detect_document_text(Document={"Bytes": file_bytes});
        lines = [];
        for block in response.get("Blocks", []) {
            if block.get("BlockType") == "LINE" {
                lines.append(block.get("Text", ""));
            }
        }
        return "\n".join(lines);
    } except Exception as e {
        print(f"[OCR] Textract failed for {file_path}: {e}");
        return "";
    }
}

def ocr_pdf_pages(pdf_path: str, max_pages: int = 10) -> str {
    """
    Convert PDF to images and OCR each page.
    Requires pdf2image and poppler.
    """
    try {
        import from pdf2image { convert_from_path }
        import from pytesseract { image_to_string }
        pages = convert_from_path(pdf_path, first_page=1, last_page=max_pages, dpi=300);
        all_text = [];
        page_num = 0;
        for page in pages {
            page_num += 1;
            try {
                text = image_to_string(page, config="--oem 3 --psm 6");
                all_text.append(f"=== Page {page_num} ===\n" + text.strip());
            } except Exception as pe {
                print(f"[OCR] Page {page_num} OCR failed: {pe}");
            }
        }
        return "\n\n".join(all_text);
    } except Exception as e {
        print(f"[OCR] PDF OCR failed for {pdf_path}: {e}");
        return "";
    }
}

"""PDF text extractor — extracts text from selectable PDFs via pdfplumber."""

def extract_text_from_pdf(pdf_path: str, max_pages: int = 20) -> str {
    """Extract text from a selectable PDF using pdfplumber."""
    try {
        import from pdfplumber { open as pdf_open }
        pdf = pdf_open(pdf_path);
        all_text = [];
        page_num = 0;
        for page in pdf.pages {
            if page_num >= max_pages {
                break;
            }
            page_num += 1;
            text = page.extract_text();
            if text {
                all_text.append(f"=== Page {page_num} ===\n" + text.strip());
            }
        }
        pdf.close();
        return "\n\n".join(all_text);
    } except Exception as e {
        print(f"[PDFExtractor] Extraction failed for {pdf_path}: {e}");
        return "";
    }
}

def extract_tables_from_pdf(pdf_path: str, max_pages: int = 20) -> list[list] {
    """Extract tables from a PDF as list of lists."""
    try {
        import from pdfplumber { open as pdf_open }
        pdf = pdf_open(pdf_path);
        all_tables = [];
        page_num = 0;
        for page in pdf.pages {
            if page_num >= max_pages {
                break;
            }
            page_num += 1;
            tables = page.extract_tables();
            for table in tables {
                all_tables.append(table);
            }
        }
        pdf.close();
        return all_tables;
    } except Exception as e {
        print(f"[PDFExtractor] Table extraction failed for {pdf_path}: {e}");
        return [];
    }
}

def is_selectable_pdf(pdf_path: str) -> bool {
    """Return True if the PDF contains selectable text."""
    try {
        import from pdfplumber { open as pdf_open }
        pdf = pdf_open(pdf_path);
        if len(pdf.pages) == 0 {
            pdf.close();
            return False;
        }
        text = pdf.pages[0].extract_text();
        pdf.close();
        return text is not None and len(text.strip()) > 50;
    } except Exception {
        return False;
    }
}

"""Email parser — extracts structured data from raw email messages."""

def parse_email_message(raw_email: bytes) -> dict {
    """
    Parse a raw email message into structured fields.
    Returns dict with subject, sender, body_text, attachments, etc.
    """
    try {
        import from email { message_from_bytes }
        import from email.header { decode_header }
        msg = message_from_bytes(raw_email);
        # Decode subject
        raw_subject = msg.get("Subject", "");
        subject_parts = decode_header(raw_subject);
        subject = "";
        for part, enc in subject_parts {
            if isinstance(part, bytes) {
                subject += part.decode(enc or "utf-8", errors="replace");
            } else {
                subject += part;
            }
        }
        # Extract sender
        sender = msg.get("From", "");
        date_str = msg.get("Date", "");
        # Extract body and attachments
        body_text = "";
        attachments = [];
        if msg.is_multipart() {
            for part in msg.walk() {
                content_type = part.get_content_type();
                content_disp = str(part.get("Content-Disposition", ""));
                if "attachment" in content_disp {
                    filename = part.get_filename() or "attachment";
                    attachments.append({
                        "filename": filename,
                        "content_type": content_type,
                        "data": part.get_payload(decode=True)
                    });
                } elif content_type == "text/plain" and "attachment" not in content_disp {
                    payload = part.get_payload(decode=True);
                    if payload {
                        charset = part.get_content_charset() or "utf-8";
                        body_text += payload.decode(charset, errors="replace");
                    }
                }
            }
        } else {
            payload = msg.get_payload(decode=True);
            if payload {
                charset = msg.get_content_charset() or "utf-8";
                body_text = payload.decode(charset, errors="replace");
            }
        }
        return {
            "subject": subject,
            "sender": sender,
            "date": date_str,
            "body_text": body_text.strip(),
            "attachments": attachments
        };
    } except Exception as e {
        print(f"[EmailParser] Parse failed: {e}");
        return {"subject": "", "sender": "", "date": "", "body_text": "", "attachments": []};
    }
}

def is_healthcare_email(subject: str, body: str) -> bool {
    """Quick heuristic to detect if an email is healthcare/insurance-related."""
    keywords = [
        "medicare", "medicaid", "explanation of benefits", "eob",
        "claim", "insurance", "provider", "hospital", "prescription",
        "medicare summary notice", "msn", "statement", "remittance"
    ];
    combined = (subject + " " + body).lower();
    return any(kw in combined for kw in keywords);
}

"""Email sender — sends transactional emails via SendGrid or SMTP."""

import from os { environ }

def send_email(to_address: str, subject: str, body_text: str, body_html: str = "") -> bool {
    """
    Send a transactional email.
    Uses SendGrid if SENDGRID_API_KEY is set, otherwise falls back to SMTP.
    Returns True on success.
    """
    sendgrid_key = environ.get("SENDGRID_API_KEY", "");
    if sendgrid_key != "" {
        return _send_via_sendgrid(to_address, subject, body_text, body_html, sendgrid_key);
    }
    return _send_via_smtp(to_address, subject, body_text);
}

def _send_via_sendgrid(to_address: str, subject: str, body_text: str, body_html: str, api_key: str) -> bool {
    """Send email via SendGrid API."""
    try {
        import from sendgrid { SendGridAPIClient }
        import from sendgrid.helpers.mail { Mail }
        from_email = environ.get("EMAIL_FROM", "noreply@agewise.ai");
        message = Mail(
            from_email=from_email,
            to_emails=to_address,
            subject=subject,
            plain_text_content=body_text,
            html_content=body_html if body_html != "" else f"<pre>{body_text}</pre>"
        );
        sg = SendGridAPIClient(api_key);
        response = sg.send(message);
        success = response.status_code in [200, 202];
        print(f"[Email] Sent via SendGrid to {to_address}: status {response.status_code}");
        return success;
    } except Exception as e {
        print(f"[Email] SendGrid failed: {e}");
        return False;
    }
}

def _send_via_smtp(to_address: str, subject: str, body_text: str) -> bool {
    """Send email via SMTP."""
    try {
        import from smtplib { SMTP }
        import from email.mime.text { MIMEText }
        import from email.mime.multipart { MIMEMultipart }
        smtp_host = environ.get("SMTP_HOST", "localhost");
        smtp_port = int(environ.get("SMTP_PORT", "587"));
        smtp_user = environ.get("SMTP_USER", "");
        smtp_pass = environ.get("SMTP_PASS", "");
        from_email = environ.get("EMAIL_FROM", "noreply@agewise.ai");
        msg = MIMEMultipart();
        msg["From"] = from_email;
        msg["To"] = to_address;
        msg["Subject"] = subject;
        msg.attach(MIMEText(body_text, "plain"));
        with SMTP(smtp_host, smtp_port) as server {
            if smtp_user != "" {
                server.starttls();
                server.login(smtp_user, smtp_pass);
            }
            server.sendmail(from_email, to_address, msg.as_string());
        }
        print(f"[Email] Sent via SMTP to {to_address}");
        return True;
    } except Exception as e {
        print(f"[Email] SMTP failed: {e}");
        return False;
    }
}

def send_appeal_letter_email(to_address: str, dispute_id: str, letter_content: str) -> bool {
    """Send an appeal letter draft by email."""
    subject = f"AgeWise — Appeal Letter Draft (Dispute {dispute_id})";
    body = f"Please review the attached appeal letter draft.\n\n{letter_content}\n\nNote: This draft requires attorney review before submission.";
    return send_email(to_address, subject, body);
}

"""IMAP email connector — monitors patient/child email for incoming documents.

Uses Python's imaplib to connect to a Gmail or other IMAP account,
fetches unread emails with attachments, extracts text content.
"""

import from os { environ }
import from imaplib { IMAP4_SSL }
import from email { message_from_bytes }
import from email.header { decode_header }

can fetch_new_emails(
    host: str = "",
    port: int = 993,
    username: str = "",
    password: str = "",
    folder: str = "INBOX",
    max_emails: int = 20
) -> list[dict] {
    """Fetch unread emails and return list of dicts with subject, body, attachments_text."""
    h = host or environ.get("IMAP_HOST", "imap.gmail.com");
    p = port or int(environ.get("IMAP_PORT", "993"));
    u = username or environ.get("IMAP_USER", "");
    pw = password or environ.get("IMAP_PASSWORD", "");

    if u == "" or pw == "" {
        print("[IMAPConnector] IMAP credentials not configured, skipping email fetch");
        return [];
    }

    try {
        mail = IMAP4_SSL(h, p);
        mail.login(u, pw);
        mail.select(folder);

        # Search for unread messages
        status, data = mail.search(None, "UNSEEN");
        if status != "OK" {
            return [];
        }

        email_ids = data[0].split();
        results = [];

        for eid in email_ids[-max_emails:] {
            status, msg_data = mail.fetch(eid, "(RFC822)");
            if status != "OK" {
                continue;
            }

            msg = message_from_bytes(msg_data[0][1]);

            # Decode subject
            subject_raw = msg.get("Subject", "");
            decoded = decode_header(subject_raw);
            subject = "";
            for part, enc in decoded {
                if isinstance(part, bytes) {
                    subject += part.decode(enc or "utf-8", errors="replace");
                } else {
                    subject += str(part);
                }
            }

            sender = msg.get("From", "");
            body = "";

            # Extract body
            if msg.is_multipart() {
                for part in msg.walk() {
                    if part.get_content_type() == "text/plain" {
                        try {
                            body += part.get_payload(decode=True).decode("utf-8", errors="replace");
                        } except { pass; }
                    }
                }
            } else {
                try {
                    body = msg.get_payload(decode=True).decode("utf-8", errors="replace");
                } except { pass; }
            }

            results.append({
                "subject": subject,
                "sender": sender,
                "body": body,
                "attachments_text": "",
                "email_id": eid.decode()
            });

            # Mark as read
            mail.store(eid, "+FLAGS", "\\Seen");
        }

        mail.logout();
        return results;
    } except Exception as e {
        print(f"[IMAPConnector] Error fetching emails: {e}");
        return [];
    }
}

"""MX Technologies client — alternative to Plaid for financial data aggregation."""

import from os { environ }

glob MX_BASE_URL: str = "https://int-api.mx.com";  # Atrium API
glob MX_PROD_URL: str = "https://api.mx.com";

def get_base_url() -> str {
    """Return the MX API base URL based on environment."""
    if environ.get("APP_ENV") == "production" {
        return MX_PROD_URL;
    }
    return MX_BASE_URL;
}

def _get_headers() -> dict {
    """Build MX API authentication headers."""
    import from base64 { b64encode }
    client_id = environ.get("MX_CLIENT_ID", "");
    api_key = environ.get("MX_API_KEY", "");
    credentials = b64encode(f"{client_id}:{api_key}".encode()).decode();
    return {
        "Authorization": f"Basic {credentials}",
        "Accept": "application/vnd.mx.api.v1+json",
        "Content-Type": "application/json"
    };
}

def create_user(user_id: str) -> dict {
    """Create an MX user record."""
    try {
        import from httpx { Client }
        with Client() as c {
            resp = c.post(
                f"{get_base_url()}/users",
                headers=_get_headers(),
                json={"user": {"id": user_id}}
            );
            resp.raise_for_status();
            return resp.json().get("user", {});
        }
    } except Exception as e {
        print(f"[MX] Create user failed: {e}");
        return {};
    }
}

def get_accounts(mx_user_guid: str) -> list[dict] {
    """Fetch all accounts for an MX user."""
    try {
        import from httpx { Client }
        with Client() as c {
            resp = c.get(
                f"{get_base_url()}/users/{mx_user_guid}/accounts",
                headers=_get_headers()
            );
            resp.raise_for_status();
            return resp.json().get("accounts", []);
        }
    } except Exception as e {
        print(f"[MX] Get accounts failed: {e}");
        return [];
    }
}

def get_transactions(mx_user_guid: str, account_guid: str, days_back: int = 90) -> list[dict] {
    """Fetch recent transactions for an MX account."""
    try {
        import from httpx { Client }
        import from datetime { datetime, timedelta }
        from_date = (datetime.utcnow() - timedelta(days=days_back)).strftime("%Y-%m-%d");
        with Client() as c {
            resp = c.get(
                f"{get_base_url()}/users/{mx_user_guid}/accounts/{account_guid}/transactions",
                headers=_get_headers(),
                params={"from_date": from_date, "records_per_page": 500}
            );
            resp.raise_for_status();
            return resp.json().get("transactions", []);
        }
    } except Exception as e {
        print(f"[MX] Get transactions failed: {e}");
        return [];
    }
}

"""Plaid API client — financial account linking and transaction sync.

Plaid connects to the patient's bank accounts to:
1. Track medical bill payments
2. Detect suspicious charges (scam detection)
3. Identify recurring bills that may need monitoring
4. Monitor for missed payments and late fees

Uses plaid-python SDK. Install with: pip install plaid-python
"""

import from os { environ }

can _get_plaid_client() -> object {
    """Build and return a configured Plaid API client."""
    try {
        import from plaid { Environment }
        import from plaid.api { plaid_api }
        import from plaid.configuration { Configuration }
        import from plaid.api_client { ApiClient }

        env_name = environ.get("PLAID_ENV", "sandbox");
        env_map = {
            "sandbox": Environment.Sandbox,
            "development": Environment.Development,
            "production": Environment.Production
        };
        config = Configuration(
            host=env_map.get(env_name, Environment.Sandbox),
            api_key={
                "clientId": environ.get("PLAID_CLIENT_ID", ""),
                "secret": environ.get("PLAID_SECRET", "")
            }
        );
        return plaid_api.PlaidApi(ApiClient(config));
    } except ImportError {
        raise ImportError("plaid-python not installed. Run: pip install plaid-python");
    }
}

can create_link_token(user_id: str, client_name: str = "AgeWise") -> str {
    """Create a Plaid Link token to initiate account connection."""
    try {
        import from plaid.model.link_token_create_request { LinkTokenCreateRequest }
        import from plaid.model.link_token_create_request_user { LinkTokenCreateRequestUser }
        import from plaid.model.products { Products }
        import from plaid.model.country_code { CountryCode }
    } except ImportError {
        return "";
    }

    client = _get_plaid_client();
    request = LinkTokenCreateRequest(
        user=LinkTokenCreateRequestUser(client_user_id=user_id),
        client_name=client_name,
        products=[Products("transactions")],
        country_codes=[CountryCode("US")],
        language="en"
    );
    response = client.link_token_create(request);
    return response.link_token;
}

can sync_transactions(access_token: str, cursor: str = "") -> dict {
    """Sync transactions from Plaid using incremental cursor-based sync."""
    try {
        import from plaid.model.transactions_sync_request { TransactionsSyncRequest }
    } except ImportError {
        return {"added": [], "modified": [], "removed": [], "next_cursor": ""};
    }

    client = _get_plaid_client();
    has_more = True;
    added = [];
    modified = [];
    removed = [];
    current_cursor = cursor;

    while has_more {
        request = TransactionsSyncRequest(
            access_token=access_token,
            cursor=current_cursor if current_cursor else None
        );
        response = client.transactions_sync(request);
        added.extend(response.added);
        modified.extend(response.modified);
        removed.extend(response.removed);
        current_cursor = response.next_cursor;
        has_more = response.has_more;
    }

    return {
        "added": [_txn_to_dict(t) for t in added],
        "modified": [_txn_to_dict(t) for t in modified],
        "removed": [t.transaction_id for t in removed],
        "next_cursor": current_cursor
    };
}

can get_accounts(access_token: str) -> list[dict] {
    """Get all accounts linked to an access token."""
    try {
        import from plaid.model.accounts_get_request { AccountsGetRequest }
    } except ImportError {
        return [];
    }

    client = _get_plaid_client();
    request = AccountsGetRequest(access_token=access_token);
    response = client.accounts_get(request);
    return [
        {
            "account_id": acc.account_id,
            "name": acc.name,
            "official_name": acc.official_name or "",
            "type": str(acc.type),
            "subtype": str(acc.subtype) if acc.subtype else "",
            "mask": acc.mask or "",
            "balance_current": acc.balances.current,
            "balance_available": acc.balances.available
        }
        for acc in response.accounts
    ];
}

can _txn_to_dict(t: object) -> dict {
    return {
        "transaction_id": t.transaction_id,
        "account_id": t.account_id,
        "amount": float(t.amount),
        "merchant_name": t.merchant_name or t.name or "",
        "date": str(t.date),
        "category": t.category or [],
        "pending": t.pending,
        "payment_channel": str(t.payment_channel) if t.payment_channel else "other"
    };
}

