}

class RuleBasedAnalysisEngine {
    def analyze(self: RuleBasedAnalysisEngine, request: AnalysisRequest, emit: Any) -> AnalysisResult {
        positive = {"NVDA", "MSFT", "AAPL", "AMZN", "META", "GOOGL"};
        negative = {"TSLA", "SMCI", "COIN", "MSTR", "PLTR"};
        holdings = request.portfolio.holdings;

        emit(
            EngineEvent(
                agent="portfolio_ingestor",
                stage="started",
                message="Normalized " + str(len(holdings)) + " holdings for analysis",
                progress=0.1
            )
        );
        emit(
            EngineEvent(
                agent="researcher",
                stage="running",
                message="Scanning the portfolio for concentration and crowding risk",
                progress=0.25
            )
        );

        holding_results: list[HoldingAnalysis] = [];
        recommendations: list[Recommendation] = [];
        graph_nodes: list[GraphNode] = [];
        graph_edges: list[GraphEdge] = [];

        weighted_risk_total: float = 0.0;
        sentiment_scores: list[int] = [];

        index: int = 0;
        for holding in holdings {
            index = index + 1;
            ticker = holding.ticker.upper();
            concentration_penalty: int = min(int(holding.weight * 100), 35);
            ord_sum: int = 0;
            for ch in ticker {
                oc: int = ord(ch);
                ord_sum = ord_sum + oc;
            }
            base_risk: int = 35 + concentration_penalty + ((ord_sum % 17) * 2);

            sentiment = "neutral";
            sentiment_score: int = 0;
            if ticker in positive {
                base_risk = base_risk - 8;
                sentiment = "positive";
                sentiment_score = 1;
            } elif ticker in negative {
                base_risk = base_risk + 10;
                sentiment = "negative";
                sentiment_score = -1;
            }

            risk_score: int = max(5, min(base_risk, 95));
            weighted_risk_total = weighted_risk_total + (float(risk_score) * holding.weight);
            sentiment_scores.append(sentiment_score);

            summary = self._build_summary(
                ticker=ticker,
                weight=holding.weight,
                risk_score=risk_score,
                sentiment=sentiment
            );
            w_rounded = int(holding.weight * 10000) / 10000.0;
            holding_results.append(
                HoldingAnalysis(
                    ticker=ticker,
                    weight=w_rounded,
                    risk_score=risk_score,
                    sentiment=sentiment,
                    summary=summary
                )
            );

            if holding.weight >= 0.2 or risk_score >= 70 {
                tw = max(holding.weight * 0.7, 0.05);
                target_weight = int(tw * 10000) / 10000.0;
                recommendations.append(
                    Recommendation(
                        ticker=ticker,
                        action="reduce",
                        reason="position concentration and volatility",
                        target_weight=target_weight
                    )
                );
            }

            if request.options.include_graph {
                asset_id = "asset:" + ticker;
                graph_nodes.extend(
                    [
                        GraphNode(id=asset_id, label=ticker, kind="asset"),
                        GraphNode(id="bull:" + ticker, label=ticker + " Bull", kind="bull"),
                        GraphNode(id="bear:" + ticker, label=ticker + " Bear", kind="bear"),
                        GraphNode(id="judge:" + ticker, label=ticker + " Judge", kind="judge")
                    ]
                );
                graph_edges.extend(
                    [
                        GraphEdge(source=asset_id, target="bull:" + ticker, label="analyzed_by"),
                        GraphEdge(source=asset_id, target="bear:" + ticker, label="analyzed_by"),
                        GraphEdge(source="bull:" + ticker, target="judge:" + ticker, label="debated"),
                        GraphEdge(source="bear:" + ticker, target="judge:" + ticker, label="debated")
                    ]
                );
            }

            denom: int = len(holdings);
            if denom < 1 {
                denom = 1;
            }
            prog: float = 0.25 + (0.4 * float(index) / float(denom));
            if prog > 0.65 {
                prog = 0.65;
            }
            emit(
                EngineEvent(
                    agent="risk_analyzer",
                    stage="running",
                    message="Evaluated " + ticker + " with risk score " + str(risk_score),
                    progress=prog
                )
            );
        }

        emit(
            EngineEvent(
                agent="sentiment_agent",
                stage="running",
                message="Synthesizing cross-holding sentiment and allocation pressure",
                progress=0.8
            )
        );

        overall_risk_score = int(round(weighted_risk_total));
        risk_band = self._risk_band(overall_risk_score);
        sentiment_summary = self._sentiment_summary(sentiment_scores);

        if request.options.include_rebalancing and len(recommendations) == 0 and len(holding_results) > 0 {
            lowest = holding_results[0];
            for h in holding_results {
                if h.risk_score < lowest.risk_score {
                    lowest = h;
                }
            }
            tw_m = int(lowest.weight * 10000) / 10000.0;
            recommendations.append(
                Recommendation(
                    ticker=lowest.ticker,
                    action="maintain",
                    reason="portfolio looks balanced relative to current signals",
                    target_weight=tw_m
                )
            );
        }

        emit(
            EngineEvent(
                agent="judge_agent",
                stage="completed",
                message="Finished portfolio verdict and rebalancing recommendations",
                progress=1.0
            )
        );

        graph = GraphData();
        if request.options.include_graph {
            graph = GraphData(nodes=graph_nodes, edges=graph_edges);
        }

        return AnalysisResult(
            overall_risk_score=overall_risk_score,
            risk_band=risk_band,
            sentiment_summary=sentiment_summary,
            rebalancing_suggestions=recommendations
                if request.options.include_rebalancing
                else [],
            holdings=holding_results,
            graph=graph
        );
    }

    def _build_summary(
        self: RuleBasedAnalysisEngine,
        ticker: str,
        weight: float,
        risk_score: int,
        sentiment: str
    ) -> str {
        if sentiment == "positive" {
            tone = "favorable momentum with manageable downside";
        } elif sentiment == "negative" {
            tone = "elevated downside sensitivity and headline risk";
        } else {
            tone = "mixed signals with no decisive catalyst";
        }
        pct = int(weight * 1000) / 10.0;
        return (
            ticker + " is " + str(pct) + "% of the portfolio with a "
            + str(risk_score) + "/100 risk score, suggesting " + tone + "."
        );
    }

    def _risk_band(self: RuleBasedAnalysisEngine, score: int) -> str {
        if score >= 70 {
            return "high";
        }
        if score >= 45 {
            return "moderate";
        }
        return "low";
    }

    def _sentiment_summary(self: RuleBasedAnalysisEngine, scores: list[int]) -> str {
        score: int = 0;
        for s in scores {
            score = score + s;
        }
        if score > 0 {
            return "Positive skew across core holdings";
        }
        if score < 0 {
            return "Mixed to negative across the portfolio";
        }
        return "Mixed";
    }
}

"""Maps the Jac multi-agent graph (`alphawalker_pipeline.jac`) into API `AnalysisResult` models."""

import logging;
import os;
import from typing { Any }

import from api.engine { EngineEvent, RuleBasedAnalysisEngine }
import from api.jac_bridge { run_jac_pipeline }
import from api.models {
    AnalysisRequest,
    AnalysisResult,
    GraphData,
    GraphEdge,
    GraphNode,
    HoldingAnalysis,
    Recommendation
}

glob logger = logging.getLogger("api.jac_engine");

def _risk_band(score: int) -> str {
    if score >= 70 {
        return "high";
    }
    if score >= 45 {
        return "moderate";
    }
    return "low";
}

def _sentiment_summary(scores: list[int]) -> str {
    total: int = 0;
    for s in scores {
        total = total + s;
    }
    if total > 0 {
        return "Positive skew across core holdings";
    }
    if total < 0 {
        return "Mixed to negative across the portfolio";
    }
    return "Mixed";
}

def _has_any(hay: str, needles: list[str]) -> bool {
    for n in needles {
        if n in hay {
            return True;
        }
    }
    return False;
}

def _sentiment_from_row(verdict: str, bull_c: int, bear_c: int) -> str {
    v = (verdict or "").lower();
    if _has_any(v, ["buy", "accumulate", "overweight", "add"]) {
        return "positive";
    }
    if _has_any(v, ["sell", "reduce", "underweight", "trim"]) {
        return "negative";
    }
    if bull_c > bear_c + 15 {
        return "positive";
    }
    if bear_c > bull_c + 15 {
        return "negative";
    }
    return "neutral";
}

def _risk_score(row: dict[str, Any], weight: float) -> int {
    jc = int(row.get("judge_confidence", 0) or 0);
    bc = int(row.get("bear_confidence", 0) or 0);
    buc = int(row.get("bull_confidence", 0) or 0);
    base: int = max(10, 100 - min(100, jc));
    diff: int = abs(bc - buc);
    tilt: int = diff // 5;
    concentration: int = min(25, int(weight * 100));
    score: int = base + tilt + (concentration // 2);
    return max(5, min(95, score));
}

def _pct_one(weight: float) -> str {
    v = int(weight * 1000) / 10.0;
    return str(v);
}

def _summary(row: dict[str, Any], weight: float, risk: int, sentiment: str) -> str {
    t = str(row.get("ticker", ""));
    rationale_raw = row.get("rationale", "");
    rationale = str(rationale_raw or "").strip();
    verdict_raw = row.get("verdict", "");
    verdict = str(verdict_raw or "").strip();
    pct = _pct_one(weight);
    if rationale != "" {
        clip: str;
        if len(rationale) > 400 {
            clip = rationale[0:397] + "...";
        } else {
            clip = rationale;
        }
        return (
            t + " (" + pct + "% weight): judge verdict «" + verdict + "» ("
            + str(risk) + "/100 risk, " + sentiment + "). " + clip
        );
    }
    vv = verdict;
    if vv == "" {
        vv = "n/a";
    }
    return (
        t + " is " + pct + "% of the portfolio with risk " + str(risk) + "/100 "
        + "and " + sentiment + " tone; verdict: " + vv + "."
    );
}

def _round4(x: float) -> float {
    return int(x * 10000) / 10000.0;
}

def _build_graph(tickers: list[str]) -> GraphData {
    nodes: list[GraphNode] = [];
    edges: list[GraphEdge] = [];
    for ticker in tickers {
        aid = "asset:" + ticker;
        nodes.append(GraphNode(id=aid, label=ticker, kind="asset"));
        nodes.append(GraphNode(id="bull:" + ticker, label=ticker + " bull coalition", kind="bull"));
        nodes.append(GraphNode(id="bear:" + ticker, label=ticker + " bear coalition", kind="bear"));
        nodes.append(GraphNode(id="judge:" + ticker, label=ticker + " judge", kind="judge"));
        edges.append(GraphEdge(source=aid, target="bull:" + ticker, label="coalition"));
        edges.append(GraphEdge(source=aid, target="bear:" + ticker, label="coalition"));
        edges.append(GraphEdge(source="bull:" + ticker, target="judge:" + ticker, label="synthesis"));
        edges.append(GraphEdge(source="bear:" + ticker, target="judge:" + ticker, label="synthesis"));
    }
    return GraphData(nodes=nodes, edges=edges);
}

class JacAnalysisEngine {
    has _fallback: RuleBasedAnalysisEngine;

    def __init__(self: JacAnalysisEngine, fallback: RuleBasedAnalysisEngine | None = None) {
        if fallback is not None {
            self._fallback = fallback;
        } else {
            self._fallback = RuleBasedAnalysisEngine();
        }
    }

    def analyze(self: JacAnalysisEngine, request: AnalysisRequest, emit: Any) -> AnalysisResult {
        holdings = request.portfolio.holdings;
        tickers: list[str] = [];
        for h in holdings {
            tickers.append(h.ticker.strip().upper());
        }

        emit(
            EngineEvent(
                agent="portfolio_ingestor",
                stage="started",
                message="Ingested " + str(len(tickers)) + " tickers for Jac graph execution",
                progress=0.08
            )
        );
        emit(
            EngineEvent(
                agent="jac_graph",
                stage="running",
                message="Running bull/bear coalitions and judge walkers (Jac multi-agent engine)",
                progress=0.15
            )
        );

        fb_raw = os.getenv("ALPHAWALKER_JAC_FALLBACK", "1").lower();
        fallback_on_error = fb_raw in ["1", "true", "yes"];

        rows_raw: list[dict[str, Any]] = [];
        try {
            rows_raw = run_jac_pipeline(tickers);
        } except Exception as exc {
            logger.warning("Jac pipeline error: %s", str(exc));
            if not fallback_on_error {
                raise exc;
            }
            emit(
                EngineEvent(
                    agent="jac_graph",
                    stage="degraded",
                    message="Jac engine unavailable (" + str(exc) + "); using deterministic fallback",
                    progress=0.2
                )
            );
            return self._fallback.analyze(request, emit);
        }

        by_ticker: dict[str, dict[str, Any]] = {};
        for r in rows_raw {
            if isinstance(r, dict) {
                tk = str(r.get("ticker", "")).upper();
                by_ticker[tk] = r;
            }
        }

        holding_results: list[HoldingAnalysis] = [];
        recommendations: list[Recommendation] = [];
        weighted_risk: float = 0.0;
        sentiment_scores: list[int] = [];
        n_hold: int = len(holdings);
        if n_hold < 1 {
            n_hold = 1;
        }

        i: int = 0;
        for holding in holdings {
            i = i + 1;
            t = holding.ticker.strip().upper();
            row: dict[str, Any] = {};
            if t in by_ticker {
                row = by_ticker[t];
            }
            sentiment = _sentiment_from_row(
                str(row.get("verdict", "")),
                int(row.get("bull_confidence", 0) or 0),
                int(row.get("bear_confidence", 0) or 0)
            );
            risk = _risk_score(row, holding.weight);
            weighted_risk = weighted_risk + (float(risk) * holding.weight);
            if sentiment == "positive" {
                sentiment_scores.append(1);
            } elif sentiment == "negative" {
                sentiment_scores.append(-1);
            } else {
                sentiment_scores.append(0);
            }

            holding_results.append(
                HoldingAnalysis(
                    ticker=t,
                    weight=_round4(holding.weight),
                    risk_score=risk,
                    sentiment=sentiment,
                    summary=_summary(row, holding.weight, risk, sentiment)
                )
            );

            if request.options.include_rebalancing and (holding.weight >= 0.2 or risk >= 70) {
                tw = holding.weight * 0.75;
                if tw < 0.05 {
                    tw = 0.05;
                }
                recommendations.append(
                    Recommendation(
                        ticker=t,
                        action="reduce",
                        reason="concentration or elevated risk from Jac synthesis",
                        target_weight=_round4(tw)
                    )
                );
            }

            prog: float = 0.2 + 0.55 * float(i) / float(n_hold);
            if prog > 0.75 {
                prog = 0.75;
            }
            emit(
                EngineEvent(
                    agent="risk_analyzer",
                    stage="running",
                    message="Jac synthesis complete for " + t + " (risk " + str(risk) + ")",
                    progress=prog
                )
            );
        }

        overall_risk = int(weighted_risk + 0.5);
        risk_band = _risk_band(overall_risk);
        sentiment_summary = _sentiment_summary(sentiment_scores);

        if request.options.include_rebalancing and len(recommendations) == 0 and len(holding_results) > 0 {
            best = holding_results[0];
            for h in holding_results {
                if h.risk_score < best.risk_score {
                    best = h;
                }
            }
            recommendations.append(
                Recommendation(
                    ticker=best.ticker,
                    action="maintain",
                    reason="Jac graph suggests no mandatory trim vs. current policy",
                    target_weight=_round4(best.weight)
                )
            );
        }

        emit(
            EngineEvent(
                agent="sentiment_agent",
                stage="running",
                message="Aggregated cross-holding sentiment from Jac coalitions",
                progress=0.85
            )
        );
        emit(
            EngineEvent(
                agent="judge_agent",
                stage="completed",
                message="Jac judge walkers finished; portfolio verdict materialized",
                progress=1.0
            )
        );

        out_graph: GraphData = GraphData();
        if request.options.include_graph {
            g_tickers: list[str] = [];
            for h in holdings {
                g_tickers.append(h.ticker.strip().upper());
            }
            out_graph = _build_graph(g_tickers);
        }

        rec_out: list[Recommendation] = [];
        if request.options.include_rebalancing {
            rec_out = recommendations;
        }

        return AnalysisResult(
            overall_risk_score=overall_risk,
            risk_band=risk_band,
            sentiment_summary=sentiment_summary,
            rebalancing_suggestions=rec_out,
            holdings=holding_results,
            graph=out_graph
        );
    }
}

"""FastAPI application exposing AlphaWalker analysis runs.

Analysis executes the Jac multi-agent graph (`alphawalker_pipeline.jac`) by default,
with SQLite-backed run state for polling. See `DEPLOYMENT.md` for env vars.
"""

import os;
import from datetime { datetime, timezone }
import from pathlib { Path }
import from typing { Annotated }
import from fastapi { Depends, FastAPI, Header, HTTPException, Query }
import from fastapi.middleware.cors { CORSMiddleware }
import from pydantic { BaseModel }

import from api.models {
    AnalysisOptions,
    AnalysisRequest,
    ClientContext,
    Holding,
    PortfolioInput
}
import from api.jac_bridge { run_jac_pipeline }
import from api.meta_bridge { run_meta }
import from api.prices { fetch_historical_prices }
import from api.query_bridge { run_query }
import from api.rebalance_bridge { run_rebalance }
import from api.service { AnalysisService }
import from api.storage { RunStorage }
import from api.insforge_client { create_insforge_client }
import from api.verdict_cache { get as cache_get, set_verdict as cache_set }

class HoldingIn(BaseModel) {
    has ticker: str;
    has weight: float;
}

class PortfolioInputIn(BaseModel) {
    has holdings: list[HoldingIn];
    has as_of_date: str;
}

class AnalysisOptionsIn(BaseModel) {
    has include_sentiment: bool = True;
    has include_rebalancing: bool = True;
    has include_graph: bool = True;
}

class ClientContextIn(BaseModel) {
    has source: str = "alphawalker";
    has session_id: str | None = None;
}

class AnalysisRequestIn(BaseModel) {
    has portfolio: PortfolioInputIn;
    has options: AnalysisOptionsIn = AnalysisOptionsIn();
    has client_context: ClientContextIn = ClientContextIn();
}

class AnalyzeTickersIn(BaseModel) {
    has tickers: list[str];
}

class QueryIn(BaseModel) {
    has question: str;
    has results: list[dict];
}

class PortfolioAnnotationIn(BaseModel) {
    has annotation: str = "";
    has correlated_theme: str = "";
    has hedging_gaps: str = "";
    has portfolio_conviction: str = "";
}

class RebalanceIn(BaseModel) {
    has tickers: list[str];
    has portfolio_annotation: PortfolioAnnotationIn;
    has results: list[dict] = [];
}

glob APP_ROOT = Path(__file__).resolve().parent.parent;
glob DB_PATH = os.getenv("ALPHAWALKER_DB_PATH", str(APP_ROOT / "data" / "analysis_runs.db"));
glob API_KEY = os.getenv("ALPHAWALKER_API_KEY", "");
glob storage = RunStorage(DB_PATH);
glob insforge_client = create_insforge_client(
    os.getenv("INSFORGE_URL"),
    os.getenv("INSFORGE_SERVICE_KEY")
);
glob service = AnalysisService(storage, insforge=insforge_client);
glob startup_recover_count = service.recover_incomplete_runs();
glob app = FastAPI(title="AlphaWalker API", version="0.1.0");

with entry {
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["http://localhost:3000", "http://localhost:5173", "http://127.0.0.1:3000", "http://127.0.0.1:5173"],
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"]
    );
}

def require_api_key(x_api_key: Annotated[str | None, Header()] = None) {
    if API_KEY == "" {
        return;
    }
    if x_api_key != API_KEY {
        raise HTTPException(status_code=401, detail="Unauthorized");
    }
}

def _normalize_ticker_list(raw: list[str]) -> list[str] {
    out: list[str] = [];
    for t in raw {
        if t and t.strip() != "" {
            out.append(t.strip().upper());
        }
    }
    return out;
}

def _int_field(v: int | str | None) -> int {
    if v is None {
        return 0;
    }
    return int(v);
}

def _row_with_confidence(r: dict) -> dict {
    jc_i = _int_field(r.get("judge_confidence", 0));
    return {
        "ticker": str(r.get("ticker", "") or ""),
        "verdict": str(r.get("verdict", "") or ""),
        "confidence": jc_i,
        "rationale": str(r.get("rationale", "") or ""),
        "condition": str(r.get("condition", "") or ""),
        "judge_confidence": jc_i,
        "bull_argument": str(r.get("bull_argument", "") or ""),
        "bull_confidence": _int_field(r.get("bull_confidence", 0)),
        "bear_argument": str(r.get("bear_argument", "") or ""),
        "bear_confidence": _int_field(r.get("bear_confidence", 0))
    };
}

def _analyze_tickers_response(body: AnalyzeTickersIn) -> dict {
    tickers = _normalize_ticker_list(body.tickers);
    if len(tickers) == 0 {
        raise HTTPException(
            status_code=400,
            detail="Provide at least one non-empty ticker."
        );
    }

    # Check cache — skip pipeline for tickers analyzed within the last 12 hours.
    # Prefer Insforge (persists across restarts); fall back to in-memory cache.
    cached: dict = {};
    if insforge_client is not None {
        for (ticker, row) in insforge_client.fetch_recent_verdicts(tickers).items() {
            cached[ticker] = _row_with_confidence(row);
        }
    }
    for t in tickers {
        if t not in cached {
            hit = cache_get(t);
            if hit is not None {
                cached[t] = hit;
            }
        }
    }
    fresh_tickers = [t for t in tickers if t not in cached];

    rows_raw: list[dict] = [];
    if len(fresh_tickers) > 0 {
        try {
            rows_raw = run_jac_pipeline(fresh_tickers);
        } except Exception as exc {
            raise HTTPException(status_code=502, detail=str(exc));
        }
    }

    # Merge: fresh results + cached, preserving original ticker order
    fresh_map: dict = {};
    for r in rows_raw {
        if isinstance(r, dict) and r.get("ticker") {
            row = _row_with_confidence(r);
            fresh_map[r["ticker"]] = row;
            cache_set(r["ticker"], row);  # store in 12h TTL cache
        }
    }
    data: list[dict] = [];
    for t in tickers {
        if t in fresh_map {
            data.append(fresh_map[t]);
        } elif t in cached {
            data.append(cached[t]);
        }
    }
    portfolio_meta: dict | None = None;
    try {
        portfolio_meta = run_meta(data);
    } except Exception as meta_exc {
        import logging;
        logging.getLogger("api.main").warning("Meta agent failed (non-fatal): %s", meta_exc);
    }

    # Only persist fresh results — cached verdicts are already in the DB
    if insforge_client is not None and len(fresh_tickers) > 0 {
        fresh_data = [d for d in data if d.get("ticker", "") in fresh_map];
        if len(fresh_data) > 0 {
            now_iso = datetime.now(timezone.utc).isoformat();
            insforge_row = insforge_client.insert_analysis_run({
                "tickers": tickers,
                "status": "completed",
                "results": data,
                "created_at": now_iso
            });
            if insforge_row is not None and "id" in insforge_row {
                insforge_run_id = insforge_row["id"];
                verdicts: list[dict] = [];
                for d in fresh_data {
                    verdicts.append({
                        "run_id": insforge_run_id,
                        "ticker": d.get("ticker", ""),
                        "verdict": d.get("verdict", ""),
                        "judge_confidence": d.get("judge_confidence", 0),
                        "bull_confidence": d.get("bull_confidence", 0),
                        "bear_confidence": d.get("bear_confidence", 0),
                        "rationale": d.get("rationale", ""),
                        "condition": d.get("condition", ""),
                        "bull_argument": d.get("bull_argument", ""),
                        "bear_argument": d.get("bear_argument", ""),
                        "created_at": now_iso
                    });
                }
                if len(verdicts) > 0 {
                    insforge_client.insert_ticker_verdicts(verdicts);
                }
            }
        }
    }
    return {"status": "success", "data": data, "portfolio_meta": portfolio_meta};
}

def to_request(payload: AnalysisRequestIn) -> AnalysisRequest {
    hs: list[Holding] = [];
    for item in payload.portfolio.holdings {
        hs.append(Holding(ticker=item.ticker, weight=item.weight));
    }
    return AnalysisRequest(
        portfolio=PortfolioInput(holdings=hs, as_of_date=payload.portfolio.as_of_date),
        options=AnalysisOptions(**payload.options.model_dump()),
        client_context=ClientContext(**payload.client_context.model_dump())
    );
}

