    def relativeRefreshedAt(iso: str) -> str {
        raw = String(iso).trim();
        if raw == "" {
            return "";
        }
        try {
            ms = Date.parse(raw);
            if ms != ms {
                return raw;
            }
            diff = Date.now() - ms;
            if diff < 0 {
                diff = 0;
            }
            mins = Math.floor(diff / 60000);
            if mins < 1 {
                return "just now";
            }
            if mins < 60 {
                return String(mins) + "m ago";
            }
            hrs = Math.floor(mins / 60);
            if hrs < 24 {
                return String(hrs) + "h ago";
            }
            days = Math.floor(hrs / 24);
            if days < 30 {
                return String(days) + "d ago";
            }
            d = Reflect.construct(Date, [ms]);
            return d.toLocaleDateString("en-US", {"month": "short", "day": "numeric", "year": "numeric"});
        } except Exception {
            return raw;
        }
    }

