        async def createAppAccount(uname: str, selectedRole: str) -> dict {
            result = await jacSpawn(
                "EnsureUserAccount",
                "",
                {"username": uname, "role": selectedRole, "display_name": uname}
            );
            if result.reports and result.reports.length > 0 {
                return result.reports[0];
            }
            return {"ok": False, "error": "Could not create user profile."};
        }

        async def signInOrCreate() -> None {
            apiAuthError = "";
            if username.trim() == "" or password.trim() == "" {
                apiAuthError = "Enter username and password.";
                return;
            }

            if authMode == "signup" {
                su = await jacSignup(username.trim(), password);
                if not su.success {
                    if su.error and su.error.message {
                        apiAuthError = String(su.error.message);
                    } elif su.error {
                        apiAuthError = String(su.error);
                    } else {
                        apiAuthError = "Could not create login.";
                    }
                    return;
                }
                created = await createAppAccount(username.trim(), roleChoice);
                if not created.ok {
                    if created.error and created.error.message {
                        apiAuthError = String(created.error.message);
                    } elif created.error {
                        apiAuthError = String(created.error);
                    } else {
                        apiAuthError = "Could not create app profile.";
                    }
                    return;
                }
                userId = created.user.id;
                role = created.user.role;
                isAuthed = True;
                apiAuthError = "";
                mainTab = "work";
                await loadTasks();
                await hydrateChatSession();
                if role == "manager" {
                    await loadSnapshot();
                    runRefresh().catch(lambda e: any -> None {});
                } else {
                    snapshot = {};
                    summaries = [];
                }
                await loadMentionDirectory();
                return;
            }

            ok = await jacLogin(username.trim(), password);
            if not ok {
                apiAuthError = "Invalid username or password.";
                return;
            }
            u = await loadUserByUsername(username.trim());
            if not u {
                created2 = await createAppAccount(username.trim(), "employee");
                if not created2.ok {
                    if created2.error and created2.error.message {
                        apiAuthError = String(created2.error.message);
                    } elif created2.error {
                        apiAuthError = String(created2.error);
                    } else {
                        apiAuthError = "Could not create app profile.";
                    }
                    return;
                }
                u = created2.user;
            }
            userId = u.id;
            role = u.role;
            isAuthed = True;
            apiAuthError = "";
            mainTab = "work";
            await loadTasks();
            await hydrateChatSession();
            if role == "manager" {
                await loadSnapshot();
                runRefresh().catch(lambda e: any -> None {});
            } else {
                snapshot = {};
                summaries = [];
            }
            await loadMentionDirectory();
        }

