                            </button>
                            for t in ["planned", "in-progress", "completed", "overdue"]
                        ]}
                    </div>
                    {( <p className="bb-task-loading" role="status">Loading tasks…</p> ) if tasksLoading else (None)}
                    {( <p className="bb-task-empty">{taskTabEmptyMessage(taskTab)}</p> ) if (not tasksLoading and len(tasks) == 0) else (None)}
                    <ul className="bb-task-list">
                        {[
                            <li className="bb-task-card" key={String(tk.id)}>
                                <div className="bb-task-card-top">
                                    <h3 className="bb-task-title">{tk.title}</h3>
                                    <span className="bb-task-status">{tk.status}</span>
                                </div>
                                {( <p className="bb-task-assignee">{String(tk.assignee_name)} · @{String(tk.assignee_username)}</p> ) if (role == "manager" and tk.assignee_name) else (None)}
                                {( <p className="bb-task-project">{String(tk.project_name)}</p> ) if (role == "manager" and tk.project_name) else (None)}
                                <p className="bb-task-schedule">{taskScheduleLine(taskTab, tk)}</p>
                                {( <span className="bb-task-est">Est. {String(tk.time_estimate)}</span> ) if tk.time_estimate else (None)}
                                {( <div className="bb-task-chips">
                                    {[
                                        <span key={String(c)} className={"bb-task-chip bb-task-chip--" + String(c).replace("_", "-")}>{complianceChipLabel(String(c))}</span>
                                        for c in tk.compliance_flags
                                    ]}
                                </div> ) if tk.compliance_flags else (None)}
                                <p className="bb-task-id-muted" title="Task id">{String(tk.id)}</p>
                            </li>
                            for tk in tasks
                        ]}
                    </ul>
                </section>
            </div> ) if (isAuthed and (role != "manager" or mainTab == "work")) else (None)}
        </div>;
    }
}

# Shared `with entry` logic for beanbot_with_ui.jac (alternate entry).

def beanbot_try_delegate_jac_start() -> None {
    import os;
    import subprocess;
    import sys;
    if len(sys.argv) >= 2 and sys.argv[1] == "start" and str(sys.argv[0]).endswith(".jac") {
        cwd = os.path.dirname(os.path.abspath(sys.argv[0]));
        rc = subprocess.call(
            ["jac", "start", sys.argv[0]] + sys.argv[2:],
            cwd=cwd,
        );
        sys.exit(rc);
    }
    if (
        len(sys.argv) >= 3
        and str(sys.argv[1]).endswith(".jac")
        and sys.argv[2] == "start"
    ) {
        # e.g. [jac, main.jac, start, --no_client]
        entry = sys.argv[1];
        cwd = os.path.dirname(os.path.abspath(entry));
        rc = subprocess.call(
            ["jac", "start", entry] + sys.argv[3:],
            cwd=cwd,
        );
        sys.exit(rc);
    }
    if (
        len(sys.argv) >= 3
        and sys.argv[1] == "start"
        and str(sys.argv[2]).endswith(".jac")
    ) {
        # e.g. [jac, start, main.jac, --dev]
        entry = sys.argv[2];
        cwd = os.path.dirname(os.path.abspath(entry));
        rc = subprocess.call(
            ["jac", "start", entry] + sys.argv[3:],
            cwd=cwd,
        );
        sys.exit(rc);
    }
}

def beanbot_run_entry() -> None {
    import sys;
    beanbot_try_delegate_jac_start();
    import from db { init_db };
    init_db();
    print(
        "BeanBot ready. Same as main.jac: jac start beanbot_with_ui.jac (README). "
        + "API only: jac start main.jac --no_client. DB smoke: jac run main.jac."
    );
}

