"""Authentication walkers — register or login by phone number and password."""

import secrets;
import from models.user { User, user_to_dict, hash_password }
import from services.common { new_session_id, iso_now }

def find_user_by_phone(phone: str) -> User | None {
    anchor = root();
    users = [u for u in [anchor -->](?:User) if u.phone_number == phone];
    if users { return users[0]; }
    return None;
}

def find_user_by_token(token: str) -> User | None {
    anchor = root();
    users = [u for u in [anchor -->](?:User) if u.session_token == token];
    if users { return users[0]; }
    return None;
}

walker :pub register_or_login {
    has phone_number: str;
    has password: str;

    can start with Root entry {
        phone = self.phone_number.strip();
        if phone == "" {
            report {"error": "Phone number is required"};
            disengage;
        }
        if self.password == "" {
            report {"error": "Password is required"};
            disengage;
        }
        pw_hash = hash_password(self.password);
        token = secrets.token_hex(32);
        existing = find_user_by_phone(phone);
        if existing == None {
            uid = new_session_id();
            now = iso_now();
            created = root ++> User(
                phone_number=phone,
                user_id=uid,
                created_at=now,
                password_hash=pw_hash,
                session_token=token
            );
            existing = created[0];
            commit();
            report {"user": user_to_dict(existing), "token": token, "is_new": True};
        } else {
            if existing.password_hash != pw_hash {
                report {"error": "Incorrect password"};
                disengage;
            }
            existing.session_token = token;
            commit();
            report {"user": user_to_dict(existing), "token": token, "is_new": False};
        }
    }
}

walker :pub get_user_by_token {
    has token: str;

    can start with Root entry {
        if self.token == "" {
            report {"error": "Token is required"};
            disengage;
        }
        user = find_user_by_token(self.token);
        if user == None {
            report {"error": "Invalid or expired session"};
            disengage;
        }
        report {"user": user_to_dict(user)};
    }
}

walker :pub logout {
    has token: str;

    can start with Root entry {
        user = find_user_by_token(self.token);
        if user != None {
            user.session_token = "";
            commit();
        }
        report {"ok": True};
    }
}

"""Calling agent — verifies readiness for provider search."""

import from models.session { UserSession, CallingPreparation }
import from services.common { transcript_excerpt }
glob LLM_READY: bool = True;

"""You are Care Anchor, a compassionate medical intake assistant. Your job is to gather enough
information to find the right healthcare providers near the patient. You MUST collect:

1. The patient's location (city and state) — required to find nearby providers
2. Enough symptom detail to determine the right specialist — ask about what the symptoms feel
   like, where exactly they occur, how long they've been going on, severity, and any related
   symptoms

Still missing: {missing_fields}
Symptoms shared so far: {symptoms}
Recent conversation:
{recent_transcript}

Write a warm, thorough response that does ALL of the following:
- Briefly acknowledge what the patient shared (1 short sentence)
- Ask for ALL missing fields together naturally
- Ask targeted symptom detail questions to build a clear clinical picture: where exactly is the
  discomfort, what does it feel like (sharp, dull, throbbing, etc.), how long has it been going
  on, how severe is it on a scale of 1-10, and are there any related symptoms?

Be conversational and empathetic, not clinical. No bullet points. Do not wrap your response in
quotation marks."""
def llm_generate_follow_up(
    missing_fields: list[str],
    symptoms: list[str],
    recent_transcript: str
) -> str by llm();

def run_calling_agent(session: UserSession) -> CallingPreparation {
    session.agent_path.append("Calling Agent:active");

    loc = session.location if session.location else "";
    missing: list[str] = [];

    if not session.extracted_symptoms or len(session.extracted_symptoms) == 0 {
        missing.append("symptoms");
    }
    if loc == "" { missing.append("location (city and state)"); }

    ready = len(missing) == 0;

    note = "";
    if not ready {
        note = "Waiting for: " + ", ".join(missing) + ".";
    }

    session.agent_path.append("Calling Agent:completed");

    return CallingPreparation(
        normalized_location=loc,
        normalized_insurance="",
        provider_search_ready=ready,
        missing_fields=missing,
        note=note
    );
}

def build_calling_follow_up(session: UserSession, prep: CallingPreparation) -> str {
    if not prep.provider_search_ready {
        if LLM_READY {
            try {
                excerpt = transcript_excerpt(session.transcript, 8);
                result = llm_generate_follow_up(
                    missing_fields=prep.missing_fields,
                    symptoms=session.extracted_symptoms,
                    recent_transcript=excerpt
                );
                return result;
            } except Exception as e {
                0;
            }
        }
        missing_str = " and ".join(prep.missing_fields);
        return "Could you share your " + missing_str + "? Also tell me more about your symptoms — where exactly do you feel them, how long have they been going on, and how severe are they?";
    }
    return "I have everything I need. Let me look up providers for you.";
}

"""Conversation agent — symptom and field extraction."""

import from models.session { UserSession, ConversationStateUpdate }
import from services.transcript_parser { build_conversation_state_update }

def run_conversation_agent(session: UserSession, message: str) -> ConversationStateUpdate {
    session.active_agent = "Conversation Agent";
    session.agent_path.append("Conversation Agent:active");

    update = build_conversation_state_update(
        message=message,
        transcript_messages=session.transcript,
        known_symptoms=session.extracted_symptoms,
        known_location=session.location
    );

    for sym in update.extracted_symptoms {
        if sym not in session.extracted_symptoms {
            session.extracted_symptoms.append(sym);
        }
    }

    if update.location and update.location != "" {
        session.location = update.location;
    }
    if update.duration and update.duration != "" {
        session.symptom_duration = update.duration;
    }
    if update.severity and update.severity != "" {
        session.severity = update.severity;
    }

    session.agent_path.append("Conversation Agent:completed");
    return update;
}

def minimum_fields_ready(session: UserSession) -> bool {
    has_symptoms = len(session.extracted_symptoms) > 0;
    has_location = session.location != None and session.location != "";
    return has_symptoms and has_location;
}

"""Diagnosis agent — ICD-10-CM code matching and provider search."""

import from models.session { UserSession, DiagnosisResult }
import from services.symptom_mapper { build_diagnosis_result }
import from services.provider_matcher { find_providers }
import from services.common { transcript_excerpt }

def run_diagnosis_agent(session: UserSession) -> DiagnosisResult {
    session.active_agent = "Diagnosis Agent";
    session.agent_path.append("Diagnosis Agent:active");

    excerpt = transcript_excerpt(session.transcript, 8);
    result = build_diagnosis_result(session.extracted_symptoms, excerpt);

    session.assigned_codes = result.symptom_codes;

    loc = session.location if session.location else "";

    providers = find_providers(
        diagnosis=result,
        location=loc,
        max_results=4
    );
    session.provider_options = providers;

    session.agent_path.append("Diagnosis Agent:completed");
    return result;
}

"""Intervention agent — crisis detection and state management."""

import from models.session { UserSession, InterventionDecision }
import from services.safety_rules { detect_crisis, detect_resume, CRISIS_RESPONSE_MARKDOWN }
import from services.provider_matcher { find_therapists, format_therapists_markdown }

def build_crisis_reply(session: UserSession) -> str {
    base = CRISIS_RESPONSE_MARKDOWN;
    loc = session.location if session.location else "";
    if loc == "" {
        return base + "\n\n---\n\nTo help find a therapist near you, could you share your city and state?";
    }
    providers = find_therapists(loc, 5);
    therapist_section = format_therapists_markdown(providers, loc);
    return base + "\n\n---\n\n" + therapist_section;
}

def run_therapist_search(session: UserSession) -> str {
    loc = session.location if session.location else "";
    if loc == "" {
        return "To find therapists near you, could you share your city and state?";
    }
    providers = find_therapists(loc, 5);
    session.provider_options = providers;
    session.crisis_therapists_shown = True;
    return format_therapists_markdown(providers, loc);
}

def run_intervention_agent(session: UserSession, message: str) -> dict {
    decision = detect_crisis(message);
    if decision.is_crisis {
        session.intervention_active = True;
        session.intervention_resolved = False;
        session.active_agent = "Intervention Agent";
        flag = "Crisis language detected: " + decision.reason;
        if flag not in session.risk_flags {
            session.risk_flags.append(flag);
        }
        if "Intervention Agent:active" not in session.agent_path {
            session.agent_path.append("Intervention Agent:active");
        }
        reply = build_crisis_reply(session);
        if session.location and session.location != "" {
            session.crisis_therapists_shown = True;
        }
        decision.response_markdown = reply;
        return {"triggered": True, "decision": decision};
    }
    return {"triggered": False, "decision": decision};
}

def try_resume_from_intervention(session: UserSession, message: str) -> str | None {
    if not session.intervention_active { return None; }
    if session.intervention_resolved { return None; }

    if detect_resume(message) {
        session.intervention_active = False;
        session.intervention_resolved = True;
        session.active_agent = "Conversation Agent";
        session.agent_path.append("Intervention Agent:resolved");
        return "I'm glad you're safe. Let's continue — please tell me your symptoms, and your city/state and insurance when you can.";
    }
    return None;
}

"""Messaging agent — formats the final user-facing reply from structured data."""

import from models.session { UserSession, DiagnosisResult }

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _is_icd_code(s: str) -> bool {
    if len(s) < 3 { return False; }
    return s[0].isupper() and s[1].isdigit();
}

def _natural_symptoms(raw: list) -> list {
    result: list = [];
    for s in raw {
        words = s.strip().split();
        if words and not _is_icd_code(words[0]) {
            result.append(s);
        }
    }
    return result;
}

def _code_str(code: any) -> str {
    if isinstance(code, dict) {
        return code["code"] + " — " + code["description"];
    }
    return code.code + " — " + code.description;
}

def _provider_lines(p: any) -> list {
    if isinstance(p, dict) {
        name  = p["name"];
        spec  = p["specialty"];
        phone = p["phone"];
        tele  = p["telehealth_available"];
    } else {
        name  = p.name;
        spec  = p.specialty;
        phone = p.phone;
        tele  = p.telehealth_available;
    }
    lines: list = ["- **" + name + "** (" + spec + ") · " + phone];
    if tele { lines.append("  *Telehealth available*"); }
    return lines;
}

# ---------------------------------------------------------------------------
# Template-based reply — no LLM
# The local 7B model echoes its prompt and cannot reliably format Markdown.
# All output is derived directly from structured session data.
# ---------------------------------------------------------------------------

def run_messaging_agent(
    session: UserSession,
    diagnosis: DiagnosisResult
) -> str {
    session.active_agent = "Messaging Agent";
    session.agent_path.append("Messaging Agent:active");

    loc = session.location if session.location else "your area";
    lines: list = [];

    # What the patient reported
    readable = _natural_symptoms(session.extracted_symptoms);
    lines.append("## What I heard");
    if readable {
        lines.append("You mentioned: **" + ", ".join(readable[:5]) + "**.");
    } else {
        lines.append("I wasn't able to identify specific symptoms from your message. Please describe how you're feeling.");
    }

    # Possible related conditions
    if diagnosis.symptom_codes {
        lines.append("\n## Possible related conditions");
        lines.append("*(For informational purposes only — not a medical diagnosis)*");
        for code in diagnosis.symptom_codes[:3] {
            lines.append("- **" + _code_str(code) + "**");
        }
    }

    # Matched providers
    if session.provider_options {
        lines.append("\n## Providers near " + loc);
        for p in session.provider_options[:3] {
            for ln in _provider_lines(p) {
                lines.append(ln);
            }
        }
    } else {
        lines.append("\n*No providers found for your location. Try calling 211 for local referrals.*");
    }

    # Disclaimer
    lines.append("\n---");
    lines.append("*Care Anchor is a care coordination tool. It does not provide medical advice or diagnoses. In an emergency, call 911.*");

    session.agent_path.append("Messaging Agent:completed");
    return "\n".join(lines);
}

"""Public walkers — POST /walker/<Name> endpoints."""

import from models.session {
    UserSession, append_message, session_to_dict, update_session_timestamp
}
import from services.common { new_session_id, iso_now }
import from .conversation { minimum_fields_ready, run_conversation_agent }
import from .intervention { run_intervention_agent, try_resume_from_intervention, run_therapist_search }
import from .calling { run_calling_agent, build_calling_follow_up }
import from .diagnosis { run_diagnosis_agent }
import from .messaging { run_messaging_agent }

def find_session(sid: str) -> UserSession | None {
    anchor = root();
    sessions = [candidate for candidate in [anchor -->](?:UserSession) if candidate.session_id == sid];
    if sessions { return sessions[0]; }
    return None;
}

def build_payload(session: UserSession, reply: str, crisis: bool) -> dict {
    return {
        "session_id": session.session_id,
        "reply_markdown": reply,
        "session": session_to_dict(session),
        "crisis": crisis
    };
}

def run_pipeline(session: UserSession, message: str) -> dict {
    now = iso_now();
    append_message(session, "user", message, "User", now);
    session.last_user_message = message;
    update_session_timestamp(session, now);

    run_conversation_agent(session, message);

    intervention = run_intervention_agent(session, message);
    if intervention["triggered"] {
        decision = intervention["decision"];
        reply = decision.response_markdown;
        append_message(session, "assistant", reply, "Intervention Agent", iso_now());
        return build_payload(session, reply, True);
    }

    resumed = try_resume_from_intervention(session, message);
    if resumed != None {
        append_message(session, "assistant", resumed, "Conversation Agent", iso_now());
        return build_payload(session, resumed, False);
    }

    if session.intervention_active {
        if not session.crisis_therapists_shown and session.location and session.location != "" {
            reply = run_therapist_search(session);
            append_message(session, "assistant", reply, "Intervention Agent", iso_now());
            return build_payload(session, reply, True);
        }
        hold = "**Safety check** — Are you safe right now? If in immediate danger call **911** or text **988**.\n\nCould you share your city and state so I can find a therapist near you?";
        append_message(session, "assistant", hold, "Intervention Agent", iso_now());
        return build_payload(session, hold, True);
    }

    calling = run_calling_agent(session);

    if not calling.provider_search_ready {
        reply = build_calling_follow_up(session, calling);
        append_message(session, "assistant", reply, "Calling Agent", iso_now());
        return build_payload(session, reply, False);
    }

    diagnosis = run_diagnosis_agent(session);
    reply = run_messaging_agent(session, diagnosis);
    append_message(session, "assistant", reply, "Messaging Agent", iso_now());
    return build_payload(session, reply, False);
}

