def:pub run_data_agent(command: str) -> dict {
    agent = root() spawn DataAgentWalker(command_text=command);
    walk_log = agent.thoughts;

    final_summary = agent.data_found if len(agent.data_found) > 0 else "Graph modified successfully! Check UI updates.";

    return {
        "summary": final_summary,
        "thoughts": walk_log
    };
}
