  border-radius: 999px;
  padding: 0.4rem 0.8rem;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background: rgba(255, 255, 255, 0.03);
  font-size: 0.78rem;
  color: var(--text-secondary);
}

.gw-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-weight: var(--weight-label);
  color: rgba(220, 239, 255, 0.76);
}

.gw-kicker::before {
  content: "";
  width: 44px;
  height: 1px;
  background: linear-gradient(90deg, rgba(82, 229, 213, 0), rgba(82, 229, 213, 0.8));
}

.gw-shell-nav {
  position: sticky;
  top: 18px;
  z-index: 10;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 18px;
  padding: 18px 22px;
  border-radius: 28px;
}

/* True horizontal center for middle links: equal flex space left and right. */
.gw-shell-nav--balanced {
  grid-template-columns: 1fr auto 1fr;
}

.gw-shell-nav--balanced > .gw-wordmark {
  justify-self: start;
  min-width: 0;
}

.gw-shell-nav--balanced > .gw-header-links {
  justify-self: center;
}

.gw-shell-nav--balanced > .gw-nav-cta {
  justify-self: end;
}

.gw-header-links {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.gw-nav-cta {
  white-space: nowrap;
  justify-self: end;
}

.gw-nav-link {
  padding: 0.7rem 0.92rem;
  border-radius: 999px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: color 180ms var(--ease-out), background 180ms var(--ease-out);
}

.gw-nav-link:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);
}

.gw-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.95rem;
}

.gw-wordmark-copy {
  display: flex;
  flex-direction: column;
  gap: 0.16rem;
}

.gw-wordmark-title {
  font-family: var(--font-display);
  font-size: 1.08rem;
  font-weight: var(--weight-bold);
  letter-spacing: -0.03em;
}

.gw-wordmark-subtitle {
  color: var(--text-tertiary);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.gw-mark {
  position: relative;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background:
    radial-gradient(circle at 30% 25%, rgba(255, 255, 255, 0.24), transparent 42%),
    linear-gradient(180deg, rgba(220, 239, 255, 0.18), rgba(17, 22, 29, 0.7));
  border: 1px solid rgba(220, 239, 255, 0.16);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 10px 26px rgba(0, 0, 0, 0.28);
}

.gw-mark-core {
  position: absolute;
  inset: 13px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(125, 211, 255, 0.9), rgba(82, 229, 213, 0.36) 54%, transparent 70%);
  filter: blur(0.5px);
}

.gw-mark-orbit {
  position: absolute;
  inset: 7px;
  border-radius: 999px;
  border: 1px solid rgba(220, 239, 255, 0.2);
}

.gw-mark-orbit-one {
  inset: 8px 11px 16px 11px;
}

.gw-mark-orbit-two {
  inset: 15px 8px 9px 15px;
}

.gw-role-panel {
  max-width: 920px;
  margin: 0 auto;
  padding-top: 48px;
}

.gw-role-head {
  text-align: center;
  margin-bottom: 36px;
}

.gw-role-title {
  margin: 12px 0 14px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: var(--weight-black);
  letter-spacing: -0.04em;
  line-height: 1.1;
}

.gw-role-sub {
  margin: 0 auto;
  max-width: 52ch;
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.75;
}

.gw-role-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.gw-role-card {
  display: block;
  padding: 26px 26px 24px;
  border-radius: 22px;
  color: inherit;
  text-decoration: none;
  text-align: center;
  border: 1px solid rgba(220, 239, 255, 0.14);
  transition: border-color 0.25s var(--ease-out), transform 0.25s var(--ease-out);
}

.gw-role-card:hover {
  border-color: rgba(125, 211, 255, 0.4);
  transform: translateY(-3px);
}

.gw-role-card-kicker {
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-cyan);
  font-weight: var(--weight-label);
  margin: 0 auto 10px;
  max-width: 100%;
  text-wrap: balance;
}

.gw-role-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  margin: 0 0 10px;
  font-weight: var(--weight-bold);
}

.gw-role-card-body {
  margin: 0;
  color: var(--text-secondary);
  font-size: 0.98rem;
  line-height: 1.65;
}

.gw-role-back {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 22px;
  font-size: 0.92rem;
  color: var(--text-secondary);
}

.gw-role-back-icon {
  flex-shrink: 0;
  opacity: 0.9;
}

.gw-role-back:hover {
  color: var(--text-primary);
}

.gw-landing-main {
  display: grid;
  gap: 54px;
  padding-top: 0;
  margin-top: 54px;
}

.gw-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(0, 0.96fr);
  gap: clamp(16px, 2.4vw, 32px);
  align-items: center;
}

.gw-landing-fold > header {
  flex-shrink: 0;
}

.gw-landing-fold .gw-hero-landing {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.gw-hero-landing-center {
  flex: 1;
  width: 100%;
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  justify-items: center;
  align-items: center;
}

.gw-hero-landing-backdrop {
  grid-column: 1;
  grid-row: 1;
  place-self: stretch;
  z-index: 0;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 0;
}

.gw-hero-landing-orb-anim {
  display: flex;
  align-items: center;
  justify-content: center;
}

.gw-hero-landing-orb {
  width: min(78vmin, 24rem);
  height: min(78vmin, 24rem);
  max-width: min(92vw, 400px);
  max-height: min(92vw, 400px);
  flex-shrink: 0;
  border-radius: 999px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.18), rgba(255, 255, 255, 0.05)),
    rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.16);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    0 28px 80px rgba(0, 0, 0, 0.35),
    0 0 80px rgba(125, 211, 255, 0.08);
  backdrop-filter: blur(20px) saturate(145%);
  -webkit-backdrop-filter: blur(20px) saturate(145%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.gw-hero-landing-orb-shield {
  width: 76%;
  height: 76%;
  min-width: 80px;
  min-height: 80px;
  max-width: 260px;
  max-height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  filter: drop-shadow(0 0 20px rgba(125, 211, 255, 0.15));
}

.gw-hero-landing-content {
  grid-column: 1;
  grid-row: 1;
  place-self: center;
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: fit-content;
  max-width: min(42rem, 94vw);
  padding: 0 clamp(12px, 3vw, 22px);
  box-sizing: border-box;
}

.gw-landing-fold .gw-hero-title {
  margin: 0 0 clamp(10px, 1.6vh, 22px);
  padding-top: 0.04em;
  font-size: clamp(2rem, 3.8dvh + 2.4vw, 6.4rem);
  line-height: 1.07;
  letter-spacing: -0.055em;
  max-width: 22ch;
  position: relative;
  z-index: 1;
  text-shadow: 0 2px 28px rgba(0, 0, 0, 0.55);
}

.gw-landing-fold .gw-hero-text {
  margin: 0 0 clamp(10px, 1.8vh, 22px);
  font-size: clamp(0.9rem, 0.9dvh + 0.75vw, 1.2rem);
  line-height: 1.62;
  max-width: 52ch;
  text-shadow: 0 1px 18px rgba(0, 0, 0, 0.5);
}

.gw-landing-fold .gw-kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 100%;
  margin: 0 auto clamp(16px, 2.6vh, 28px);
  padding-top: 2px;
  position: relative;
  z-index: 2;
  text-align: center;
  color: rgba(236, 244, 255, 0.96);
  font-weight: var(--weight-label);
  text-shadow: 0 1px 18px rgba(0, 0, 0, 0.45);
}

.gw-landing-fold .gw-hero-title,
.gw-landing-fold .gw-hero-text {
  margin-left: auto;
  margin-right: auto;
}

.gw-landing-fold .gw-hero-pillars {
  width: 100%;
  max-width: 36rem;
  margin-left: auto;
  margin-right: auto;
}

@media (max-height: 520px) {
  .gw-landing-fold .gw-kicker {
    font-size: 0.68rem;
    letter-spacing: 0.16em;
    margin-bottom: 10px;
  }

  .gw-landing-fold .gw-hero-text {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
}

.gw-hero-copy {
  position: relative;
  z-index: 2;
}

.gw-hero-title {
  margin: 18px 0 18px;
  font-family: var(--font-display);
  font-size: clamp(3.2rem, 7vw, 6.4rem);
  line-height: 0.92;
  letter-spacing: -0.06em;
  font-weight: var(--weight-black);
  max-width: 11ch;
}

.gw-hero-text {
  margin: 0 0 28px;
  max-width: 58ch;
  color: var(--text-secondary);
  font-size: clamp(1.02rem, 1.5vw, 1.24rem);
  line-height: 1.88;
}

.gw-hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}

.gw-chip-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 26px;
}

.gw-metric-chip {
  border-radius: 20px;
  padding: 18px;
}

.gw-metric-value {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: var(--weight-black);
  letter-spacing: -0.05em;
}

.gw-metric-label {
  margin-top: 0.5rem;
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.gw-metric-detail {
  margin-top: 0.25rem;
  color: var(--text-tertiary);
  font-size: 0.78rem;
}

.gw-system-strip {
  border-radius: 24px;
  padding: 16px 18px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.gw-system-strip span {
  font-size: 0.82rem;
  font-weight: var(--weight-label);
  color: rgba(220, 239, 255, 0.84);
  padding: 0.58rem 0.78rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.gw-hero-pillars {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(8px, 1.2vw, 14px);
}

.gw-hero-pillar {
  border-radius: 18px;
  padding: clamp(12px, 1.6vh, 18px) clamp(10px, 1.2vw, 16px);
  min-height: 3.35rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-size: clamp(0.72rem, 0.55dvh + 0.55vw, 0.84rem);
  font-weight: var(--weight-label);
  letter-spacing: 0.02em;
  color: rgba(220, 239, 255, 0.9);
  line-height: 1.25;
}

.gw-hero-visual {
  position: relative;
  min-height: 640px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gw-ghost-emblem {
  width: min(100%, 560px);
  height: auto;
}

.gw-hero-alert-card,
.gw-hero-telemetry {
  position: absolute;
  border-radius: 22px;
  padding: 18px 20px;
}

.gw-hero-alert-card {
