}

.gw-hero-alert-label,
.gw-telemetry-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-tertiary);
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-hero-alert-label::before,
.gw-telemetry-label::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent-red);
  box-shadow: 0 0 18px rgba(255, 123, 144, 0.65);
}

.gw-hero-alert-title,
.gw-telemetry-value {
  margin-top: 0.9rem;
  font-family: var(--font-display);
  font-size: 1.28rem;
  font-weight: var(--weight-bold);
  letter-spacing: -0.03em;
}

.gw-hero-alert-copy,
.gw-telemetry-copy {
  margin-top: 0.55rem;
  color: var(--text-secondary);
  line-height: 1.6;
  font-size: 0.92rem;
}

.gw-telemetry {
  width: min(240px, 46%);
}

.gw-telemetry-top {
  right: -2%;
  top: 10%;
}

.gw-telemetry-middle {
  left: 6%;
  top: 13%;
}

.gw-telemetry-bottom {
  right: 8%;
  bottom: 18%;
}

.gw-section {
  position: relative;
}

.gw-section-head {
  margin-bottom: 22px;
  max-width: 760px;
}

.gw-section-title {
  margin: 12px 0 10px;
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 4.3vw, 3.6rem);
  line-height: 0.98;
  letter-spacing: -0.05em;
  font-weight: var(--weight-black);
}

.gw-section-copy {
