  font-family: var(--font-display);
  font-size: clamp(2.8rem, 6vw, 5.2rem);
  line-height: 0.94;
  letter-spacing: -0.06em;
  font-weight: var(--weight-black);
}

.gw-auth-copy {
  margin: 0;
  max-width: 48ch;
  color: var(--text-secondary);
