.gw-auth-card-header h2 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: 2rem;
  letter-spacing: -0.04em;
}

.gw-auth-card-header p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.7;
}

.gw-provider-grid {
