  gap: 14px;
}

.gw-provider-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 0.96rem 1rem;
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02)),
    rgba(18, 24, 31, 0.62);
  color: var(--text-primary);
  cursor: pointer;
  transition: transform 180ms var(--ease-out), border-color 180ms var(--ease-out);
}

.gw-provider-button:hover {
  transform: translateY(-2px);
  border-color: rgba(220, 239, 255, 0.2);
}

.gw-provider-icon {
  width: 20px;
  height: 20px;
}

.gw-auth-divider {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  color: var(--text-tertiary);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-auth-divider::before,
.gw-auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(220, 239, 255, 0), rgba(220, 239, 255, 0.18), rgba(220, 239, 255, 0));
}

.gw-auth-field {
  display: grid;
  gap: 0.55rem;
}

.gw-auth-label {
  font-size: 0.8rem;
  color: rgba(220, 239, 255, 0.7);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gw-auth-input {
  width: 100%;
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background: rgba(8, 11, 15, 0.5);
  padding: 1rem 1.05rem;
  min-height: 56px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 180ms var(--ease-out), background 180ms var(--ease-out);
}

.gw-auth-input::placeholder {
  color: rgba(125, 136, 152, 0.72);
}

.gw-auth-input:hover,
.gw-auth-input:focus-visible {
  border-color: rgba(125, 211, 255, 0.3);
  background: rgba(10, 14, 19, 0.65);
}

.gw-auth-legal {
  color: var(--text-tertiary);
  font-size: 0.82rem;
  line-height: 1.7;
}

.gw-auth-note-card {
  padding: 22px 24px;
}

.gw-note-list {
  display: grid;
  gap: 12px;
  margin-top: 16px;
}

.gw-note-item {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 0.88rem 0.96rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.06);
  color: var(--text-secondary);
}

.gw-note-item span:first-child {
  color: var(--text-primary);
}

.gw-app-shell {
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  gap: 22px;
  min-height: calc(100vh - 48px);
}

.gw-sidebar {
  border-radius: 32px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.gw-sidebar-nav {
  display: grid;
  gap: 10px;
}

.gw-sidebar-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.92rem 1rem;
  border-radius: 20px;
  border: 1px solid transparent;
  cursor: pointer;
  color: var(--text-secondary);
  transition:
    background 180ms var(--ease-out),
    border-color 180ms var(--ease-out),
    transform 180ms var(--ease-out),
    color 180ms var(--ease-out);
}

.gw-sidebar-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);
}

.gw-sidebar-item.is-active {
  background:
    linear-gradient(180deg, rgba(220, 239, 255, 0.12), rgba(220, 239, 255, 0.03)),
    rgba(125, 211, 255, 0.08);
  border-color: rgba(125, 211, 255, 0.16);
  color: var(--text-primary);
  transform: translateX(2px);
}

.gw-sidebar-icon {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.08);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: rgba(220, 239, 255, 0.84);
}

.gw-sidebar-copy {
  display: grid;
  gap: 0.16rem;
  text-align: left;
}

.gw-sidebar-copy strong {
  font-size: 0.94rem;
  letter-spacing: -0.02em;
}

.gw-sidebar-copy span {
  font-size: 0.76rem;
  color: var(--text-tertiary);
}

.gw-sidebar-footer {
  margin-top: auto;
  display: grid;
  gap: 14px;
}

.gw-demo-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  width: fit-content;
  padding: 0.7rem 0.88rem;
  border-radius: 999px;
  background: rgba(82, 229, 213, 0.07);
  border: 1px solid rgba(82, 229, 213, 0.14);
  color: rgba(220, 255, 250, 0.92);
  font-size: 0.8rem;
  font-weight: var(--weight-label);
}

.gw-demo-badge::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent-aqua);
  box-shadow: 0 0 18px rgba(82, 229, 213, 0.5);
}

.gw-profile-card {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.92rem 1rem;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.08);
}

.gw-avatar {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.18), transparent 40%),
    linear-gradient(180deg, rgba(125, 211, 255, 0.24), rgba(17, 22, 29, 0.8));
  border: 1px solid rgba(220, 239, 255, 0.16);
  font-family: var(--font-display);
  font-weight: var(--weight-bold);
}

.gw-profile-meta {
  display: grid;
  gap: 0.2rem;
}

.gw-profile-meta strong {
  font-size: 0.92rem;
}

.gw-profile-meta span {
  color: var(--text-tertiary);
  font-size: 0.78rem;
}

.gw-workspace {
  display: grid;
  gap: 18px;
}

.gw-workspace--connect {
  min-height: calc(100vh - 120px);
  place-content: center;
}

.gw-topbar {
  border-radius: 30px;
  padding: 18px 20px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
}

.gw-topbar-heading {
  display: grid;
  gap: 0.5rem;
}

.gw-topbar-heading h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  letter-spacing: -0.04em;
}

.gw-topbar-heading p {
  margin: 0;
  color: var(--text-secondary);
}

.gw-topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.gw-repo-select,
.gw-icon-button,
.gw-search-shell {
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.1);
  background: rgba(8, 11, 15, 0.34);
  min-height: 52px;
}

.gw-repo-select {
  display: inline-flex;
  align-items: center;
  gap: 0.78rem;
  padding: 0 1rem;
}

.gw-repo-label {
  display: grid;
  gap: 0.16rem;
  text-align: left;
}

.gw-repo-label strong {
  font-size: 0.92rem;
}

.gw-repo-label span {
  font-size: 0.76rem;
  color: var(--text-tertiary);
}

.gw-search-shell {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0 0.9rem;
  min-width: 280px;
}

.gw-search-shell svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.gw-search-input {
  width: 100%;
  background: transparent;
  border: 0;
  outline: none;
}

.gw-icon-button {
  width: 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  cursor: pointer;
}

.gw-icon-badge {
  position: absolute;
  top: 9px;
  right: 9px;
  min-width: 18px;
  height: 18px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 123, 144, 0.92);
  color: #10131a;
  font-size: 0.68rem;
  font-weight: var(--weight-bold);
}

.gw-command-banner {
  border-radius: 24px;
  padding: 16px 18px;
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
}

.gw-command-banner strong {
  font-size: 0.88rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(220, 239, 255, 0.78);
}

.gw-command-banner p {
  margin: 0.45rem 0 0;
  color: var(--text-secondary);
  line-height: 1.7;
}

.gw-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
}

.gw-main-grid--single {
  grid-template-columns: minmax(0, 1fr);
}

.gw-wordmark-link {
  text-decoration: none;
  color: inherit;
  border-radius: 20px;
  outline-offset: 4px;
}

.gw-wordmark-link:focus-visible {
  outline: 2px solid rgba(125, 211, 255, 0.45);
}

.gw-sidebar-item--no-icon {
  padding-left: 1.1rem;
}

.gw-repo-connect {
  border-radius: 28px;
  padding: 2rem 2.25rem;
  max-width: 560px;
  margin: 0 auto;
  align-self: center;
  display: grid;
  gap: 1.1rem;
}

.gw-repo-connect-title {
  margin: 0;
  font-size: 1.35rem;
  letter-spacing: -0.03em;
}

.gw-repo-connect-lede {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.65;
  font-size: 0.92rem;
}

.gw-repo-connect-code {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: rgba(186, 230, 253, 0.92);
}

.gw-repo-connect-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.gw-repo-connect-input {
  flex: 1 1 220px;
  min-width: 0;
  border-radius: 16px;
  border: 1px solid rgba(220, 239, 255, 0.14);
  background: rgba(6, 10, 18, 0.55);
  color: var(--text-primary);
  padding: 0.75rem 1rem;
  font-size: 0.9rem;
}

.gw-repo-connect-input::placeholder {
  color: var(--text-tertiary);
}

.gw-table-panel {
  border-radius: 24px;
  padding: 1.25rem 1.35rem 1.35rem;
}

.gw-table-panel-title {
  margin: 0 0 1rem;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
}

.gw-data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}

.gw-data-table th,
.gw-data-table td {
  text-align: left;
  padding: 0.65rem 0.75rem;
  border-bottom: 1px solid rgba(220, 239, 255, 0.08);
  vertical-align: top;
}

.gw-data-table th {
  color: var(--text-tertiary);
  font-weight: var(--weight-label);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.68rem;
}

.gw-data-table--compact td {
  padding: 0.5rem 0.75rem;
}

.gw-repo-row-current {
  background: rgba(125, 211, 255, 0.06);
}

.gw-settings-column {
  gap: 16px;
}

.gw-settings-block {
  border-radius: 24px;
  padding: 1.25rem 1.35rem 1.35rem;
  display: grid;
  gap: 0.85rem;
}

.gw-settings-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-secondary);
  font-size: 0.88rem;
  cursor: pointer;
}

.gw-settings-label {
  min-width: 160px;
  color: var(--text-secondary);
  font-size: 0.86rem;
}

.gw-settings-select {
  flex: 1;
  max-width: 220px;
  border-radius: 14px;
  border: 1px solid rgba(220, 239, 255, 0.14);
  background: rgba(6, 10, 18, 0.55);
  color: var(--text-primary);
  padding: 0.45rem 0.65rem;
  font-size: 0.86rem;
}

.gw-settings-hint {
  margin: 1rem 0 0;
  font-size: 0.8rem;
  color: var(--text-tertiary);
  line-height: 1.55;
}

.gw-main-column {
  display: grid;
  gap: 18px;
}

.gw-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.gw-summary-card {
  border-radius: 24px;
  padding: 20px;
  display: grid;
  gap: 1rem;
}

.gw-summary-card.is-frost {
  border-color: rgba(220, 239, 255, 0.18);
}

.gw-summary-card.is-cyan {
  border-color: rgba(125, 211, 255, 0.2);
}

.gw-summary-card.is-aqua {
  border-color: rgba(82, 229, 213, 0.2);
}

.gw-summary-card.is-amber {
  border-color: rgba(255, 191, 105, 0.22);
}

.gw-summary-label {
  color: var(--text-tertiary);
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-summary-value {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: var(--weight-black);
  letter-spacing: -0.05em;
}

.gw-summary-delta {
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.gw-summary-spark {
  width: 100%;
  height: 48px;
}

.gw-threat-panel,
.gw-graph-panel,
.gw-right-panel {
  border-radius: 28px;
  padding: 22px;
}

.gw-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.gw-panel-head h2,
.gw-right-panel h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.32rem;
  letter-spacing: -0.03em;
}

.gw-panel-head p,
.gw-right-panel p {
  margin: 0.55rem 0 0;
  color: var(--text-secondary);
  line-height: 1.65;
  font-size: 0.92rem;
}

.gw-feed-list {
  display: grid;
  gap: 12px;
}

.gw-feed-row {
  width: 100%;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 1rem 1.04rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(220, 239, 255, 0.06);
  text-align: left;
  cursor: pointer;
  transition:
    transform 180ms var(--ease-out),
    border-color 180ms var(--ease-out),
    background 180ms var(--ease-out);
}

.gw-feed-row:hover {
  transform: translateY(-1px);
  border-color: rgba(220, 239, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
}

.gw-feed-time {
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 0.76rem;
}

.gw-feed-copy strong {
  display: block;
  font-size: 0.94rem;
  letter-spacing: -0.02em;
}

.gw-feed-copy span {
  display: block;
  margin-top: 0.32rem;
  color: var(--text-secondary);
  font-size: 0.84rem;
  line-height: 1.6;
}

.gw-feed-hint {
  color: rgba(220, 239, 255, 0.7);
  font-size: 0.8rem;
}

.gw-severity-pill,
.gw-state-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  padding: 0.44rem 0.7rem;
  font-size: 0.72rem;
  font-weight: var(--weight-label);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.gw-severity-critical {
  background: rgba(255, 123, 144, 0.12);
  color: rgba(255, 189, 199, 0.94);
  border: 1px solid rgba(255, 123, 144, 0.18);
}

.gw-severity-high {
  background: rgba(255, 191, 105, 0.12);
  color: rgba(255, 214, 164, 0.96);
  border: 1px solid rgba(255, 191, 105, 0.18);
}

.gw-severity-medium {
  background: rgba(125, 211, 255, 0.12);
  color: rgba(210, 239, 255, 0.96);
  border: 1px solid rgba(125, 211, 255, 0.18);
}

.gw-state-active {
  background: rgba(82, 229, 213, 0.1);
  color: rgba(196, 255, 248, 0.94);
  border: 1px solid rgba(82, 229, 213, 0.18);
}

.gw-state-queued {
  background: rgba(255, 191, 105, 0.08);
  color: rgba(255, 224, 184, 0.92);
  border: 1px solid rgba(255, 191, 105, 0.16);
}

.gw-state-watching {
  background: rgba(125, 211, 255, 0.1);
  color: rgba(219, 244, 255, 0.94);
  border: 1px solid rgba(125, 211, 255, 0.16);
}

.gw-graph-panel {
  position: relative;
  min-height: 470px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.gw-graph-inner-frame {
  position: absolute;
  inset: 22px;
  border-radius: 26px;
  border: 1px dashed rgba(220, 239, 255, 0.18);
  box-shadow:
    inset 0 0 80px rgba(125, 211, 255, 0.02),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.gw-graph-copy {
  position: relative;
  z-index: 2;
  max-width: 560px;
  text-align: center;
}

.gw-graph-copy span {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  border-radius: 999px;
  padding: 0.48rem 0.82rem;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: rgba(220, 239, 255, 0.84);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-graph-copy span::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent-cyan);
  box-shadow: 0 0 14px rgba(125, 211, 255, 0.5);
}

.gw-graph-copy h2 {
  margin: 1.15rem 0 0.8rem;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.1rem);
  line-height: 0.96;
  letter-spacing: -0.05em;
}

.gw-graph-copy p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.8;
}

.gw-graph-foot {
  margin-top: 1.15rem;
  color: var(--text-tertiary);
  font-size: 0.88rem;
}

.gw-graph-constellation {
  position: absolute;
  inset: 6px;
  width: calc(100% - 12px);
  height: calc(100% - 12px);
  opacity: 0.42;
}

.gw-right-rail {
  display: grid;
  gap: 18px;
}

.gw-right-panel {
  border-radius: 28px;
}

.gw-right-list {
  display: grid;
  gap: 12px;
  margin-top: 14px;
}

.gw-right-item {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 0.88rem 0.95rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.06);
}

.gw-right-item strong {
  font-size: 0.9rem;
  letter-spacing: -0.02em;
}

.gw-right-item span {
  color: var(--text-secondary);
  font-size: 0.78rem;
}

.gw-session-notes {
  display: grid;
  gap: 10px;
  margin-top: 14px;
}

.gw-session-note {
  padding: 0.9rem 0.98rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.06);
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.88rem;
}

.gw-fade-up {
  opacity: 0;
  transform: translateY(26px) scale(0.985);
  animation: gwFadeUp 0.88s var(--ease-out) forwards;
}

/* Opacity-only entrance: safe to combine with gw-float-* (transform) on a parent/child. */
.gw-fade-in {
  opacity: 0;
  animation: gwFadeInOnly 0.78s var(--ease-out) forwards;
}

@keyframes gwFadeInOnly {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.gw-stagger-1 {
  animation-delay: 0.08s;
}

.gw-stagger-2 {
  animation-delay: 0.16s;
}

.gw-stagger-3 {
  animation-delay: 0.24s;
}

.gw-stagger-4 {
  animation-delay: 0.32s;
}

.gw-stagger-5 {
  animation-delay: 0.4s;
}

.gw-stagger-6 {
  animation-delay: 0.48s;
}

.gw-stagger-7 {
  animation-delay: 0.56s;
}

.gw-stagger-8 {
  animation-delay: 0.64s;
}

.gw-float-slow {
  animation: gwFloatSlow 14s var(--ease-soft) infinite;
}

.gw-float-medium {
  animation: gwFloatMedium 10s var(--ease-soft) infinite;
}

.gw-float-delay {
