import db.icij_db;
import from byllm.llm { Model }

glob llm_model: Model = Model(model_name="anthropic/claude-haiku-4-5-20251001");

node Entity {
    has node_id: str;
    has name: str;
    has node_type: str = "entity";
    has countries: str = "";
    has country_codes: str = "";
    has source_id: str = "";
    has jurisdiction: str = "";
    has is_power_player: bool = False;
    has power_player_title: str = "";
    has power_player_release: str = "";
    has hop: int = 0;
}

edge LinkedTo {
    has rel_type: str;
    has link: str = "";
    has source_id: str = "";
}

"""Summarize the structural connection between two persons in an offshore
entity graph. Output 2-3 sentences describing ONLY the graph structure:
who connects to whom, through which entities and intermediaries, in which
jurisdictions, via what relationship types. Do NOT speculate about motives,
legality, or tax implications. Stick strictly to what the edges show."""
def summarize_connection(
    path_description: str,
    person_a: str,
    person_b: str,
    jurisdictions: str,
    entity_count: int,
    intermediary_count: int,
    hop_count: int
) -> str by llm_model();

def:pub search(query: str, limit: int = 30) -> dict {
    results = db.icij_db.search_nodes(query=query, limit=limit);
    return {
        "success": True,
        "results": results,
        "count": len(results)
    };
}

def:pub investigate(node_id: str, max_depth: int = 3, max_nodes: int = 500) -> dict {
    subgraph = db.icij_db.get_subgraph(
        center_node_id=node_id,
        max_depth=max_depth,
        max_nodes=max_nodes
    );
    if not subgraph["nodes"] {
        return {"success": False, "error": "Node not found"};
    }
    return {
        "success": True,
        "nodes": subgraph["nodes"],
        "edges": subgraph["edges"],
        "power_players_found": subgraph["power_players_found"],
        "truncated": subgraph["truncated"],
        "stats": subgraph["stats"]
    };
}

def:pub get_node_detail(node_id: str) -> dict {
    detail = db.icij_db.get_node_detail(node_id);
    if not detail {
        return {"success": False, "error": "Node not found"};
    }
    return {
        "success": True,
        "node": detail
    };
}

def:pub get_db_stats() -> dict {
    stats = db.icij_db.get_stats();
    return {
        "success": True,
        "stats": stats
    };
}

def:pub get_power_players() -> dict {
    data = db.icij_db.get_power_players();
    return {
        "success": True,
        "players": data["players"],
        "connected_pairs": data["connected_pairs"],
        "connectable_count": data["connectable_count"]
    };
}

def:pub find_connections(node_ids: list) -> dict {
    if len(node_ids) < 2 {
        return {"success": False, "error": "Select at least 2 Power Players"};
    }

    # Spawn the PathFinder agent — it discovers paths, materializes the graph,
    # traverses it, and generates AI summaries
    w = PathFinder(target_ids=node_ids);
    root() spawn w;

    return w.result;
}

walker :pub PathFinder {
    has target_ids: list[str] = [];
    has max_depth: int = 6;
    has result: dict = {};
    has collected_nodes: list[dict] = [];
    has visited_ids: list[str] = [];
    has bfs_result: dict = {};

    can start with Root entry {
        if len(self.target_ids) < 2 {
            self.result = {"success": False, "error": "Need at least 2 targets"};
            report self.result;
            disengage;
        }

        # Step 1: Use Python BFS tool to discover paths between targets
        self.bfs_result = db.icij_db.find_connections(
            node_ids=self.target_ids,
            max_depth=8
        );

        if not self.bfs_result["nodes"] {
            self.result = {
                "success": True,
                "nodes": [],
                "edges": [],
                "paths_found": [],
                "paths_not_found": self.bfs_result["paths_not_found"],
                "summaries": [],
                "stats": self.bfs_result["stats"]
            };
            report self.result;
            disengage;
        }

        # Step 2: Materialize discovered paths as a Jac graph
        node_map: dict = {};
        for n in self.bfs_result["nodes"] {
            entity = Entity(
                node_id=n["node_id"],
                name=n["name"],
                node_type=n["node_type"],
                countries=n.get("countries", ""),
                country_codes=n.get("country_codes", ""),
                source_id=n.get("source_id", ""),
                jurisdiction=n.get("jurisdiction", ""),
                is_power_player=n.get("is_power_player", False),
                power_player_title=n.get("power_player_title", ""),
                power_player_release=n.get("power_player_release", ""),
                hop=n.get("hop", 0)
            );
            here ++> entity;
            node_map[n["node_id"]] = entity;
        }

        for e in self.bfs_result["edges"] {
            src = node_map.get(e["source"]);
            tgt = node_map.get(e["target"]);
            if src and tgt {
                src +>:LinkedTo(
                    rel_type=e["rel_type"],
                    link=e.get("link", ""),
                    source_id=e.get("source_id", "")
                ):+> tgt;
            }
        }

        # Step 3: Traverse the materialized graph
        for entity in [-->][?:Entity] {
            visit entity;
        }
    }

    can examine with Entity entry {
        # Agent traverses each node in the discovered path
        if here.node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(here.node_id);

        self.collected_nodes.append({
            "node_id": here.node_id,
            "name": here.name,
            "node_type": here.node_type,
            "countries": here.countries,
            "country_codes": here.country_codes,
            "source_id": here.source_id,
            "jurisdiction": here.jurisdiction,
            "is_power_player": here.is_power_player,
            "power_player_title": here.power_player_title,
            "power_player_release": here.power_player_release,
            "hop": here.hop
        });
    }

    can finish with Root exit {
        # Step 4: Generate AI summaries for each discovered path
        summaries: list = [];
        for path_info in self.bfs_result["paths_found"] {
            path_nodes = [n for n in self.collected_nodes
                          if n["node_id"] in path_info["path_node_ids"]];
            path_edges = [e for e in self.bfs_result["edges"]
                          if e["source"] in path_info["path_node_ids"]
                          and e["target"] in path_info["path_node_ids"]];

            desc = db.icij_db.build_path_description(path_nodes, path_edges);

            jurisdictions_set: set = set();
            entity_count = 0;
            intermediary_count = 0;
            for n in path_nodes {
                j = n.get("jurisdiction", "") or n.get("countries", "");
                if j { jurisdictions_set.add(j); }
                if n["node_type"] == "entity" { entity_count += 1; }
                if n["node_type"] == "intermediary" { intermediary_count += 1; }
            }

            start_node = db.icij_db.get_node(path_info["start_id"]);
            end_node = db.icij_db.get_node(path_info["end_id"]);

            cached = db.icij_db.get_cached_summary(path_info["start_id"], path_info["end_id"]);
            if cached {
                summary_text = cached;
            } else {
                try {
                    summary_text = summarize_connection(
                        path_description=desc,
                        person_a=start_node["name"] if start_node else "",
                        person_b=end_node["name"] if end_node else "",
                        jurisdictions=", ".join(jurisdictions_set),
                        entity_count=entity_count,
                        intermediary_count=intermediary_count,
                        hop_count=path_info["hops"]
                    );
                    db.icij_db.save_cached_summary(path_info["start_id"], path_info["end_id"], summary_text);
                } except Exception as e {
                    summary_text = f"{start_node['name'] if start_node else ''} and {end_node['name'] if end_node else ''} are connected through {path_info['hops']} hops via {entity_count} entities.";
                    db.icij_db.save_cached_summary(path_info["start_id"], path_info["end_id"], summary_text);
                }
            }

            summaries.append({
                "start_name": start_node["name"] if start_node else "",
                "end_name": end_node["name"] if end_node else "",
                "summary": summary_text,
                "hops": path_info["hops"]
            });
        }

        # Clean up materialized graph
        for entity in [-->][?:Entity] {
            del entity;
        }

        # Step 5: Generate investigation decision log
        investigation_log = db.icij_db.generate_investigation_log(self.bfs_result);

        # Step 6: Report findings
        self.result = {
            "success": True,
            "nodes": self.collected_nodes,
            "edges": self.bfs_result["edges"],
            "paths_found": self.bfs_result["paths_found"],
            "paths_not_found": self.bfs_result["paths_not_found"],
            "summaries": summaries,
            "investigation_log": investigation_log,
            "stats": self.bfs_result["stats"]
        };
        report self.result;
    }
}

walker :pub Investigate {
    has center_id: str = "";
    has max_depth: int = 3;
    has max_nodes: int = 500;
    has collected_nodes: list[dict] = [];
    has collected_edges: list[dict] = [];
    has power_players: list[dict] = [];
    has visited_ids: list[str] = [];

    can start with Root entry {
        subgraph = db.icij_db.get_subgraph(
            center_node_id=self.center_id,
            max_depth=self.max_depth,
            max_nodes=self.max_nodes
        );

        node_map: dict = {};
        for n in subgraph["nodes"] {
            entity = Entity(
                node_id=n["node_id"],
                name=n["name"],
                node_type=n["node_type"],
                countries=n.get("countries", ""),
                country_codes=n.get("country_codes", ""),
                source_id=n.get("source_id", ""),
                jurisdiction=n.get("jurisdiction", ""),
                is_power_player=n.get("is_power_player", False),
                power_player_title=n.get("power_player_title", ""),
                power_player_release=n.get("power_player_release", ""),
                hop=n.get("hop", 0)
            );
            here ++> entity;
            node_map[n["node_id"]] = entity;
        }

        for e in subgraph["edges"] {
            src = node_map.get(e["source"]);
            tgt = node_map.get(e["target"]);
            if src and tgt {
                src +>:LinkedTo(
                    rel_type=e["rel_type"],
                    link=e.get("link", ""),
                    source_id=e.get("source_id", "")
                ):+> tgt;
            }
        }

        for entity in [-->][?:Entity] {
            if entity.node_id == self.center_id {
                visit entity;
            }
        }
    }

    can examine with Entity entry {
        if here.node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(here.node_id);

        self.collected_nodes.append({
            "node_id": here.node_id,
            "name": here.name,
            "node_type": here.node_type,
            "countries": here.countries,
            "source_id": here.source_id,
            "is_power_player": here.is_power_player,
            "power_player_title": here.power_player_title,
            "power_player_release": here.power_player_release,
            "hop": here.hop
        });

        if here.is_power_player {
            self.power_players.append({
                "node_id": here.node_id,
                "name": here.name,
                "title": here.power_player_title,
                "release": here.power_player_release,
                "hop": here.hop
            });
        }

        visit [<-->][?:Entity];
    }

    can finish with Root exit {
        for entity in [-->][?:Entity] {
            del entity;
        }

        report {
            "success": True,
            "nodes": self.collected_nodes,
            "edges": self.collected_edges,
            "power_players_found": self.power_players,
            "stats": {
                "total_nodes": len(self.collected_nodes),
                "total_edges": len(self.collected_edges)
            }
        };
    }
}

#* Inocula C2 — Attacker Control Plane (Laptop B)
   Phase 1 skeleton. Walker shapes mirror shared/protocol.md §5 "C2" and the
   Scout→C2 / C2→Sentinel / Sentinel→C2 contracts in §1, §2, §4.

   Phase 1 scope:
     - Graph + walker endpoints + cl{} attack dashboard
     - OODA state machine transitions based on scan evidence
     - NO real firing. run_operation() just arms + logs. Tracks are stubs.
     - Real orchestration lands in Phase 4 via tracks/track_stealth.jac and
       tracks/track_noisy.jac. *#

import sys;
import os;
import time;
import json;
import datetime;

import from adapters.track_ops { fire_stealth as track_fire_stealth, fire_noisy as track_fire_noisy, plan_operation as track_plan, adapter_healthcheck as track_adapter_healthcheck }

# ── Utility helpers ──────────────────────────────────────────────────────

def now_utc() -> str {
    return datetime.datetime.utcnow().isoformat() + "Z";
}

def cap_event_log(log: list, cap: int) -> list {
    if len(log) > cap {
        return log[-cap:];
    }
    return log;
}

# ── Graph schema ─────────────────────────────────────────────────────────

node C2Node {
    has operator_id: str = "inocula-c2",
        ooda_phase: str = "observe",
        current_track: str = "stealth",
        armed: bool = False,
        auto: bool = False,
        target_mac: str = "",
        target_name: str = "",
        target_rssi: int = 0,
        last_scan_utc: str = "",
        last_scan_device_count: int = 0,
        trigger_count: int = 0,
        last_trigger_utc: str = "",
        last_trigger_epoch: float = 0.0,
        cooldown_seconds: float = 90.0,
        event_log: list = [],
        rssi_min_trigger: int = -55,
        idle_required: bool = True,
        op_state: str = "idle",
        last_operation_id: str = "",
        last_operation_result: dict = {};
}

node PiNode {
    has pi_id: str = "",
        last_seen_utc: str = "",
        last_ip: str = "",
        scan_count: int = 0,
        alive: bool = False;
}

node VictimNode {
    has victim_id: str = "",
        sentinel_url: str = "",
        last_status_utc: str = "",
        idle_seconds: float = 0.0,
        defense_phase: str = "unknown",
        connected_device_count: int = 0;
}

edge ScoutEdge {}
edge TargetEdge {}

# ── Shared helpers ───────────────────────────────────────────────────────

def append_event(c2: C2Node, kind: str, payload: dict) {
    entry: dict = {"at": now_utc(), "kind": kind, "data": payload};
    c2.event_log = cap_event_log(c2.event_log + [entry], 200);
}

def pi_summary(p: PiNode) -> dict {
    return {
        "pi_id": p.pi_id,
        "last_ip": p.last_ip,
        "alive": p.alive,
        "last_seen_utc": p.last_seen_utc,
        "scan_count": p.scan_count
    };
}

def victim_summary(v: VictimNode) -> dict {
    return {
        "victim_id": v.victim_id,
        "idle_seconds": v.idle_seconds,
        "defense_phase": v.defense_phase,
        "connected_device_count": v.connected_device_count,
        "last_status_utc": v.last_status_utc
    };
}

def is_interesting_target(name: str) -> bool {
    #* Phase 1 target heuristic: match common HID + audio peripheral names.
       Includes ghostshield's short-code conventions ("km" for mouse-kits,
       "kb" for keyboard kits) so devices like "Samsers KM01-M" resolve
       without additional WinRT metadata. *#
    nl: str = name.lower();
    if "mouse" in nl { return True; }
    if "keyboard" in nl { return True; }
    if "buds" in nl { return True; }
    if "km01" in nl { return True; }
    if " km" in nl { return True; }
    if "kb01" in nl { return True; }
    return False;
}

def select_target(devices: list, rssi_min_trigger: int) -> dict {
    #* Pick the highest-RSSI device whose name matches our target kinds
       and whose RSSI meets the trigger threshold. Returns {} if none. *#
    best: dict = {};
    best_rssi: int = -999;
    for dev in devices {
        name: str = dev.get("name", "");
        if name == "" { continue; }
        rssi_raw = dev.get("rssi", -999);
        rssi_val: int = int(rssi_raw);
        if rssi_val < rssi_min_trigger { continue; }
        if not is_interesting_target(name) { continue; }
        if rssi_val > best_rssi {
            best_rssi = rssi_val;
            best = {
                "name": name,
                "mac": dev.get("mac", ""),
                "rssi": rssi_val,
                "addr_type": dev.get("addr_type", "")
            };
        }
    }
    return best;
}

def compute_ooda_phase(c2: C2Node) -> str {
    if c2.target_mac == "" {
        return "observe";
    }
    if not c2.armed {
        return "orient";
    }
    if c2.trigger_count == 0 {
        return "decide";
    }
    return "act";
}

def cooldown_remaining(c2: C2Node) -> float {
    if c2.last_trigger_epoch <= 0.0 {
        return 0.0;
    }
    elapsed: float = time.time() - c2.last_trigger_epoch;
    remaining: float = c2.cooldown_seconds - elapsed;
    if remaining < 0.0 {
        return 0.0;
    }
    return float(int(remaining * 10.0)) / 10.0;
}

def load_env(key: str, fallback: str) -> str {
    val = os.environ.get(key, fallback);
    if val is None {
        return fallback;
    }
    return val;
}

# ── Walkers — REST endpoints ─────────────────────────────────────────────
# All walker:pub are served at POST /walker/<name>

walker:pub get_c2_state {
    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can collect with C2Node entry {
        scouts = [here ->:ScoutEdge:->][?:PiNode];
        victims = [here ->:TargetEdge:->][?:VictimNode];
        scout_list: list = [];
        for s in scouts { scout_list.append(pi_summary(s)); }
        victim_list: list = [];
        for v in victims { victim_list.append(victim_summary(v)); }

        target_obj: dict = {};
        if here.target_mac != "" {
            target_obj = {
                "name": here.target_name,
                "mac": here.target_mac,
                "rssi": here.target_rssi
            };
        }

        report {
            "operator_id": here.operator_id,
            "ooda_phase": here.ooda_phase,
            "current_track": here.current_track,
            "armed": here.armed,
            "auto": here.auto,
            "target": target_obj,
            "last_scan_utc": here.last_scan_utc,
            "last_scan_device_count": here.last_scan_device_count,
            "trigger_count": here.trigger_count,
            "last_trigger_utc": here.last_trigger_utc,
            "cooldown_seconds": here.cooldown_seconds,
            "cooldown_remaining_s": cooldown_remaining(here),
            "rssi_min_trigger": here.rssi_min_trigger,
            "idle_required": here.idle_required,
            "op_state": here.op_state,
            "last_operation_id": here.last_operation_id,
            "last_operation_result": here.last_operation_result,
            "event_log": here.event_log[-50:],
            "scouts": scout_list,
            "victims": victim_list,
            "now_utc": now_utc()
        };
    }
}

walker:pub report_scan {
    #* Scout → C2 contract (see shared/protocol.md §1). Updates pi-as-node,
       selects a target, transitions OODA phase. Does NOT fire anything. *#
    has pi_ip: str = "",
        scan_updated_utc: str = "",
        rssi_min_dbm: int = 0,
        scan_duration_s: int = 0,
        devices: list = [],
        classic: list = [];

    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can handle with C2Node entry {
        # 1. Find-or-create PiNode keyed by pi_ip
        scouts = [here ->:ScoutEdge:->][?:PiNode];
        matches = [s for s in scouts if s.last_ip == self.pi_ip or s.pi_id == self.pi_ip];
        if len(matches) == 0 {
            new_pi = PiNode(pi_id=self.pi_ip, last_ip=self.pi_ip);
            here +>:ScoutEdge():+> new_pi;
            pi_ref = new_pi;
        } else {
            pi_ref = matches[0];
        }
        pi_ref.last_ip = self.pi_ip;
        pi_ref.last_seen_utc = self.scan_updated_utc if self.scan_updated_utc != "" else now_utc();
        pi_ref.scan_count = pi_ref.scan_count + 1;
        pi_ref.alive = True;

        # 2. Update C2 scan state
        here.last_scan_utc = pi_ref.last_seen_utc;
        here.last_scan_device_count = len(self.devices);

        # 3. Target selection — highest-RSSI matching device above threshold
        chosen = select_target(self.devices, here.rssi_min_trigger);
        if len(chosen) > 0 {
            here.target_name = chosen.get("name", "");
            here.target_mac = chosen.get("mac", "");
            here.target_rssi = int(chosen.get("rssi", 0));
        } else {
            here.target_name = "";
            here.target_mac = "";
            here.target_rssi = 0;
        }

        # 4. OODA phase transition (Phase 1 simple logic)
        here.ooda_phase = compute_ooda_phase(here);

        # 5. Append event
        append_event(here, "scan", {
            "pi": self.pi_ip,
            "devices": len(self.devices),
            "classic": len(self.classic),
            "selected": here.target_name,
            "phase": here.ooda_phase
        });

        # 6. Response per protocol §1
        resp_target: dict = {};
        if here.target_mac != "" {
            resp_target = {
                "name": here.target_name,
                "mac": here.target_mac,
                "reason": "rssi " + str(here.target_rssi) + " >= " + str(here.rssi_min_trigger)
            };
        }
        report {
            "devices_received": len(self.devices),
            "c2_phase": here.ooda_phase,
            "target": resp_target,
            "next_poll_seconds": 10
        };
    }
}

walker:pub run_operation {
    #* Phase 4: real orchestration. Dispatches to track_ops.py adapters.
       Honors cooldown. Supports dry_run for safe UI preview. *#
    has track: str = "",
        dry_run: bool = False,
        force: bool = False;

    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can fire with C2Node entry {
        valid_tracks = ["stealth", "noisy", "both"];
        if self.track not in valid_tracks {
            report {
                "started": False,
                "error": "invalid track — must be one of stealth|noisy|both",
                "track": self.track
            };
            disengage;
        }

        # Cooldown gate — skip on dry_run and skip on force.
        remaining = cooldown_remaining(here);
        if (not self.dry_run) and (not self.force) and remaining > 0.0 {
            append_event(here, "run_operation", {
                "track": self.track,
                "rejected": "cooldown",
                "cooldown_remaining_s": remaining
            });
            report {
                "started": False,
                "error": "cooldown",
                "cooldown_remaining_s": remaining,
                "track": self.track
            };
            disengage;
        }

        here.current_track = self.track;
        here.armed = True;
        here.auto = True;
        op_id = "op_" + str(int(time.time()));
        here.last_operation_id = op_id;
        here.op_state = ("planning" if self.dry_run else "firing");

        append_event(here, "run_operation", {
            "track": self.track,
            "operation_id": op_id,
            "dry_run": self.dry_run,
            "force": self.force
        });

        # ── Dispatch ─────────────────────────────────────────────
        sentinel_url = load_env("INOCULA_SENTINEL_URL", "");
        token = load_env("INOCULA_TOKEN", "");
        pi_host = load_env("INOCULA_PI_SSH_HOST", "");

        steps: list = [];
        final_ok = True;

        if self.track == "stealth" {
            stealth_res = track_fire_stealth(
                sentinel_url=sentinel_url,
                token=token,
                operation_id=op_id,
                force=self.force,
                dry_run=self.dry_run
            );
            steps.append({"kind": "stealth", "result": stealth_res});
            if not stealth_res.get("ok", False) {
                final_ok = False;
            }
        } elif self.track == "noisy" {
            if here.target_mac == "" {
                steps.append({"kind": "noisy", "result": {"ok": False, "error": "no target locked"}});
                final_ok = False;
            } else {
                noisy_res = track_fire_noisy(
                    target_mac=here.target_mac,
                    pi_ssh_host=pi_host,
                    dry_run=self.dry_run
                );
                steps.append({"kind": "noisy", "result": noisy_res});
                if not noisy_res.get("ok", False) {
                    final_ok = False;
                }
            }
        } else {
            # "both" — noisy first, chain stealth as impact
            noisy_res: dict = {};
            if here.target_mac == "" {
                noisy_res = {"ok": False, "error": "no target locked"};
                final_ok = False;
            } else {
                noisy_res = track_fire_noisy(
                    target_mac=here.target_mac,
                    pi_ssh_host=pi_host,
                    dry_run=self.dry_run
                );
            }
            steps.append({"kind": "noisy", "result": noisy_res});
            stealth_res = track_fire_stealth(
                sentinel_url=sentinel_url,
                token=token,
                operation_id=op_id,
                force=self.force,
                dry_run=self.dry_run
            );
            steps.append({"kind": "stealth", "result": stealth_res});
            if not stealth_res.get("ok", False) {
                final_ok = False;
            }
        }

        # Record outcome. dry_run does NOT advance the cooldown clock or
        # bump trigger_count — it is literally a preview.
        if not self.dry_run {
            here.trigger_count = here.trigger_count + 1;
            here.last_trigger_epoch = time.time();
            here.last_trigger_utc = now_utc();
        }
        here.op_state = "done";
        here.last_operation_result = {
            "operation_id": op_id,
            "track": self.track,
            "dry_run": self.dry_run,
            "ok": final_ok,
            "steps": steps,
            "at_utc": now_utc()
        };
        append_event(here, "operation_result", here.last_operation_result);
        here.ooda_phase = compute_ooda_phase(here);

        report {
            "started": True,
            "ok": final_ok,
            "track": self.track,
            "operation_id": op_id,
            "ooda_phase": here.ooda_phase,
            "dry_run": self.dry_run,
            "steps": steps,
            "trigger_count": here.trigger_count,
            "cooldown_remaining_s": cooldown_remaining(here)
        };
    }
}

walker:pub abort_operation {
    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can kill with C2Node entry {
        here.armed = False;
        here.auto = False;
        append_event(here, "abort_operation", {"note": "kill switch engaged"});
        here.ooda_phase = compute_ooda_phase(here);
        report {"aborted": True, "ooda_phase": here.ooda_phase};
    }
}

walker:pub configure {
    #* Each field uses a sentinel default so callers can update any subset.
       idle_required is int-encoded (-1 unset, 0 false, 1 true) to keep the
       JSON contract simple. *#
    has target_mac: str = "",
        target_name: str = "",
        current_track: str = "",
        cooldown_seconds: float = -1.0,
        rssi_min_trigger: int = 999,
        idle_required: int = -1;

    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can apply with C2Node entry {
        changes: dict = {};
        if self.target_mac != "" {
            here.target_mac = self.target_mac;
            changes["target_mac"] = self.target_mac;
        }
        if self.target_name != "" {
            here.target_name = self.target_name;
            changes["target_name"] = self.target_name;
        }
        if self.current_track != "" {
            here.current_track = self.current_track;
            changes["current_track"] = self.current_track;
        }
        if self.cooldown_seconds != -1.0 {
            here.cooldown_seconds = self.cooldown_seconds;
            changes["cooldown_seconds"] = self.cooldown_seconds;
        }
        if self.rssi_min_trigger != 999 {
            here.rssi_min_trigger = self.rssi_min_trigger;
            changes["rssi_min_trigger"] = self.rssi_min_trigger;
        }
        if self.idle_required != -1 {
            here.idle_required = (self.idle_required == 1);
            changes["idle_required"] = here.idle_required;
        }
        append_event(here, "configure", changes);
        here.ooda_phase = compute_ooda_phase(here);
        report {
            "updated": changes,
            "current": {
                "target_mac": here.target_mac,
                "target_name": here.target_name,
                "current_track": here.current_track,
                "cooldown_seconds": here.cooldown_seconds,
                "rssi_min_trigger": here.rssi_min_trigger,
                "idle_required": here.idle_required
            }
        };
    }
}

walker:pub operation_dryrun {
    #* Returns what a live run_operation would do, without side-effects.
       Backs the UI "DRY RUN" button and the test harness. *#
    has track: str = "stealth";

    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can plan with C2Node entry {
        valid_tracks = ["stealth", "noisy", "both"];
        if self.track not in valid_tracks {
            report {"ok": False, "error": "invalid track", "track": self.track};
            disengage;
        }
        mac = here.target_mac if here.target_mac != "" else "AA:BB:CC:DD:EE:FF";
        plan = track_plan(self.track, mac);
        report {
            "ok": True,
            "track": self.track,
            "has_target": (here.target_mac != ""),
            "plan": plan,
            "cooldown_remaining_s": cooldown_remaining(here)
        };
    }
}

walker:pub status {
    #* Thin status endpoint for dashboard polling. Same data as
       get_c2_state but without the cost of rebuilding scout/victim
       summaries — used by the cooldown tick loop. *#
    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can snap with C2Node entry {
        report {
            "ooda_phase": here.ooda_phase,
            "armed": here.armed,
            "current_track": here.current_track,
            "trigger_count": here.trigger_count,
            "last_trigger_utc": here.last_trigger_utc,
            "cooldown_seconds": here.cooldown_seconds,
            "cooldown_remaining_s": cooldown_remaining(here),
            "op_state": here.op_state,
            "last_operation_id": here.last_operation_id,
            "has_target": (here.target_mac != ""),
            "now_utc": now_utc()
        };
    }
}

walker:pub sentinel_alert {
    #* Sentinel → C2 webhook (see shared/protocol.md §4). *#
    has sentinel: str = "",
        severity: str = "",
        summary: str = "",
        signals: list = [],
        at_utc: str = "";

    can enter with Root entry {
        existing = [-->[?:C2Node]];
        if len(existing) == 0 {
            here ++> C2Node();
        }
        visit [-->[?:C2Node]];
    }
    can record with C2Node entry {
        append_event(here, "sentinel_alert", {
            "sentinel": self.sentinel,
            "severity": self.severity,
            "summary": self.summary,
            "signals": self.signals,
            "at_utc": (self.at_utc if self.at_utc != "" else now_utc())
        });
        report {"ack": True};
    }
}

