import os;
import sys;
import json;
import time;
import from typing { Any }
import from jac.layers.trace_utils { trace_file, read_trace }

glob DATA_ROOT: str = "./jac/layer_data";
glob TRACE_DIR: str = DATA_ROOT + "/traces";
glob DEDUPE_WINDOW_SECONDS: float = 0.7;

glob ALLOWED_EVENT_TYPES: list[str] = [
    "navigate",
    "click",
    "input",
    "submit",
    "network",
    "scroll",
    "session_state",
    "page_semantic",
    "dom_snapshot",
    "screenshot",
    "page_ready",
    "tab_created",
    "tab_closed",
    "tab_switched",
    "unknown"
];

glob SENSITIVE_HINTS: list[str] = [
    "password",
    "passcode",
    "token",
    "secret",
    "auth",
    "session",
    "cookie",
    "credit",
    "card",
    "ssn"
];

"""R: Return a timestamp string for persisted layer records.
M: Uses `time.time()` and string-casts for broad Jac compatibility.
E: Resolution is seconds with fractional precision.
"""
def timestamp_now() -> str {
    return str(time.time());
}

"""R: Coerce values to bounded strings for safe trace persistence.
M: String-casts, trims, and caps length to avoid oversized events.
E: None maps to empty string.
"""
def safe_str(value: Any, max_len: int) -> str {
    text = str(value or "").strip();
    if len(text) > max_len {
        return text[:max_len];
    }
    return text;
}

"""R: Parse a float from arbitrary input.
M: Attempts `float(raw)` and falls back to zero on invalid values.
E: Invalid numbers return 0.0.
"""
def safe_float(raw: Any) -> float {
    try {
        return float(raw);
    } except ValueError {
        return 0.0;
    } except TypeError {
        return 0.0;
    }
}

"""R: Parse an int from arbitrary input.
M: Attempts `int(raw)` and falls back to zero on invalid values.
E: Invalid numbers return 0.
"""
def safe_int(raw: Any) -> int {
    try {
        return int(raw);
    } except ValueError {
        return 0;
    } except TypeError {
        return 0;
    }
}

"""R: Recursively sanitize JSON-like values for trace persistence.
M: Bounds nesting depth, collection size, and string length.
E: Unsupported values are string-cast and truncated.
"""
def sanitize_json_value(raw: Any, depth: int, max_items: int, max_len: int) -> Any {
    if depth <= 0 {
        return safe_str(raw, max_len);
    }

    if isinstance(raw, dict) {
        normalized: dict[str, Any] = {};
        count: int = 0;
        for key in raw {
            if count >= max_items {
                break;
            }
            safe_key: str = safe_str(key, 80);
            normalized[safe_key] = sanitize_json_value(raw[key], depth - 1, max_items, max_len);
            count += 1;
        }
        return normalized;
    }

    if isinstance(raw, list) {
        normalized_list: list[Any] = [];
        count: int = 0;
        for item in raw {
            if count >= max_items {
                break;
            }
            normalized_list.append(sanitize_json_value(item, depth - 1, max_items, max_len));
            count += 1;
        }
        return normalized_list;
    }

    if isinstance(raw, bool) or isinstance(raw, int) or isinstance(raw, float) {
        return raw;
    }

    return safe_str(raw, max_len);
}

"""R: Ensure observation trace storage path exists.
M: Creates `jac/layer_data/traces` recursively.
E: Safe to call repeatedly.
"""
def ensure_trace_dir() {
    os.makedirs(TRACE_DIR, exist_ok=True);
}

"""R: Validate session id format for filesystem-safe trace names.
M: Allows letters, digits, `_`, and `-`.
E: Empty ids are invalid.
"""
def is_valid_session_id(session_id: str) -> bool {
    if not session_id {
        return False;
    }

    for char in session_id {
        is_lower = (char >= "a") and (char <= "z");
        is_upper = (char >= "A") and (char <= "Z");
        is_digit = (char >= "0") and (char <= "9");
        if not (is_lower or is_upper or is_digit or char == "_" or char == "-") {
            return False;
        }
    }
    return True;
}

"""R: Parse JSON payload passed via CLI args.
M: Joins argv entries from index 2 and decodes JSON.
E: Invalid JSON returns an empty dict.
"""
def parse_payload() -> dict[str, Any] {
    raw_payload: str = "{}";
    if len(sys.argv) > 2 {
        raw_payload = " ".join(sys.argv[2:]);
    }

    try {
        parsed = json.loads(raw_payload);
        if isinstance(parsed, dict) {
            return parsed;
        }
        return {};
    } except json.JSONDecodeError {
        return {};
    }
}

"""R: Persist one observation trace JSON record.
M: Writes formatted JSON to the session file path.
E: Propagates filesystem errors to caller.
"""
def write_trace(session_id: str, trace_data: dict[str, Any]) {
    ensure_trace_dir();
    with open(trace_file(session_id), "w") as file {
        json.dump(trace_data, file, indent=2);
    }
}

"""R: Create deterministic session ids for trace files.
M: Prefixes a time-derived numeric stamp with `sess_`.
E: Collisions are unlikely but possible under extreme concurrency.
"""
def new_session_id() -> str {
    return "sess_" + str(time.time()).replace(".", "");
}

"""R: Check whether an event type is in the allowed schema.
M: Uses fixed allow-list used by the observation layer.
E: Unknown types are treated as invalid.
"""
def is_allowed_event_type(event_type: str) -> bool {
    return event_type in ALLOWED_EVENT_TYPES;
}

"""R: Normalize target payload to stable string fields.
M: Copies supported target keys with bounded string lengths.
E: Missing/non-dict targets produce empty defaults.
"""
def normalize_target(raw_target: Any) -> dict[str, str] {
    target: dict[str, str] = {
        "tag": "",
        "id": "",
        "name": "",
        "role": "",
        "type": "",
        "label": "",
        "text": "",
        "placeholder": "",
        "class_name": "",
        "path": ""
    };

    if not isinstance(raw_target, dict) {
        return target;
    }

    target["tag"] = safe_str(raw_target.get("tag", ""), 60).lower();
    target["id"] = safe_str(raw_target.get("id", ""), 120);
    target["name"] = safe_str(raw_target.get("name", ""), 120);
    target["role"] = safe_str(raw_target.get("role", ""), 80).lower();
    target["type"] = safe_str(raw_target.get("type", ""), 40).lower();
    target["label"] = safe_str(raw_target.get("label", ""), 140);
    target["text"] = safe_str(raw_target.get("text", ""), 180);
    target["placeholder"] = safe_str(raw_target.get("placeholder", ""), 140);
    target["class_name"] = safe_str(raw_target.get("class_name", ""), 220);
    target["path"] = safe_str(raw_target.get("path", ""), 300);

    return target;
}

"""R: Normalize metadata payload for consistent analytics fields.
M: Copies known metadata keys and string/number coercions.
E: Unknown metadata keys are dropped for schema stability.
"""
def normalize_meta(raw_meta: Any) -> dict[str, Any] {
    normalized: dict[str, Any] = {
        "source": "",
        "trigger": "",
        "tab_id": "",
        "kind": "",
        "method": "",
        "request_url": "",
        "initiator_type": "",
        "content_type": "",
        "status": 0,
        "ok": False,
        "duration_ms": 0,
        "error": ""
    };

    if not isinstance(raw_meta, dict) {
        return normalized;
    }

    normalized["source"] = safe_str(raw_meta.get("source", ""), 60);
    normalized["trigger"] = safe_str(raw_meta.get("trigger", ""), 60);
    normalized["tab_id"] = safe_str(raw_meta.get("tab_id", ""), 80);
    normalized["kind"] = safe_str(raw_meta.get("kind", ""), 40);
    normalized["method"] = safe_str(raw_meta.get("method", ""), 20).upper();
    normalized["request_url"] = safe_str(raw_meta.get("request_url", ""), 300);
    normalized["initiator_type"] = safe_str(raw_meta.get("initiator_type", ""), 40);
    normalized["content_type"] = safe_str(raw_meta.get("content_type", ""), 120);
    normalized["status"] = safe_int(raw_meta.get("status", 0));
    normalized["ok"] = bool(raw_meta.get("ok", False));
    normalized["duration_ms"] = safe_int(raw_meta.get("duration_ms", 0));
    normalized["error"] = safe_str(raw_meta.get("error", ""), 160);

    return normalized;
}

"""R: Normalize viewport/scroll telemetry for safe persistence.
M: Keeps common numeric viewport fields and truncates extra data conservatively.
E: Missing/non-dict payloads return empty defaults.
"""
def normalize_viewport(raw_viewport: Any) -> dict[str, Any] {
    normalized: dict[str, Any] = {
        "scroll_x": 0,
        "scroll_y": 0,
        "viewport_width": 0,
        "viewport_height": 0,
        "document_width": 0,
        "document_height": 0,
        "scroll_progress": 0.0
    };

    if not isinstance(raw_viewport, dict) {
        return normalized;
    }

    normalized["scroll_x"] = safe_int(raw_viewport.get("scroll_x", 0));
    normalized["scroll_y"] = safe_int(raw_viewport.get("scroll_y", 0));
    normalized["viewport_width"] = safe_int(raw_viewport.get("viewport_width", 0));
    normalized["viewport_height"] = safe_int(raw_viewport.get("viewport_height", 0));
    normalized["document_width"] = safe_int(raw_viewport.get("document_width", 0));
    normalized["document_height"] = safe_int(raw_viewport.get("document_height", 0));
    normalized["scroll_progress"] = safe_float(raw_viewport.get("scroll_progress", 0));

    return normalized;
}

"""R: Normalize DOM snapshot payloads with bounded nested structure.
M: Preserves headings, form summaries, active element metadata, and HTML excerpts.
E: Large strings and lists are truncated for trace stability.
"""
def normalize_dom_snapshot(raw_snapshot: Any) -> dict[str, Any] {
    if not isinstance(raw_snapshot, dict) {
        return {};
    }
    return sanitize_json_value(raw_snapshot, 4, 16, 2800);
}

"""R: Normalize page/session introspection payloads with bounded nested structure.
M: Preserves cookies, storage previews, navigator info, and routing context.
E: Only page-visible/session-readable state can be captured.
"""
def normalize_session_state(raw_state: Any) -> dict[str, Any] {
    if not isinstance(raw_state, dict) {
        return {};
    }
    return sanitize_json_value(raw_state, 4, 18, 700);
}

"""R: Normalize semantic workflow/page descriptors.
M: Preserves lightweight heuristic context such as page kind, stage, actions, and headings.
E: Unknown/non-dict payloads map to empty dict.
"""
def normalize_semantic(raw_semantic: Any) -> dict[str, Any] {
    if not isinstance(raw_semantic, dict) {
        return {};
    }
    return sanitize_json_value(raw_semantic, 4, 18, 240);
}

"""R: Normalize network telemetry payloads for safe persistence.
M: Preserves request/response metadata, headers, sizes, and timing with bounded fields.
E: Payloads remain metadata-only; response bodies are not persisted.
"""
def normalize_network(raw_network: Any) -> dict[str, Any] {
    if not isinstance(raw_network, dict) {
        return {};
    }
    return sanitize_json_value(raw_network, 4, 18, 320);
}

"""R: Normalize screenshot telemetry payloads.
M: Preserves mime, dimensions, trigger, and one small captured image data URL.
E: Empty/non-dict payloads map to empty dict; image size is bounded.
"""
def normalize_screenshot(raw_screenshot: Any) -> dict[str, Any] {
    normalized: dict[str, Any] = {
        "mime": "",
        "trigger": "",
        "width": 0,
        "height": 0,
        "data_url": "",
        "capture_error": ""
    };

    if not isinstance(raw_screenshot, dict) {
        return {};
    }

    normalized["mime"] = safe_str(raw_screenshot.get("mime", ""), 40);
    normalized["trigger"] = safe_str(raw_screenshot.get("trigger", ""), 40);
    normalized["width"] = safe_int(raw_screenshot.get("width", 0));
    normalized["height"] = safe_int(raw_screenshot.get("height", 0));
    normalized["data_url"] = safe_str(raw_screenshot.get("data_url", ""), 220000);
    normalized["capture_error"] = safe_str(raw_screenshot.get("capture_error", ""), 200);

    return normalized;
}

"""R: Determine if target hints suggest sensitive field content.
M: Checks target type and common secret-related label/name patterns.
E: Heuristic may over-redact ambiguous fields.
"""
def is_sensitive_target(target: dict[str, str]) -> bool {
    if target["type"] == "password" {
        return True;
    }

    haystack = (
        target["label"] + " " + target["name"] + " " + target["id"] + " " + target["placeholder"]
    ).lower();

    for hint in SENSITIVE_HINTS {
        if hint in haystack {
            return True;
        }
    }

    return False;
}

"""R: Convert untyped payloads into normalized observation events.
M: Enforces schema for type/url/target/meta and redacts sensitive values.
E: Unknown types are stored as `unknown`.
"""
def normalize_event(raw_event: Any, default_url: str) -> dict[str, Any] {
    event_type: str = "unknown";
    event_url: str = safe_str(default_url, 300);
    event_value: str = "";
    target: dict[str, str] = normalize_target({});
    meta: dict[str, Any] = normalize_meta({});
    viewport: dict[str, Any] = normalize_viewport({});
    dom_snapshot: dict[str, Any] = {};
    session_state: dict[str, Any] = {};
    semantic: dict[str, Any] = {};
    network: dict[str, Any] = {};
    screenshot: dict[str, Any] = {};

    if isinstance(raw_event, dict) {
        event_type_candidate = safe_str(raw_event.get("type", ""), 40).lower();
        if is_allowed_event_type(event_type_candidate) {
            event_type = event_type_candidate;
        }

        raw_url = safe_str(raw_event.get("url", ""), 300);
        if raw_url {
            event_url = raw_url;
        }

        target = normalize_target(raw_event.get("target", {}));
        meta = normalize_meta(raw_event.get("meta", {}));
        viewport = normalize_viewport(raw_event.get("viewport", {}));
        dom_snapshot = normalize_dom_snapshot(raw_event.get("dom_snapshot", {}));
        session_state = normalize_session_state(raw_event.get("session_state", {}));
        semantic = normalize_semantic(raw_event.get("semantic", {}));
        network = normalize_network(raw_event.get("network", {}));
        screenshot = normalize_screenshot(raw_event.get("screenshot", {}));

        if "value" in raw_event {
            event_value = safe_str(raw_event.get("value", ""), 300);
        }
    }

    if is_sensitive_target(target) {
        event_value = "__redacted__";
    }

    return {
        "type": event_type,
        "url": event_url,
        "value": event_value,
        "target": target,
        "meta": meta,
        "viewport": viewport,
        "dom_snapshot": dom_snapshot,
        "session_state": session_state,
        "semantic": semantic,
        "network": network,
        "screenshot": screenshot,
        "recorded_at": timestamp_now()
    };
}

"""R: Build a stable comparison signature for event dedupe.
M: Concatenates key event fields likely to indicate duplicate actions.
E: Signature intentionally ignores timestamp and minor non-core metadata.
"""
def event_signature(event_data: dict[str, Any]) -> str {
    target: dict[str, Any] = event_data.get("target", {}) if isinstance(event_data.get("target", {}), dict) else {};
    meta: dict[str, Any] = event_data.get("meta", {}) if isinstance(event_data.get("meta", {}), dict) else {};
    viewport: dict[str, Any] = event_data.get("viewport", {}) if isinstance(event_data.get("viewport", {}), dict) else {};
    semantic: dict[str, Any] = event_data.get("semantic", {}) if isinstance(event_data.get("semantic", {}), dict) else {};
    network: dict[str, Any] = event_data.get("network", {}) if isinstance(event_data.get("network", {}), dict) else {};
    dom_snapshot: dict[str, Any] = event_data.get("dom_snapshot", {}) if isinstance(event_data.get("dom_snapshot", {}), dict) else {};

    return (
        safe_str(event_data.get("type", ""), 40) + "|" +
        safe_str(event_data.get("url", ""), 300) + "|" +
        safe_str(event_data.get("value", ""), 300) + "|" +
        safe_str(target.get("tag", ""), 60) + "|" +
        safe_str(target.get("id", ""), 120) + "|" +
        safe_str(target.get("name", ""), 120) + "|" +
        safe_str(target.get("role", ""), 80) + "|" +
        safe_str(target.get("type", ""), 40) + "|" +
        safe_str(target.get("label", ""), 140) + "|" +
        safe_str(target.get("text", ""), 180) + "|" +
        safe_str(meta.get("source", ""), 60) + "|" +
        safe_str(meta.get("trigger", ""), 60) + "|" +
        safe_str(meta.get("tab_id", ""), 80) + "|" +
        safe_str(meta.get("kind", ""), 40) + "|" +
        safe_str(meta.get("method", ""), 20) + "|" +
        safe_str(meta.get("request_url", ""), 300) + "|" +
        str(safe_int(meta.get("status", 0))) + "|" +
        str(safe_int(viewport.get("scroll_y", 0))) + "|" +
        str(safe_float(viewport.get("scroll_progress", 0))) + "|" +
        safe_str(semantic.get("page_kind", ""), 80) + "|" +
        safe_str(semantic.get("workflow_stage", ""), 80) + "|" +
        safe_str(network.get("request_url", ""), 300) + "|" +
        safe_str(network.get("kind", ""), 40) + "|" +
        safe_str(dom_snapshot.get("target_path", ""), 300)
    );
}

"""R: Detect near-identical adjacent events to reduce trace noise.
M: Compares normalized signatures and timestamp delta.
E: Returns false when timestamps are missing or unparsable.
"""
def is_duplicate_event(last_event: dict[str, Any], new_event: dict[str, Any]) -> bool {
    last_time = safe_float(last_event.get("recorded_at", "0"));
    new_time = safe_float(new_event.get("recorded_at", "0"));
    if last_time <= 0.0 or new_time <= 0.0 {
        return False;
    }

    if abs(new_time - last_time) > DEDUPE_WINDOW_SECONDS {
        return False;
    }

    return event_signature(last_event) == event_signature(new_event);
}

"""R: Start a new observation recording session.
M: Builds initial trace payload and persists it to disk.
E: Optional `session_id` can overwrite an existing session file.
"""
def start_trace(payload: dict[str, Any]) -> dict[str, Any] {
    ensure_trace_dir();

    session_id = safe_str(payload.get("session_id", ""), 120);
    if not session_id {
        session_id = new_session_id();
    }

    if not is_valid_session_id(session_id) {
        return {"ok": False, "error": "invalid session_id format"};
    }

    title = safe_str(payload.get("title", "Manual Trace"), 140);
    source_url = safe_str(payload.get("url", ""), 300);
    now: str = timestamp_now();

    trace_data = {
        "session_id": session_id,
        "title": title,
        "source_url": source_url,
        "status": "recording",
        "started_at": now,
        "updated_at": now,
        "telemetry_counts": {},
        "events": []
    };

    write_trace(session_id, trace_data);

    return {
        "ok": True,
        "session_id": session_id,
        "trace_file": trace_file(session_id)
    };
}

"""R: Append one event to an active observation session.
M: Loads trace file, normalizes payload, dedupes noise, and rewrites JSON.
E: Missing session id or trace file returns explicit errors.
"""
def append_trace_event(payload: dict[str, Any]) -> dict[str, Any] {
    session_id = safe_str(payload.get("session_id", ""), 120);
    if not session_id {
        return {"ok": False, "error": "session_id is required"};
    }
    if not is_valid_session_id(session_id) {
        return {"ok": False, "error": "invalid session_id format"};
    }

    trace_data = read_trace(session_id);
    if not trace_data {
        return {"ok": False, "error": "trace not found", "session_id": session_id};
    }

    events: list[Any] = [];
    raw_events = trace_data.get("events", []);
    if isinstance(raw_events, list) {
        events = raw_events;
    }

    normalized = normalize_event(payload.get("event", {}), safe_str(trace_data.get("source_url", ""), 300));

    if events and isinstance(events[-1], dict) and is_duplicate_event(events[-1], normalized) {
        trace_data["updated_at"] = timestamp_now();
        write_trace(session_id, trace_data);
        return {
            "ok": True,
            "session_id": session_id,
            "event_count": len(events),
            "deduped": True
        };
    }

    events.append(normalized);
    trace_data["events"] = events;
    trace_data["updated_at"] = timestamp_now();

    event_type = safe_str(normalized.get("type", "unknown"), 40);
    telemetry_counts: dict[str, Any] = {};
    raw_counts = trace_data.get("telemetry_counts", {});
    if isinstance(raw_counts, dict) {
        telemetry_counts = raw_counts;
    }
    telemetry_counts[event_type] = safe_int(telemetry_counts.get(event_type, 0)) + 1;
    trace_data["telemetry_counts"] = telemetry_counts;

    if normalized.get("viewport", {}) {
        trace_data["latest_viewport"] = normalized["viewport"];
    }
    if normalized.get("semantic", {}) {
        trace_data["latest_semantic"] = normalized["semantic"];
    }
    if normalized.get("session_state", {}) {
        trace_data["latest_session_state"] = normalized["session_state"];
    }
    if normalized.get("dom_snapshot", {}) {
        trace_data["latest_dom_snapshot"] = normalized["dom_snapshot"];
    }
    if normalized.get("screenshot", {}) {
        trace_data["latest_screenshot"] = normalized["screenshot"];
    }

    write_trace(session_id, trace_data);

    return {
        "ok": True,
        "session_id": session_id,
        "event_count": len(events),
        "deduped": False
    };
}

"""R: Mark an observation session as stopped.
M: Loads trace by id, updates status fields, and saves file.
E: Safe to call more than once for the same session.
"""
def stop_trace(payload: dict[str, Any]) -> dict[str, Any] {
    session_id = safe_str(payload.get("session_id", ""), 120);
    if not session_id {
        return {"ok": False, "error": "session_id is required"};
    }
    if not is_valid_session_id(session_id) {
        return {"ok": False, "error": "invalid session_id format"};
    }

    trace_data = read_trace(session_id);
    if not trace_data {
        return {"ok": False, "error": "trace not found", "session_id": session_id};
    }

    now: str = timestamp_now();
    trace_data["status"] = "stopped";
    trace_data["stopped_at"] = now;
    trace_data["updated_at"] = now;
    write_trace(session_id, trace_data);

    events: list[Any] = [];
    raw_events = trace_data.get("events", []);
    if isinstance(raw_events, list) {
        events = raw_events;
    }

    return {
        "ok": True,
        "session_id": session_id,
        "event_count": len(events)
    };
}

"""R: Fetch one stored observation trace by session id.
M: Loads trace JSON and returns the parsed dict.
E: Missing sessions return explicit errors.
"""
def get_trace(payload: dict[str, Any]) -> dict[str, Any] {
    session_id = safe_str(payload.get("session_id", ""), 120);
    if not session_id {
        return {"ok": False, "error": "session_id is required"};
    }
    if not is_valid_session_id(session_id) {
        return {"ok": False, "error": "invalid session_id format"};
    }

    trace_data = read_trace(session_id);
    if not trace_data {
        return {"ok": False, "error": "trace not found", "session_id": session_id};
    }

    return {
        "ok": True,
        "trace": trace_data
    };
}

"""R: Route a layer command to its observation operation.
M: Maps command text to start/append/stop/get handlers.
E: Unknown commands return a usage payload.
"""
def dispatch(command: str, payload: dict[str, Any]) -> dict[str, Any] {
    if command == "start" {
        return start_trace(payload);
    }

    if command == "append" {
        return append_trace_event(payload);
    }

    if command == "stop" {
        return stop_trace(payload);
    }

    if command == "get" {
        return get_trace(payload);
    }

    return {
        "ok": False,
        "error": "unknown command",
        "valid_commands": ["start", "append", "stop", "get"]
    };
}

"""R: Decide whether this module should execute its CLI entrypoint.
M: Treats non-empty, non-path-like argv values as commands and ignores import-time script paths.
E: Unknown direct commands still dispatch so the caller receives the usual usage payload.
"""
def should_dispatch_cli(command: str) -> bool {
    if not command {
        return False;
    }

    return ("/" not in command) and ("\\" not in command) and not command.endswith(".jac");
}

with entry {
    command: str = "";
    if len(sys.argv) > 1 {
        command = str(sys.argv[1]);
    }

    if should_dispatch_cli(command) {
        payload = parse_payload();
        result = dispatch(command, payload);
        print(json.dumps(result));
    }
}

"""
Jac-native recording layer.

State machine:
  idle -> recording_one_time | recording_repeated
  recording_one_time -> recording_repeated | finished
  recording_repeated -> recording_one_time | repeated_example_complete
  repeated_example_complete -> configuring_continuation
  configuring_continuation -> finished

Data model: segmented event capture with explicit one_time and repeated segments.
Continuation strategy and stop_policy are validated and stored; compiler handoff is the next pass.
"""

import os;
import sys;
import json;
import time;
import uuid;
import from typing { Any }

# ============================================================
# CONSTANTS
# ============================================================

glob DATA_ROOT: str = "./jac/layer_data";
glob RECORDING_DIR: str = DATA_ROOT + "/recordings";

glob STATE_IDLE: str = "idle";
glob STATE_RECORDING_ONE_TIME: str = "recording_one_time";
glob STATE_RECORDING_REPEATED: str = "recording_repeated";
glob STATE_REPEATED_EXAMPLE_COMPLETE: str = "repeated_example_complete";
glob STATE_CONFIGURING_CONTINUATION: str = "configuring_continuation";
glob STATE_FINISHED: str = "finished";

# Allowed continuation strategy modes
glob VALID_CONTINUATION_MODES: list[str] = [
    "next_similar_item", "scroll_for_more", "next_page", "manual_pick_next", "stop"
];

# Allowed scroll_style values for scroll_for_more mode
glob VALID_SCROLL_STYLES: list[str] = ["partial", "viewport", "until_new_items"];

# Allowed stop policy modes
glob VALID_STOP_MODES: list[str] = [
    "no_more_items", "after_n_successes", "after_n_reviews", "ask_before_continue"
];

# Stop modes that require a count in options
glob COUNT_REQUIRED_STOP_MODES: list[str] = ["after_n_successes", "after_n_reviews"];

# Allowed transitions: from_state -> list of valid to_states
glob ALLOWED_TRANSITIONS: dict[str, Any] = {
    "idle": ["recording_one_time", "recording_repeated"],
    "recording_one_time": ["recording_repeated", "finished"],
    "recording_repeated": ["recording_one_time", "repeated_example_complete"],
    "repeated_example_complete": ["configuring_continuation"],
    "configuring_continuation": ["finished"]
};

# ============================================================
# UTILITIES
# ============================================================

"""Generate a prefixed random ID from a UUID v4."""
def new_id(prefix: str) -> str {
    uid: str = str(uuid.uuid4()).replace("-", "");
    return prefix + uid[:16];
}

def new_recording_id() -> str { return new_id("rec_"); }

"""Return current UTC time as ISO-8601 string (seconds precision)."""
def timestamp_now() -> str {
    t: Any = time.gmtime();
    result: str = time.strftime("%Y-%m-%dT%H:%M:%SZ", t);
    return result;
}

"""R: Ensure recording storage path exists.
M: Creates `jac/layer_data/recordings` recursively.
E: Safe to call repeatedly.
"""
def ensure_recording_dir() {
    os.makedirs(RECORDING_DIR, exist_ok=True);
}

"""R: Build recording file path for one session.
M: Joins recording dir with `<recording_id>.json`.
E: Caller validates recording id shape.
"""
def recording_file(recording_id: str) -> str {
    return RECORDING_DIR + "/" + recording_id + ".json";
}

"""R: Read one persisted recording session from disk.
M: Loads JSON and returns dict payload when valid.
E: Missing/invalid files map to empty dict.
"""
def read_recording(recording_id: str) -> dict[str, Any] {
    path = recording_file(recording_id);
    if not os.path.exists(path) {
        return {};
    }

    try {
        with open(path, "r") as f {
            parsed = json.load(f);
            if isinstance(parsed, dict) {
                return parsed;
            }
        }
    } except json.JSONDecodeError {
        return {};
    } except OSError {
        return {};
    }

    return {};
}

"""R: Load the recording referenced by a command payload.
M: Extracts `recording_id`, reads the stored session, and returns both on success.
E: Missing ids and unknown sessions map to stable `ok: false` errors.
"""
def load_recording_from_payload(payload: dict[str, Any]) -> dict[str, Any] {
    recording_id: str = str(payload.get("recording_id", ""));
    if not recording_id {
        return {"ok": False, "error": "recording_id is required"};
    }

    rec: dict[str, Any] = read_recording(recording_id);
    if not rec {
        return {"ok": False, "error": "recording not found", "recording_id": recording_id};
    }

    return {"ok": True, "recording_id": recording_id, "recording": rec};
}

"""R: Persist one recording session JSON record.
M: Writes formatted JSON to the session file path.
E: Propagates filesystem errors to caller.
"""
def write_recording(recording_id: str, rec: dict[str, Any]) {
    ensure_recording_dir();
    with open(recording_file(recording_id), "w") as f {
        json.dump(rec, f, indent=2);
    }
}

"""R: Parse JSON payload passed via CLI args.
M: Joins argv entries from index 2 and decodes JSON.
E: Invalid JSON returns an empty dict.
"""
def parse_payload() -> dict[str, Any] {
    raw_payload: str = "{}";
    if len(sys.argv) > 2 {
        raw_payload = " ".join(sys.argv[2:]);
    }

    try {
        parsed = json.loads(raw_payload);
        if isinstance(parsed, dict) {
            return parsed;
        }
        return {};
    } except json.JSONDecodeError {
        return {};
    }
}

# ============================================================
# CONTINUATION VALIDATION
# ============================================================

"""R: Validate options dict for a scroll_for_more strategy entry.
M: Checks scroll_style (if present) is in VALID_SCROLL_STYLES; max_scrolls (if present) is a positive int.
E: Empty options dict is valid. Booleans are rejected for numeric fields.
"""
def validate_scroll_for_more_options(options: dict[str, Any]) -> dict[str, Any] {
    scroll_style = options.get("scroll_style", None);
    if scroll_style is not None {
        if not isinstance(scroll_style, str) {
            return {"ok": False, "error": "scroll_style must be a string"};
        }
        if not (scroll_style in VALID_SCROLL_STYLES) {
            return {"ok": False, "error": "invalid scroll_style: " + str(scroll_style)};
        }
    }

    max_scrolls = options.get("max_scrolls", None);
    if max_scrolls is not None {
        if isinstance(max_scrolls, bool) or not isinstance(max_scrolls, int) {
            return {"ok": False, "error": "max_scrolls must be an integer"};
        }
        if max_scrolls <= 0 {
            return {"ok": False, "error": "max_scrolls must be a positive integer"};
        }
    }

    return {"ok": True};
}

"""R: Validate options dict for a next_page strategy entry.
M: Checks button_hint (if present) is a string; max_pages (if present) is a positive int.
E: Empty options dict is valid. Booleans are rejected for numeric fields.
"""
def validate_next_page_options(options: dict[str, Any]) -> dict[str, Any] {
    button_hint = options.get("button_hint", None);
    if button_hint is not None and not isinstance(button_hint, str) {
        return {"ok": False, "error": "button_hint must be a string"};
    }

    max_pages = options.get("max_pages", None);
    if max_pages is not None {
        if isinstance(max_pages, bool) or not isinstance(max_pages, int) {
            return {"ok": False, "error": "max_pages must be an integer"};
        }
        if max_pages <= 0 {
            return {"ok": False, "error": "max_pages must be a positive integer"};
        }
    }

    return {"ok": True};
}

"""R: Validate a single continuation strategy item.
M: Checks required keys (mode, options), validates mode is known, delegates mode-specific options validation.
E: Returns the first validation failure encountered; item must be a dict with non-empty string mode.
"""
def validate_strategy_item(item: Any) -> dict[str, Any] {
    if not isinstance(item, dict) {
        return {"ok": False, "error": "strategy entry must be a dict"};
    }

    mode = item.get("mode", None);
    if mode is None {
        return {"ok": False, "error": "strategy entry missing mode"};
    }
    if not isinstance(mode, str) or mode == "" {
        return {"ok": False, "error": "strategy entry mode must be a non-empty string"};
    }
    if not (mode in VALID_CONTINUATION_MODES) {
        return {"ok": False, "error": "unknown continuation mode: " + str(mode)};
    }

    if not ("options" in item) {
        return {"ok": False, "error": "strategy entry missing options"};
    }
    options = item.get("options", {});
    if not isinstance(options, dict) {
        return {"ok": False, "error": "strategy entry options must be a dict"};
    }

    if mode == "scroll_for_more" {
        return validate_scroll_for_more_options(options);
    }
    if mode == "next_page" {
        return validate_next_page_options(options);
    }

    # next_similar_item, manual_pick_next, stop: options may be empty in v1
    return {"ok": True};
}

"""R: Validate a full continuation strategy list.
M: Checks the value is a list, then validates each entry; returns first failure with its index.
E: Empty list is valid. Index is included in error messages for debuggability.
"""
def validate_continuation_strategy(strategy: Any) -> dict[str, Any] {
    if not isinstance(strategy, list) {
        return {"ok": False, "error": "continuation strategy must be a list"};
    }

    for (i, item) in enumerate(strategy) {
        result = validate_strategy_item(item);
        if not result.get("ok", False) {
            return {
                "ok": False,
                "error": "strategy[" + str(i) + "]: " + str(result.get("error", "invalid"))
            };
        }
    }

    return {"ok": True};
}

# ============================================================
# STOP POLICY VALIDATION
# ============================================================

"""R: Validate a stop policy dict.
M: Checks required keys (mode, options), validates mode is known, enforces count for count-based modes.
E: count must be a positive integer (not a boolean) for after_n_successes and after_n_reviews.
"""
def validate_stop_policy(stop_policy: Any) -> dict[str, Any] {
    if not isinstance(stop_policy, dict) {
        return {"ok": False, "error": "stop_policy must be a dict"};
    }

    mode = stop_policy.get("mode", None);
    if mode is None {
        return {"ok": False, "error": "stop_policy missing mode"};
    }
    if not isinstance(mode, str) or mode == "" {
        return {"ok": False, "error": "stop_policy mode must be a non-empty string"};
    }
    if not (mode in VALID_STOP_MODES) {
        return {"ok": False, "error": "unknown stop_policy mode: " + str(mode)};
    }

    if not ("options" in stop_policy) {
        return {"ok": False, "error": "stop_policy missing options"};
    }
    options = stop_policy.get("options", {});
    if not isinstance(options, dict) {
        return {"ok": False, "error": "stop_policy options must be a dict"};
    }

    if mode in COUNT_REQUIRED_STOP_MODES {
        count = options.get("count", None);
        if count is None {
            return {"ok": False, "error": "stop_policy " + mode + " requires options.count"};
        }
        if isinstance(count, bool) or not isinstance(count, int) {
            return {"ok": False, "error": "stop_policy options.count must be an integer"};
        }
        if count <= 0 {
            return {"ok": False, "error": "stop_policy options.count must be positive"};
        }
    }

    return {"ok": True};
}

# ============================================================
# STATE MACHINE
# ============================================================

"""R: Check whether a state transition is allowed.
M: Looks up the from_state in ALLOWED_TRANSITIONS and checks to_state is in the valid list.
E: Any unknown from_state has no valid transitions (returns False).
"""
def transition_allowed(from_state: str, to_state: str) -> bool {
    allowed: list[Any] = ALLOWED_TRANSITIONS.get(from_state, []);
    return to_state in allowed;
}

"""R: Apply a state transition to a recording session dict in place.
M: Validates the transition is allowed, then mutates state and updated_at on the dict.
E: Returns error dict if the transition is not allowed; on success returns ok dict.
"""
def apply_transition(rec: dict[str, Any], to_state: str) -> dict[str, Any] {
    from_state: str = str(rec.get("state", ""));
    if not transition_allowed(from_state, to_state) {
        return {
            "ok": False,
            "error": "transition not allowed",
            "from": from_state,
            "to": to_state
        };
    }
    rec["state"] = to_state;
    rec["updated_at"] = timestamp_now();
    return {"ok": True};
}

# ============================================================
# SEGMENTED RECORDING DATA MODEL
# ============================================================

"""R: Build the initial segmented recording session structure in idle state.
M: Creates one_time and repeated segments (each with empty events/annotations),
   plus stub continuation and stop_policy for use in the next pass.
E: No mode is auto-selected; state starts at idle.
"""
def new_recording_session(task_name: str, meta: dict[str, Any]) -> dict[str, Any] {
    domains: list[Any] = [];
    raw_domains = meta.get("domains", []);
    if isinstance(raw_domains, list) {
        domains = raw_domains;
    }
    now: str = timestamp_now();

    return {
        "recording_id": new_recording_id(),
        "task_name": task_name,
        "created_at": now,
        "updated_at": now,
        "state": STATE_IDLE,
        "segments": {
            "one_time": {
                "events": [],
                "annotations": []
            },
            "repeated": {
                "events": [],
                "annotations": []
            }
        },
        "continuation": {
            "strategy": []
        },
        "stop_policy": {
            "mode": "",
            "options": {}
        },
        "meta": {
            "start_url": str(meta.get("start_url", "")),
            "domains": domains,
            "user_goal": str(meta.get("user_goal", ""))
        }
    };
}

"""R: Determine which segment name the current state writes to.
M: Maps recording_one_time -> one_time, recording_repeated -> repeated.
E: Returns empty string when not in an active recording state.
"""
def active_segment(state: str) -> str {
    if state == STATE_RECORDING_ONE_TIME {
        return "one_time";
    }
    if state == STATE_RECORDING_REPEATED {
        return "repeated";
    }
    return "";
}

"""R: Append one stamped payload item to the active recording segment.
M: Resolves the active segment, adds timestamp and segment metadata, then appends into the target list.
E: Returns `ok: false` when the recording is not actively capturing a segment.
"""
def append_to_active_segment(
    rec: dict[str, Any],
    item: dict[str, Any],
    collection_key: str,
    stamp_key: str
) -> dict[str, Any] {
    state: str = str(rec.get("state", ""));
    seg_name: str = active_segment(state);
    if not seg_name {
        return {
            "ok": False,
            "error": "no active recording segment in state: " + state
        };
    }

    segments: dict[str, Any] = rec.get("segments", {});
    seg: dict[str, Any] = segments.get(seg_name, {});

    items: list[Any] = [];
    raw_items = seg.get(collection_key, []);
    if isinstance(raw_items, list) {
        items = raw_items;
    }

    now: str = timestamp_now();
    stamped: dict[str, Any] = dict(item);
    stamped[stamp_key] = now;
    stamped["segment"] = seg_name;
    items.append(stamped);

    seg[collection_key] = items;
    segments[seg_name] = seg;
    rec["segments"] = segments;
    rec["updated_at"] = now;

    return {"ok": True, "segment": seg_name, "count": len(items)};
}

"""R: Append one event to the correct segment based on current session state.
M: Resolves segment via active_segment, stamps with recorded_at and segment name, appends.
E: Returns error if session is not in an active recording state.
"""
def append_event_to_segment(rec: dict[str, Any], event: dict[str, Any]) -> dict[str, Any] {
    result: dict[str, Any] = append_to_active_segment(rec, event, "events", "recorded_at");
    if not result.get("ok", False) {
        return result;
    }

    return {"ok": True, "segment": result["segment"], "event_count": result["count"]};
}

"""R: Append one annotation to the correct segment based on current session state.
M: Resolves segment via active_segment, stamps with annotated_at and segment name, appends.
E: Returns error if session is not in an active recording state.
"""
def append_annotation_to_segment(rec: dict[str, Any], annotation: dict[str, Any]) -> dict[str, Any] {
    result: dict[str, Any] = append_to_active_segment(rec, annotation, "annotations", "annotated_at");
    if not result.get("ok", False) {
        return result;
    }

    return {"ok": True, "segment": result["segment"], "annotation_count": result["count"]};
}

"""R: Apply one state transition command to a stored recording.
M: Loads the target recording, performs the transition, and persists the updated state.
E: Missing recordings and invalid transitions return the original error payloads unchanged.
"""
def transition_recording_command(payload: dict[str, Any], to_state: str) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }

    recording_id: str = str(loaded.get("recording_id", ""));
    rec: dict[str, Any] = loaded.get("recording", {});

    result: dict[str, Any] = apply_transition(rec, to_state);
    if not result.get("ok", False) {
        return result;
    }

    write_recording(recording_id, rec);
    return {"ok": True, "recording_id": recording_id, "state": rec["state"]};
}

# ============================================================
# COMMAND HANDLERS
# ============================================================

"""R: Create a new recording session in idle state.
M: Builds default segmented session, persists to disk, returns recording_id.
E: Optional task_name and meta fields; defaults are empty/minimal.
"""
def cmd_create(payload: dict[str, Any]) -> dict[str, Any] {
    task_name: str = str(payload.get("task_name", ""));
    meta: dict[str, Any] = {};
    raw_meta = payload.get("meta", {});
    if isinstance(raw_meta, dict) {
        meta = raw_meta;
    }

    rec = new_recording_session(task_name, meta);
    rec_id: str = str(rec["recording_id"]);
    write_recording(rec_id, rec);

    return {
        "ok": True,
        "recording_id": rec_id,
        "state": rec["state"],
        "recording_file": recording_file(rec_id)
    };
}

"""R: Transition to recording_one_time from idle or recording_repeated.
M: Loads session, applies transition, persists.
E: Fails if current state does not allow this transition.
"""
def cmd_enter_one_time(payload: dict[str, Any]) -> dict[str, Any] {
    return transition_recording_command(payload, STATE_RECORDING_ONE_TIME);
}

"""R: Transition to recording_repeated from idle or recording_one_time.
M: Loads session, applies transition, persists.
E: Fails if current state does not allow this transition.
"""
def cmd_enter_repeated(payload: dict[str, Any]) -> dict[str, Any] {
    return transition_recording_command(payload, STATE_RECORDING_REPEATED);
}

"""R: Append one event to the active recording segment.
M: Resolves segment from current state, appends event with timestamp, persists.
E: Fails if session is not in an active recording state.
"""
def cmd_append_event(payload: dict[str, Any]) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }
    recording_id: str = str(loaded.get("recording_id", ""));
    rec: dict[str, Any] = loaded.get("recording", {});

    event: dict[str, Any] = {};
    raw_event = payload.get("event", {});
    if isinstance(raw_event, dict) {
        event = raw_event;
    }

    result = append_event_to_segment(rec, event);
    if not result.get("ok", False) {
        return result;
    }

    write_recording(recording_id, rec);
    return {
        "ok": True,
        "recording_id": recording_id,
        "segment": result["segment"],
        "event_count": result["event_count"]
    };
}

"""R: Append one annotation to the active recording segment.
M: Resolves segment from current state, appends annotation with timestamp, persists.
E: Fails if session is not in an active recording state.
"""
def cmd_append_annotation(payload: dict[str, Any]) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }
    recording_id: str = str(loaded.get("recording_id", ""));
    rec: dict[str, Any] = loaded.get("recording", {});

    annotation: dict[str, Any] = {};
    raw_ann = payload.get("annotation", {});
    if isinstance(raw_ann, dict) {
        annotation = raw_ann;
    }

    result = append_annotation_to_segment(rec, annotation);
    if not result.get("ok", False) {
        return result;
    }

    write_recording(recording_id, rec);
    return {
        "ok": True,
        "recording_id": recording_id,
        "segment": result["segment"],
        "annotation_count": result["annotation_count"]
    };
}

"""R: Mark the repeated example as complete and advance state.
M: Transitions recording_repeated -> repeated_example_complete.
E: Fails if not currently in recording_repeated state.
"""
def cmd_finish_repeated_example(payload: dict[str, Any]) -> dict[str, Any] {
    return transition_recording_command(payload, STATE_REPEATED_EXAMPLE_COMPLETE);
}

"""R: Move to configuring_continuation and store a validated strategy list.
M: Validates the strategy before touching state; transitions repeated_example_complete ->
   configuring_continuation, or stays in configuring_continuation (allows re-configure).
E: Validation errors return ok:false without mutating stored state.
   Re-calling while already in configuring_continuation replaces the strategy in place.
"""
def cmd_configure_continuation(payload: dict[str, Any]) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }
    recording_id: str = str(loaded.get("recording_id", ""));
    rec: dict[str, Any] = loaded.get("recording", {});

    # Validate before mutating anything
    raw_strategy = payload.get("strategy", []);
    validation = validate_continuation_strategy(raw_strategy);
    if not validation.get("ok", False) {
        return {"ok": False, "error": validation.get("error", "invalid strategy")};
    }

    state: str = str(rec.get("state", ""));
    if state == STATE_REPEATED_EXAMPLE_COMPLETE {
        result = apply_transition(rec, STATE_CONFIGURING_CONTINUATION);
        if not result.get("ok", False) {
            return result;
        }
    } elif state != STATE_CONFIGURING_CONTINUATION {
        return {
            "ok": False,
            "error": "configure_continuation not allowed in state: " + state
        };
    }

    strategy: list[Any] = [];
    if isinstance(raw_strategy, list) {
        strategy = raw_strategy;
    }

    rec["continuation"] = {"strategy": strategy};
    write_recording(recording_id, rec);
    return {"ok": True, "recording_id": recording_id, "state": rec["state"]};
}

"""R: Store a validated stop policy on the recording.
M: Validates the stop_policy structure and mode-specific options, then writes to recording.
E: Only allowed in configuring_continuation state. No state transition occurs.
   Validation errors return ok:false without mutating stored data.
"""
def cmd_configure_stop_policy(payload: dict[str, Any]) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }
    recording_id: str = str(loaded.get("recording_id", ""));
    rec: dict[str, Any] = loaded.get("recording", {});

    state: str = str(rec.get("state", ""));
    if state != STATE_CONFIGURING_CONTINUATION {
        return {
            "ok": False,
            "error": "configure_stop_policy not allowed in state: " + state
        };
    }

    raw_sp = payload.get("stop_policy", {});
    validation = validate_stop_policy(raw_sp);
    if not validation.get("ok", False) {
        return {"ok": False, "error": validation.get("error", "invalid stop_policy")};
    }

    sp: dict[str, Any] = {};
    if isinstance(raw_sp, dict) {
        sp = raw_sp;
    }

    rec["stop_policy"] = sp;
    write_recording(recording_id, rec);
    return {"ok": True, "recording_id": recording_id, "state": rec["state"]};
}

"""R: Mark a recording session as finished.
M: Transitions current state -> finished, persists.
E: Fails if current state does not allow transition to finished.
"""
def cmd_finish(payload: dict[str, Any]) -> dict[str, Any] {
    return transition_recording_command(payload, STATE_FINISHED);
}

"""R: Fetch a stored recording session by recording_id.
M: Loads recording JSON and returns the parsed dict.
E: Missing sessions return explicit errors.
"""
def cmd_get(payload: dict[str, Any]) -> dict[str, Any] {
    loaded: dict[str, Any] = load_recording_from_payload(payload);
    if not loaded.get("ok", False) {
        return loaded;
    }

    return {"ok": True, "recording": loaded["recording"]};
}

# ============================================================
# DISPATCH
# ============================================================

"""R: Route a layer command to its recording operation.
M: Maps command text to recording state machine handlers.
E: Unknown commands return a usage payload with valid command list.
"""
def dispatch(command: str, payload: dict[str, Any]) -> dict[str, Any] {
    if command == "create" {
        return cmd_create(payload);
    }
    if command == "enter_one_time" {
        return cmd_enter_one_time(payload);
    }
    if command == "enter_repeated" {
        return cmd_enter_repeated(payload);
    }
    if command == "append_event" {
        return cmd_append_event(payload);
    }
    if command == "append_annotation" {
        return cmd_append_annotation(payload);
    }
    if command == "finish_repeated_example" {
        return cmd_finish_repeated_example(payload);
    }
    if command == "configure_continuation" {
        return cmd_configure_continuation(payload);
    }
    if command == "configure_stop_policy" {
        return cmd_configure_stop_policy(payload);
    }
    if command == "finish" {
        return cmd_finish(payload);
    }
    if command == "get" {
        return cmd_get(payload);
    }

    return {
        "ok": False,
        "error": "unknown command",
        "valid_commands": [
            "create", "enter_one_time", "enter_repeated",
            "append_event", "append_annotation",
            "finish_repeated_example", "configure_continuation",
            "configure_stop_policy", "finish", "get"
        ]
    };
}

"""R: Decide whether this module should execute its CLI entrypoint.
M: Treats non-empty, non-path-like argv values as commands and ignores import-time script paths.
E: Unknown direct commands still dispatch so the caller gets the usual usage payload.
"""
def should_dispatch_cli(command: str) -> bool {
    if not command {
        return False;
    }

    return ("/" not in command) and ("\\" not in command) and not command.endswith(".jac");
}

with entry {
    command: str = "";
    if len(sys.argv) > 1 {
        command = str(sys.argv[1]);
    }

    if should_dispatch_cli(command) {
        payload = parse_payload();
        result = dispatch(command, payload);
        print(json.dumps(result));
    }
}

import os;
import json;
import from typing { Any }

glob DATA_ROOT: str = "./jac/layer_data";
glob TRACE_DIR: str = DATA_ROOT + "/traces";

"""R: Build the persisted observation trace file path for one session id.
M: Joins the shared trace directory with the session id and `.json` suffix.
E: Caller is responsible for passing a valid session id string.
"""
def trace_file(session_id: str) -> str {
    return TRACE_DIR + "/" + session_id + ".json";
}

"""R: Read one persisted observation trace from disk without triggering any CLI entrypoints.
M: Loads the trace JSON file and returns it only when the parsed payload is a dict.
E: Missing files, invalid JSON, and filesystem read errors all return an empty dict.
"""
def read_trace(session_id: str) -> dict[str, Any] {
    path = trace_file(session_id);
    if not os.path.exists(path) {
        return {};
    }

    try {
        with open(path, "r") as file {
            parsed = json.load(file);
            if isinstance(parsed, dict) {
                return parsed;
            }
        }
    } except json.JSONDecodeError {
        return {};
    } except OSError {
        return {};
    }

    return {};
}

"""
Jac-native compile-time enrichment client.

Purpose:
- Resolve local or hosted LLM configuration from `.env` and process environment.
- Call either a Moonshot-hosted Kimi model or a truly local Ollama model.
- Return a small enrichment object that the compilation layer can merge safely.
"""

import os;
import json;
import time;
import subprocess;
import from typing { Any }
import from shutil { which }
import from urllib.request { Request, urlopen }
import from urllib.error { HTTPError, URLError }

glob DEFAULT_KIMI_BASE_URL: str = "https://api.moonshot.ai/v1";
glob DEFAULT_KIMI_MODEL: str = "kimi-k2.5";
glob DEFAULT_OLLAMA_BASE_URL: str = "http://127.0.0.1:11434";
glob DEFAULT_OLLAMA_MODEL: str = "qwen2.5:3b-instruct-q4_0";
glob OLLAMA_LOG_DIR: str = "./jac/layer_data/llm";
glob OLLAMA_LOG_FILE: str = OLLAMA_LOG_DIR + "/ollama-serve.log";
glob KIMI_CLI_CONFIG_PATH: str = os.path.expanduser("~/.kimi/config.toml");
glob KIMI_CLI_AGENT_FILE: str = os.path.abspath("./jac/llm/kimi_compile_agent.yaml");
glob KIMI_CLI_READY_PROMPT: str = "Reply with exactly READY and nothing else.";

"""R: Normalize quoted config values reused across dotenv and TOML parsing.
M: Trims whitespace and removes one matching pair of wrapping quotes.
E: Unbalanced or unquoted strings are returned unchanged.
"""
def strip_wrapping_quotes(raw_value: str) -> str {
    value: str = str(raw_value or "").strip();
    if len(value) >= 2 {
        if (value.startswith("\"") and value.endswith("\"")) or
           (value.startswith("'") and value.endswith("'")) {
            return value[1:-1];
        }
    }

    return value;
}

"""R: Parse one local `.env` file into a small key/value map.
M: Reads non-comment `KEY=VALUE` lines and trims optional wrapping quotes.
E: Missing files and malformed lines are ignored so runtime config stays fail-soft.
"""
def parse_dotenv(path: str = ".env") -> dict[str, str] {
    values: dict[str, str] = {};
    if not os.path.exists(path) {
        return values;
    }

    try {
        with open(path, "r") as file {
            for raw_line in file {
                line: str = str(raw_line).strip();
                if not line or line.startswith("#") or "=" not in line {
                    continue;
                }

                split_at: int = line.find("=");
                key: str = str(line[:split_at]).strip();
                value: str = strip_wrapping_quotes(str(line[split_at + 1:]).strip());
                if not key {
                    continue;
                }

                values[key] = value;
            }
        }
    } except OSError {
        return {};
    }

    return values;
}

"""R: Read one config value from process env first, then `.env`, then fallback.
M: Checks `os.environ`, falls back to parsed dotenv values, and trims whitespace.
E: Empty values collapse to the provided fallback.
"""
def env_value(name: str, dotenv: dict[str, str], fallback: str = "") -> str {
    process_value: str = str(os.environ.get(name, "") or "").strip();
    if process_value {
        return process_value;
    }

    file_value: str = str(dotenv.get(name, "") or "").strip();
    if file_value {
        return file_value;
    }

    return fallback;
}

"""R: Detect placeholder secrets so the compiler does not attempt fake API calls.
M: Rejects empty values and common sample-token markers like `your-...` and `replace-me`.
E: Conservative heuristic may classify custom sample values as placeholders.
"""
def is_placeholder_secret(raw_value: str) -> bool {
    value: str = str(raw_value or "").strip();
    if not value {
        return True;
    }

    lowered: str = value.lower();
    if lowered.startswith("your-") or lowered.startswith("sk-your-") {
        return True;
    }
    if "replace" in lowered or "placeholder" in lowered or "api-key" in lowered {
        return True;
    }

    return False;
}

"""R: Convert loose env strings into booleans.
M: Accepts common truthy tokens used in `.env` files.
E: Unknown values resolve to false.
"""
def env_bool(raw_value: str) -> bool {
    lowered: str = str(raw_value or "").strip().lower();
    return lowered in ["1", "true", "yes", "on", "enabled"];
}

"""R: Resolve the usable local Ollama binary path without requiring a system install.
M: Checks PATH first, then falls back to the user-local install path used by this project.
E: Missing binaries resolve to the empty string.
"""
def find_ollama_binary() -> str {
    path: str = str(which("ollama") or "").strip();
    if path {
        return path;
    }

    fallback: str = os.path.expanduser("~/.local/bin/ollama");
    if os.path.exists(fallback) {
        return fallback;
    }
    return "";
}

"""R: Normalize a local Ollama base URL whether config uses the root or `/v1`.
M: Trims a trailing slash and strips one `/v1` suffix so health checks hit the native API.
E: Empty values fall back to the default localhost Ollama URL.
"""
def ollama_root_base_url(raw_base_url: str) -> str {
    base_url: str = str(raw_base_url or DEFAULT_OLLAMA_BASE_URL).strip().rstrip("/");
    if not base_url {
        return DEFAULT_OLLAMA_BASE_URL;
    }
    if base_url.endswith("/v1") {
        return str(base_url[:-3]).rstrip("/");
    }
    return base_url;
}

"""R: Read one small JSON document over HTTP.
M: Uses stdlib URL loading and returns a decoded object when the response is a dict.
E: Network failures and malformed JSON degrade to the provided fallback dict.
"""
def read_json_url(url: str, fallback: dict[str, Any] = {}, timeout: int = 5) -> dict[str, Any] {
    try {
        response: Any = urlopen(url, timeout=timeout);
        raw_bytes: Any = response.read();
        response.close();
        parsed: Any = json.loads(str(raw_bytes.decode("utf-8")));
        if isinstance(parsed, dict) {
            return parsed;
        }
    } except OSError {
        return fallback;
    } except json.JSONDecodeError {
        return fallback;
    }
    return fallback;
}

"""R: Return the set of models currently available from the local Ollama daemon.
M: Calls the native `/api/tags` endpoint and extracts each advertised model name.
E: Missing or offline daemons return an empty list.
"""
def local_ollama_model_names(base_url: str) -> list[str] {
    tags: dict[str, Any] = read_json_url(ollama_root_base_url(base_url) + "/api/tags", {}, 5);
    models: Any = tags.get("models", []);
    names: list[str] = [];
    if not isinstance(models, list) {
        return names;
    }

    for model_info in models {
        if not isinstance(model_info, dict) {
            continue;
        }
        name: str = str(model_info.get("name", "")).strip();
        if name {
            names.append(name);
        }
    }
    return names;
}

"""R: Check whether the local Ollama HTTP API is responding.
M: Reads `/api/version` and treats a non-empty version field as ready.
E: Offline daemons return false without raising.
"""
def local_ollama_ready(base_url: str) -> bool {
    version_info: dict[str, Any] = read_json_url(ollama_root_base_url(base_url) + "/api/version", {}, 3);
    return str(version_info.get("version", "")).strip() != "";
}

"""R: Start the local Ollama daemon in the background when local compile mode is selected.
M: Launches `ollama serve` detached with localhost binding, no cloud remotes, and a small log file.
E: If the daemon is already up or the binary is missing, this safely returns false.
"""
def start_local_ollama_server(base_url: str) -> bool {
    if local_ollama_ready(base_url) {
        return True;
    }

    cli_path: str = find_ollama_binary();
    if not cli_path {
        return False;
    }

    os.makedirs(OLLAMA_LOG_DIR, exist_ok=True);
    log_file: Any = None;
    try {
        log_file = open(OLLAMA_LOG_FILE, "a");
        subprocess.Popen(
            [cli_path, "serve"],
            stdout=log_file,
            stderr=log_file,
            start_new_session=True,
            env={
                **os.environ,
                "OLLAMA_HOST": ollama_root_base_url(base_url),
                "OLLAMA_NO_CLOUD": "1"
            }
        );
    } except OSError {
        if log_file is not None {
            log_file.close();
        }
        return False;
    }

    for _ in range(12) {
        time.sleep(0.5);
        if local_ollama_ready(base_url) {
            return True;
        }
    }
    return False;
}

"""R: Resolve whether the requested truly local Ollama model is available for compile enrichment.
M: Checks the binary, auto-starts the daemon when needed, then verifies the target model is installed.
E: Missing installs or models return explicit reasons so setup issues are easy to fix.
"""
def resolve_local_ollama_status(model: str, base_url: str) -> dict[str, Any] {
    cli_path: str = find_ollama_binary();
    status: dict[str, Any] = {
        "available": cli_path != "",
        "ready": False,
        "path": cli_path,
        "reason": ""
    };

    if not cli_path {
        status["reason"] = "Local Ollama is not installed.";
        return status;
    }

    if not local_ollama_ready(base_url) and not start_local_ollama_server(base_url) {
        status["reason"] = "Local Ollama could not be reached on " + ollama_root_base_url(base_url) + ".";
        return status;
    }

    model_names: list[str] = local_ollama_model_names(base_url);
    if model not in model_names {
        status["reason"] = "Local Ollama is running, but model `" + model + "` is not installed. Run `ollama pull " + model + "`.";
        return status;
    }

    status["ready"] = True;
    status["reason"] = "Local compile enrichment enabled via Ollama.";
    return status;
}

"""R: Read the default model from the local `kimi` CLI config when present.
M: Scans the top-level `default_model = ...` line in `~/.kimi/config.toml`.
E: Missing files, unreadable config, or empty values resolve to the empty string.
"""
def read_kimi_cli_default_model(config_path: str = KIMI_CLI_CONFIG_PATH) -> str {
    path: str = os.path.expanduser(str(config_path or KIMI_CLI_CONFIG_PATH));
    if not os.path.exists(path) {
        return "";
    }

    try {
        with open(path, "r") as file {
            for raw_line in file {
                line: str = str(raw_line).strip();
                if not line or line.startswith("#") or line.startswith("[") or "=" not in line {
                    continue;
                }

                if not line.startswith("default_model") {
                    continue;
                }

                split_at: int = line.find("=");
                if split_at < 0 {
                    continue;
                }

                return strip_wrapping_quotes(str(line[split_at + 1:]).strip());
            }
        }
    } except OSError {
        return "";
    }

    return "";
}

"""R: Return the first non-empty line from tool output for concise status messages.
M: Scans line-by-line and stops at the first trimmed value.
E: Empty multi-line strings return the empty string.
"""
def first_non_empty_line(raw_text: str) -> str {
    for raw_line in str(raw_text or "").splitlines() {
        line: str = str(raw_line).strip();
        if line {
            return line;
        }
    }
    return "";
}

"""R: Build the exact local `kimi` CLI command used for probes and compile calls.
M: Uses print mode plus a no-tools agent file so the CLI only returns text.
E: Missing agent files are skipped so the command still works in degraded environments.
"""
def build_kimi_cli_command(prompt: str, config: dict[str, Any]) -> list[str] {
    command: list[str] = [
        str(config.get("cli_path", "") or "kimi"),
        "--quiet",
        "--print",
        "--output-format",
        "text",
        "--final-message-only"
    ];

    if os.path.exists(KIMI_CLI_AGENT_FILE) {
        command.append("--agent-file");
        command.append(KIMI_CLI_AGENT_FILE);
    }

    thinking_flag: str = "--thinking" if str(config.get("thinking_mode", "disabled")) == "enabled" else "--no-thinking";
    command.append(thinking_flag);

    model: str = str(config.get("model", "") or "").strip();
    if model {
        command.append("-m");
        command.append(model);
    }

    command.append("-p");
    command.append(prompt);
    return command;
}

"""R: Determine whether the local `kimi` CLI is installed and ready for non-interactive use.
M: Checks the binary, reads its default model, then runs one tiny readiness prompt.
E: Missing installs, missing login, timeouts, and auth failures return a descriptive inactive state.
"""
def resolve_kimi_cli_status(thinking_mode: str = "disabled") -> dict[str, Any] {
    cli_path: str = str(which("kimi") or "").strip();
    default_model: str = read_kimi_cli_default_model();
    status: dict[str, Any] = {
        "available": cli_path != "",
        "configured": False,
        "ready": False,
        "path": cli_path,
        "model": default_model,
        "reason": ""
    };

    if not cli_path {
        status["reason"] = "Local `kimi` CLI is not installed.";
        return status;
    }

    if not default_model {
        status["reason"] = "Kimi CLI is installed but not logged in. Run `kimi login` once to authorize it.";
        return status;
    }

    status["configured"] = True;

    try {
        probe_result: Any = subprocess.run(
            build_kimi_cli_command(
                KIMI_CLI_READY_PROMPT,
                {
                    "cli_path": cli_path,
                    "model": default_model,
                    "thinking_mode": thinking_mode
                }
            ),
            capture_output=True,
            text=True,
            timeout=20
        );
    } except subprocess.TimeoutExpired {
        status["reason"] = "Kimi CLI probe timed out.";
        return status;
    } except OSError as err {
        status["reason"] = "Kimi CLI could not be started: " + str(err);
        return status;
    }

    stdout: str = str(probe_result.stdout or "").strip();
    stderr: str = str(probe_result.stderr or "").strip();
    combined: str = "\n".join([stdout, stderr]).strip();
    first_line: str = first_non_empty_line(combined);
    lowered: str = first_line.lower();

    if probe_result.returncode == 0 and stdout == "READY" {
        status["ready"] = True;
        status["reason"] = "Kimi compile enrichment enabled via local `kimi` CLI.";
        return status;
    }

    if "llm not set" in lowered or "login" in lowered {
        status["configured"] = False;
        status["reason"] = "Kimi CLI is installed but not logged in. Run `kimi login` once to authorize it.";
        return status;
    }

    status["reason"] = "Kimi CLI is installed but not ready" + (": " + first_line if first_line else ".");
    return status;
}

"""R: Build the effective compile configuration from local settings.
M: Supports a truly local Ollama model plus the existing hosted Moonshot Kimi path.
E: Returns `enabled: false` with a concrete reason when the selected provider is unavailable.
"""
def resolve_kimi_compile_config() -> dict[str, Any] {
    dotenv: dict[str, str] = parse_dotenv();

    provider: str = env_value("LLM_PROVIDER", dotenv, "").lower();
    local_requested: bool = provider in ["ollama", "local"];
    model_fallback: str = DEFAULT_OLLAMA_MODEL if local_requested else DEFAULT_KIMI_MODEL;
    base_url_fallback: str = DEFAULT_OLLAMA_BASE_URL if local_requested else DEFAULT_KIMI_BASE_URL;
    model: str = env_value("LLM_MODEL", dotenv, env_value("MOONSHOT_MODEL", dotenv, env_value("MODEL", dotenv, model_fallback)));
    base_url: str = env_value("LLM_BASE_URL", dotenv, env_value("MOONSHOT_BASE_URL", dotenv, base_url_fallback)).rstrip("/");
    api_key: str = env_value(
        "LLM_API_KEY",
        dotenv,
        env_value("MOONSHOT_API_KEY", dotenv, "")
    );
    thinking_mode: str = env_value("KIMI_THINKING", dotenv, "disabled").lower();
    allow_compile_raw: str = env_value("LLM_ALLOW_COMPILE", dotenv, "true");
    normalized_thinking_mode: str = thinking_mode if thinking_mode in ["enabled", "disabled"] else "disabled";

    provider_requested: bool = provider in ["kimi", "moonshot"];
    local_selected: bool = local_requested or base_url.startswith("http://127.0.0.1:11434") or base_url.startswith("http://localhost:11434");
    model_requested: bool = str(model or "").lower().startswith("kimi-");
    allow_compile: bool = env_bool(allow_compile_raw);
    api_key_present: bool = str(api_key or "").strip() != "";
    api_key_placeholder: bool = is_placeholder_secret(api_key);
    api_key_ready: bool = api_key_present and not api_key_placeholder;
    ollama_status: dict[str, Any] = {};
    cli_status: dict[str, Any] = resolve_kimi_cli_status(normalized_thinking_mode);
    cli_ready: bool = bool(cli_status.get("ready", False));

    enabled: bool = False;
    resolved_provider: str = "kimi";
    reason: str = "Compile enrichment enabled";
    transport: str = "";
    resolved_model: str = model if model else DEFAULT_KIMI_MODEL;

    if local_selected {
        resolved_provider = "ollama";
        resolved_model = model if model else DEFAULT_OLLAMA_MODEL;
        base_url = ollama_root_base_url(base_url if base_url else DEFAULT_OLLAMA_BASE_URL);
        if not allow_compile {
            reason = "LLM_ALLOW_COMPILE is disabled.";
        } else {
            ollama_status = resolve_local_ollama_status(resolved_model, base_url);
            if bool(ollama_status.get("ready", False)) {
                enabled = True;
                transport = "local";
                reason = str(ollama_status.get("reason", "Local compile enrichment enabled via Ollama."));
            } else {
                reason = str(ollama_status.get("reason", "Local Ollama compile enrichment is not configured."));
            }
        }
    } elif not (provider_requested or model_requested) {
        reason = "No compile provider is selected. Set LLM_PROVIDER=ollama for a truly local model or LLM_PROVIDER=kimi for Moonshot.";
    } elif not allow_compile {
        reason = "LLM_ALLOW_COMPILE is disabled.";
    } elif api_key_ready {
        enabled = True;
        transport = "api";
        reason = "Kimi compile enrichment enabled via Moonshot API.";
    } elif cli_ready {
        enabled = True;
        transport = "cli";
        resolved_model = str(cli_status.get("model", "") or resolved_model);
        reason = str(cli_status.get("reason", "Kimi compile enrichment enabled via local `kimi` CLI."));
    } else {
        api_reason: str = "";
        cli_reason: str = str(cli_status.get("reason", "") or "");

        if not api_key_present {
            api_reason = "LLM_API_KEY is missing.";
        } elif api_key_placeholder {
            api_reason = "LLM_API_KEY is still set to the placeholder value in .env.";
        }

        if api_reason and cli_reason {
            if not bool(cli_status.get("available", False)) {
                reason = api_reason + " Install the local `kimi` CLI and run `kimi login`, or add a real LLM_API_KEY.";
            } elif api_key_placeholder {
                reason = cli_reason + " The current LLM_API_KEY in .env is still a placeholder, so the hosted API path is also inactive.";
            } else {
                reason = cli_reason + " " + api_reason + " Add a real LLM_API_KEY if you want the hosted API path instead.";
            }
        } elif cli_reason {
            reason = cli_reason;
        } elif api_reason {
            reason = api_reason;
        } else {
            reason = "Kimi compile enrichment is not configured.";
        }
    }

    return {
        "enabled": enabled,
        "provider": resolved_provider,
        "transport": transport,
        "model": resolved_model if resolved_model else (DEFAULT_OLLAMA_MODEL if resolved_provider == "ollama" else DEFAULT_KIMI_MODEL),
        "base_url": base_url if base_url else (DEFAULT_OLLAMA_BASE_URL if resolved_provider == "ollama" else DEFAULT_KIMI_BASE_URL),
        "api_key": api_key if api_key_ready else "",
        "ollama_path": str(ollama_status.get("path", "") or find_ollama_binary()),
        "cli_path": str(cli_status.get("path", "") or ""),
        "thinking_mode": normalized_thinking_mode,
        "allow_compile": allow_compile,
        "reason": reason
    };
}

"""R: Build a compact event summary suitable for model-side workflow enrichment.
M: Keeps only event type, URL, labels, and masked values from the first few cleaned events.
E: Non-dict events are skipped; long values stay bounded by upstream normalization.
"""
def compact_event_summary(cleaned: dict[str, Any], limit: int = 10) -> list[Any] {
    items: list[Any] = [];
    events: Any = cleaned.get("events", []);
    if not isinstance(events, list) {
        return items;
    }

    count: int = 0;
    for event in events {
        if count >= limit or not isinstance(event, dict) {
            continue;
        }

        element: Any = event.get("element", {});
        target_label: str = "";
        if isinstance(element, dict) {
            target_label = str(
                element.get("label", "") or
                element.get("name", "") or
                element.get("placeholder", "") or
                element.get("innerText", "")
            );
        }

        items.append({
            "type": str(event.get("type", "")),
            "url": str(event.get("url", "")),
            "label": target_label,
            "value": "__redacted__" if bool(event.get("masked", False)) else str(event.get("value", ""))
        });
        count += 1;
    }

    return items;
}

"""R: Extract the highest-value semantic clues from raw observation events.
M: Scans recent events for `semantic` payloads and returns the newest non-empty fields.
E: Missing semantic telemetry yields an empty dict.
"""
def latest_semantic_summary(raw_session: dict[str, Any]) -> dict[str, Any] {
    summary: dict[str, Any] = {};
    events: Any = raw_session.get("events", []);
    if not isinstance(events, list) {
        return summary;
    }

    for raw_event in events {
        if not isinstance(raw_event, dict) {
            continue;
        }
        semantic: Any = raw_event.get("semantic", {});
        if not isinstance(semantic, dict) or not semantic {
            continue;
        }

        summary = {
            "title": str(semantic.get("title", "")),
            "page_kind": str(semantic.get("page_kind", "")),
            "workflow_stage": str(semantic.get("workflow_stage", "")),
            "primary_actions": semantic.get("primary_actions", []) if isinstance(semantic.get("primary_actions", []), list) else [],
            "headings": semantic.get("headings", []) if isinstance(semantic.get("headings", []), list) else []
        };
    }

    return summary;
}

"""R: Build the shared instructions sent to the selected model for compile enrichment.
M: Provides the heuristic workflow plus a strict JSON output contract.
E: Keeps the contract intentionally compact to reduce latency and parsing risk.
"""
def build_kimi_compile_instructions() -> str {
    return """
You are enriching a heuristic browser workflow compilation for Jac Browser.
Return exactly one JSON object.

Required output shape:
{
  "context": {
    "summary": "short paragraph",
    "successCriteria": ["criterion 1", "criterion 2"]
  },
  "steps": [
    {
      "type": "same as input step type",
      "name": "short human-readable step name",
      "confidence": 0.0
    }
  ],
  "model": {
    "provider": "provider name",
    "model": "model name",
    "thinking_mode": "disabled"
  }
}

Rules:
- Keep the exact same number of steps as the heuristic workflow.
- Keep each step type identical to the corresponding heuristic step.
- Only enrich summary, success criteria, step names, and confidence.
- Use the user's explanation when present to clarify intent and success criteria.
- Use confidence from 0.0 to 1.0.
- Be concise and practical.
""".strip();
}

"""R: Build the compact trace context shared by all compile enrichment transports.
M: Packages the cleaned event summary plus the heuristic workflow into one JSON object.
E: Missing optional fields degrade to empty strings, arrays, or objects.
"""
def build_kimi_compile_context(
    raw_session: dict[str, Any],
    normalized_session: dict[str, Any],
    cleaned: dict[str, Any],
    partial: dict[str, Any]
) -> dict[str, Any] {
    return {
        "goal": str(normalized_session.get("goalContext", "")),
        "user_explanation": str(normalized_session.get("userExplanation", "")),
        "start_url": str(normalized_session.get("startUrl", "")),
        "status": str(normalized_session.get("status", "")),
        "semantic_summary": latest_semantic_summary(raw_session),
        "event_summary": compact_event_summary(cleaned, 12),
        "heuristic_workflow": {
            "name": str(partial.get("name", "")),
            "context": partial.get("context", {}),
            "inputs": partial.get("inputs", []),
            "steps": partial.get("steps", [])
        }
    };
}

def build_kimi_compile_request(
    raw_session: dict[str, Any],
    normalized_session: dict[str, Any],
    cleaned: dict[str, Any],
    partial: dict[str, Any],
    config: dict[str, Any]
) -> dict[str, Any] {
    system_prompt: str = build_kimi_compile_instructions();
    request_context: dict[str, Any] = build_kimi_compile_context(
        raw_session,
        normalized_session,
        cleaned,
        partial
    );

    payload: dict[str, Any] = {
        "model": str(config.get("model", DEFAULT_KIMI_MODEL)),
        "messages": [
            {
                "role": "system",
                "content": "You are a careful workflow compiler assistant."
            },
            {
                "role": "system",
                "content": system_prompt
            },
            {
                "role": "user",
                "content": json.dumps(request_context)
            }
        ],
        "response_format": {"type": "json_object"},
        "max_tokens": 1800
    };

    if str(config.get("thinking_mode", "disabled")) == "disabled" {
        payload["thinking"] = {"type": "disabled"};
    }

    return payload;
}

"""R: Build the native Ollama chat payload for truly local compile enrichment.
M: Reuses the shared prompt contract and asks Ollama for one non-streamed JSON reply.
E: Uses deterministic options so small local models stay predictable.
"""
def build_ollama_chat_request(
    raw_session: dict[str, Any],
    normalized_session: dict[str, Any],
    cleaned: dict[str, Any],
    partial: dict[str, Any],
    config: dict[str, Any]
) -> dict[str, Any] {
    system_prompt: str = build_kimi_compile_instructions();
    request_context: dict[str, Any] = build_kimi_compile_context(
        raw_session,
        normalized_session,
        cleaned,
        partial
    );

    return {
        "model": str(config.get("model", DEFAULT_OLLAMA_MODEL)),
        "messages": [
            {
                "role": "system",
                "content": "You are a careful workflow compiler assistant."
            },
            {
                "role": "system",
                "content": system_prompt
            },
            {
                "role": "user",
                "content": json.dumps(request_context)
            }
        ],
        "stream": False,
        "format": "json",
        "options": {
            "temperature": 0
        }
    };
}

"""R: Build the single text prompt sent through the local `kimi` CLI fallback.
M: Reuses the same instructions and JSON context as the API path, but in one plain-text prompt.
E: Prompt stays deterministic and self-contained so the CLI does not need workspace access.
"""
def build_kimi_cli_prompt(
    raw_session: dict[str, Any],
    normalized_session: dict[str, Any],
    cleaned: dict[str, Any],
    partial: dict[str, Any]
) -> str {
    request_context: dict[str, Any] = build_kimi_compile_context(
        raw_session,
        normalized_session,
        cleaned,
        partial
    );
    return (
        "You are a careful workflow compiler assistant.\n\n" +
        build_kimi_compile_instructions() +
        "\n\nInput JSON:\n" +
        json.dumps(request_context)
    );
}

"""R: POST one JSON payload to the Kimi chat completions endpoint.
M: Uses Python stdlib HTTP utilities so the integration stays Jac-native.
E: Raises descriptive exceptions for HTTP/network/parse failures.
"""
def post_kimi_json(config: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any] {
    endpoint: str = str(config.get("base_url", DEFAULT_KIMI_BASE_URL)).rstrip("/") + "/chat/completions";
    api_key: str = str(config.get("api_key", ""));
    request_body: bytes = json.dumps(payload).encode("utf-8");
    headers: dict[str, str] = {"Content-Type": "application/json"};
    if api_key {
        headers["Authorization"] = "Bearer " + api_key;
    }

    request: Any = Request(
        endpoint,
        data=request_body,
        headers=headers,
        method="POST"
    );

    try {
        response: Any = urlopen(request, timeout=30);
        raw_bytes: Any = response.read();
        response.close();
        raw_body: str = str(raw_bytes.decode("utf-8"));
        return json.loads(raw_body);
    } except HTTPError as err {
        details: str = "";
        try {
            details = err.read().decode("utf-8");
        } except Exception {
            details = "";
        }
        raise Exception("Kimi HTTP " + str(err.code) + (": " + details if details else ""));
    } except URLError as err {
        raise Exception("Kimi network error: " + str(err.reason or err));
    }
}

"""R: POST one native chat payload to a local Ollama daemon.
M: Uses the non-streaming `/api/chat` endpoint and decodes the returned JSON object.
E: Raises descriptive exceptions for offline daemons, model issues, and malformed responses.
"""
def post_ollama_chat(config: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any] {
    endpoint: str = ollama_root_base_url(str(config.get("base_url", DEFAULT_OLLAMA_BASE_URL))) + "/api/chat";
    request_body: bytes = json.dumps(payload).encode("utf-8");

    request: Any = Request(
        endpoint,
        data=request_body,
        headers={"Content-Type": "application/json"},
        method="POST"
    );

    try {
        response: Any = urlopen(request, timeout=90);
        raw_bytes: Any = response.read();
        response.close();
        raw_body: str = str(raw_bytes.decode("utf-8"));
        parsed: Any = json.loads(raw_body);
        if isinstance(parsed, dict) {
            return parsed;
        }
    } except HTTPError as err {
        details: str = "";
        try {
            details = err.read().decode("utf-8");
        } except Exception {
            details = "";
        }
        raise Exception("Local Ollama HTTP " + str(err.code) + (": " + details if details else ""));
    } except URLError as err {
        raise Exception("Local Ollama network error: " + str(err.reason or err));
    }

    raise Exception("Local Ollama returned an invalid response");
}

"""R: Parse one JSON object even when the model wraps it in fences or extra prose.
M: Tries the raw text first, then a fenced-body variant, then the first outer JSON object slice.
E: Raises when no candidate parses into a JSON object.
"""
def parse_json_object_text(raw_text: str, source_label: str = "Kimi") -> dict[str, Any] {
    trimmed: str = str(raw_text or "").strip();
    if not trimmed {
        raise Exception(source_label + " response content is empty");
    }

    candidates: list[str] = [trimmed];
    if trimmed.startswith("```") and trimmed.endswith("```") {
        lines: list[str] = trimmed.splitlines();
        if len(lines) >= 3 {
            fenced_body: str = "\n".join(lines[1:-1]).strip();
            if fenced_body and fenced_body not in candidates {
                candidates.append(fenced_body);
            }
        }
    }

    first_brace: int = trimmed.find("{");
    last_brace: int = trimmed.rfind("}");
    if first_brace >= 0 and last_brace > first_brace {
        json_slice: str = str(trimmed[first_brace:last_brace + 1]).strip();
        if json_slice and json_slice not in candidates {
            candidates.append(json_slice);
        }
    }

    for candidate in candidates {
        try {
            parsed: Any = json.loads(candidate);
            if isinstance(parsed, dict) {
                return parsed;
            }
        } except json.JSONDecodeError {
            continue;
        }
    }

    raise Exception(source_label + " JSON response was malformed");
}

"""R: Extract the JSON-mode object returned by Kimi chat completions.
M: Reads `choices[0].message.content`, parses it as JSON, and returns the dict.
E: Raises when the response is incomplete, malformed, or missing a usable choice.
"""
def parse_kimi_json_mode_response(response: dict[str, Any]) -> dict[str, Any] {
    choices: Any = response.get("choices", []);
    if not isinstance(choices, list) or not choices {
        raise Exception("Kimi response missing choices");
    }

    first_choice: Any = choices[0];
    if not isinstance(first_choice, dict) {
        raise Exception("Kimi response choice is invalid");
    }

    message: Any = first_choice.get("message", {});
    if not isinstance(message, dict) {
        raise Exception("Kimi response message is invalid");
    }

    content: Any = message.get("content", "");
    if not isinstance(content, str) or not content.strip() {
        raise Exception("Kimi response content is empty");
    }

    parsed: dict[str, Any] = parse_json_object_text(content, "Kimi");

    finish_reason: str = str(first_choice.get("finish_reason", ""));
    if finish_reason == "length" {
        parsed["_warning"] = "Kimi response was truncated";
    }

    return parsed;
}

"""R: Extract one JSON object from a non-streamed local Ollama chat response.
M: Reads `message.content`, then reuses the tolerant JSON-text parser shared by other transports.
E: Raises when Ollama returns an unexpected response shape or empty content.
"""
def parse_ollama_chat_response(response: dict[str, Any]) -> dict[str, Any] {
    message: Any = response.get("message", {});
    if not isinstance(message, dict) {
        raise Exception("Local Ollama response message is invalid");
    }

    content: Any = message.get("content", "");
    if not isinstance(content, str) or not content.strip() {
        raise Exception("Local Ollama response content is empty");
    }

    return parse_json_object_text(content, "Local Ollama");
}

"""R: Run compile enrichment through the local `kimi` CLI and parse its JSON reply.
M: Executes print mode with a no-tools agent and converts the final message into a dict.
E: Login issues, timeouts, and malformed output raise descriptive exceptions.
"""
def run_kimi_cli_json(config: dict[str, Any], prompt: str) -> dict[str, Any] {
    try {
        result: Any = subprocess.run(
            build_kimi_cli_command(prompt, config),
            capture_output=True,
            text=True,
            timeout=90
        );
    } except subprocess.TimeoutExpired {
        raise Exception("Kimi CLI request timed out");
    } except OSError as err {
        raise Exception("Kimi CLI could not be started: " + str(err));
    }

    stdout: str = str(result.stdout or "").strip();
    stderr: str = str(result.stderr or "").strip();
    combined: str = "\n".join([stdout, stderr]).strip();
    first_line: str = first_non_empty_line(combined);
    lowered: str = first_line.lower();

    if result.returncode != 0 {
        if "llm not set" in lowered or "login" in lowered {
            raise Exception("Kimi CLI is installed but not logged in. Run `kimi login` once to authorize it.");
        }
        raise Exception("Kimi CLI failed" + (": " + first_line if first_line else ""));
    }

    response_text: str = stdout if stdout else combined;
    return parse_json_object_text(response_text, "Kimi CLI");
}

"""R: Run compile-time workflow enrichment through the selected provider.
M: Chooses the truly local Ollama path, Moonshot API path, or legacy Kimi CLI path.
E: Raises on config or transport failures so the compiler can fall back to heuristics with warnings.
"""
def kimi_compile_enrichment(
    raw_session: dict[str, Any],
    normalized_session: dict[str, Any],
    cleaned: dict[str, Any],
    partial: dict[str, Any],
    options: dict[str, Any]
) -> dict[str, Any] {
    config: dict[str, Any] = resolve_kimi_compile_config();
    if not bool(config.get("enabled", False)) {
        raise Exception(str(config.get("reason", "Kimi compile enrichment is not enabled")));
    }

    parsed: dict[str, Any] = {};
    provider: str = str(config.get("provider", "kimi") or "kimi");
    transport: str = str(config.get("transport", "") or "");

    if provider == "ollama" and transport == "local" {
        response: dict[str, Any] = post_ollama_chat(
            config,
            build_ollama_chat_request(
                raw_session,
                normalized_session,
                cleaned,
                partial,
                config
            )
        );
        parsed = parse_ollama_chat_response(response);
    } elif transport == "cli" {
        parsed = run_kimi_cli_json(
            config,
            build_kimi_cli_prompt(
                raw_session,
                normalized_session,
                cleaned,
                partial
            )
        );
    } else {
        request_payload: dict[str, Any] = build_kimi_compile_request(
            raw_session,
            normalized_session,
            cleaned,
            partial,
            config
        );

        response: dict[str, Any] = post_kimi_json(config, request_payload);
        parsed = parse_kimi_json_mode_response(response);
    }

    parsed["model"] = {
        "provider": provider,
        "model": str(config.get("model", DEFAULT_OLLAMA_MODEL if provider == "ollama" else DEFAULT_KIMI_MODEL)),
        "thinking_mode": str(config.get("thinking_mode", "disabled")),
        "transport": transport if transport else ("local" if provider == "ollama" else "api")
    };
    return parsed;
}

"""
Jac-native Kimi runtime lifecycle CLI.

Purpose:
- Provide `start`, `stop`, and `status` commands for the browser process.
- Delegate all reusable logic to `runtime_state.jac` so imports stay side-effect free.
"""

import sys;
import json;
import from typing { Any }
import from jac.llm.runtime_state {
    current_runtime_state,
    start_runtime,
    stop_runtime
}

"""R: Parse CLI JSON payload passed after the command token.
M: Joins argv entries from index 2 and attempts one JSON object decode.
E: Invalid JSON returns an empty dict.
"""
def parse_payload() -> dict[str, Any] {
    raw_payload: str = "{}";
    if len(sys.argv) > 2 {
        raw_payload = " ".join(sys.argv[2:]);
    }

    try {
        parsed = json.loads(raw_payload);
        if isinstance(parsed, dict) {
            return parsed;
        }
    } except json.JSONDecodeError {
        return {};
    }
    return {};
}

"""R: Route one runtime lifecycle command to its implementation.
M: Supports `start`, `stop`, and `status`.
E: Unknown commands return a usage payload instead of raising.
"""
def dispatch(command: str, payload: dict[str, Any]) -> dict[str, Any] {
    if command == "start" {
        return start_runtime(payload);
    }
    if command == "stop" {
        return stop_runtime(payload);
    }
    if command == "status" {
        return {"ok": True, "runtime": current_runtime_state()};
    }

    return {
        "ok": False,
        "error": "unknown command",
        "valid_commands": ["start", "stop", "status"]
    };
}

"""R: Decide whether this module should execute its CLI entrypoint.
M: Treats non-empty, non-path-like argv values as commands and ignores import-time script paths.
E: Unknown direct commands still dispatch so the caller gets the usual usage payload.
"""
def should_dispatch_cli(command: str) -> bool {
    if not command {
        return False;
    }

    return ("/" not in command) and ("\\" not in command) and not command.endswith(".jac");
}

with entry {
    command: str = "";
    if len(sys.argv) > 1 {
        command = str(sys.argv[1]);
    }
    if should_dispatch_cli(command) {
        payload: dict[str, Any] = parse_payload();
        result: dict[str, Any] = dispatch(command, payload);
        print(json.dumps(result));
    }
}

"""
Jac-native LLM runtime state helpers.

Purpose:
- Keep browser-owned compile-enrichment runtime state in one small JSON file.
- Expose pure functions that other Jac modules can import safely.
- Avoid CLI side effects when compilation imports runtime status.
"""

import os;
import json;
import time;
import from typing { Any }
import from jac.llm.kimi_client { resolve_kimi_compile_config }

glob DATA_ROOT: str = "./jac/layer_data";
glob LLM_DIR: str = DATA_ROOT + "/llm";
glob LLM_RUNTIME_FILE: str = LLM_DIR + "/runtime.json";

"""R: Return a simple string timestamp for runtime state transitions.
M: Uses `time.time()` for compatibility with the rest of the Jac layer files.
E: Precision is sufficient for startup/shutdown tracing.
"""
def timestamp_now() -> str {
    return str(time.time());
}

"""R: Ensure the LLM runtime storage directory exists.
M: Creates `jac/layer_data/llm` recursively.
E: Safe to call multiple times.
"""
def ensure_llm_dir() {
    os.makedirs(LLM_DIR, exist_ok=True);
}

"""R: Build the default inactive runtime state payload.
M: Returns a consistent shape even before the browser has started once.
E: `reason` is caller-controlled so status messages remain explicit.
"""
def default_runtime_state(reason: str = "LLM runtime inactive") -> dict[str, Any] {
    return {
        "active": False,
        "provider": "",
        "transport": "",
        "model": "",
        "thinking_mode": "",
        "started_at": "",
        "stopped_at": "",
        "updated_at": timestamp_now(),
        "reason": reason,
        "source": ""
    };
}

"""R: Read the persisted browser-owned LLM runtime state from disk.
M: Loads JSON when present and falls back to a normalized inactive shape otherwise.
E: Invalid files degrade to inactive state rather than failing callers.
"""
def read_runtime_state() -> dict[str, Any] {
    if not os.path.exists(LLM_RUNTIME_FILE) {
        return default_runtime_state("LLM runtime has not started yet");
    }

    try {
        with open(LLM_RUNTIME_FILE, "r") as file {
            parsed = json.load(file);
            if isinstance(parsed, dict) {
                return {
                    "active": bool(parsed.get("active", False)),
                    "provider": str(parsed.get("provider", "")),
                    "transport": str(parsed.get("transport", "")),
                    "model": str(parsed.get("model", "")),
                    "thinking_mode": str(parsed.get("thinking_mode", "")),
                    "started_at": str(parsed.get("started_at", "")),
                    "stopped_at": str(parsed.get("stopped_at", "")),
                    "updated_at": str(parsed.get("updated_at", timestamp_now())),
                    "reason": str(parsed.get("reason", "")),
                    "source": str(parsed.get("source", ""))
                };
            }
        }
    } except json.JSONDecodeError {
        return default_runtime_state("LLM runtime state was unreadable");
    } except OSError {
        return default_runtime_state("LLM runtime state could not be read");
    }

    return default_runtime_state("LLM runtime state was invalid");
}

"""R: Persist one normalized runtime state record.
M: Writes formatted JSON to the browser-owned runtime state path.
E: Filesystem errors are surfaced to the caller.
"""
def write_runtime_state(state: dict[str, Any]) {
    ensure_llm_dir();
    with open(LLM_RUNTIME_FILE, "w") as file {
        json.dump(state, file, indent=2);
    }
}

"""R: Return the current browser-owned runtime status for compile enrichment.
M: Reads the persisted state file and normalizes its fields.
E: Missing state yields an inactive status payload.
"""
def current_runtime_state() -> dict[str, Any] {
    return read_runtime_state();
}

"""R: Activate compile enrichment for the current browser lifecycle.
M: Resolves config, writes an active state when the selected provider is valid, and returns status.
E: Missing credentials, offline local servers, or missing models produce an inactive reason.
"""
def start_runtime(payload: dict[str, Any]) -> dict[str, Any] {
    source: str = str(payload.get("source", "browser_startup"));
    config: dict[str, Any] = resolve_kimi_compile_config();

    state: dict[str, Any] = default_runtime_state("LLM runtime inactive");
    state["provider"] = str(config.get("provider", ""));
    state["transport"] = str(config.get("transport", ""));
    state["model"] = str(config.get("model", ""));
    state["thinking_mode"] = str(config.get("thinking_mode", ""));
    state["source"] = source;
    state["updated_at"] = timestamp_now();

    if bool(config.get("enabled", False)) {
        state["active"] = True;
        state["started_at"] = timestamp_now();
        state["stopped_at"] = "";
        state["reason"] = str(config.get("reason", "LLM runtime ready for compile-time enrichment"));
    } else {
        state["active"] = False;
        state["reason"] = str(config.get("reason", "LLM config missing, offline, or compile use disabled"));
    }

    write_runtime_state(state);
    return {"ok": True, "runtime": state};
}

"""R: Deactivate the browser-owned compile-enrichment runtime.
M: Preserves provider/model info while marking the runtime inactive and timestamping shutdown.
E: Safe to call even if the runtime was never activated.
"""
def stop_runtime(payload: dict[str, Any]) -> dict[str, Any] {
    source: str = str(payload.get("source", "browser_close"));
    state: dict[str, Any] = current_runtime_state();
    state["active"] = False;
    state["updated_at"] = timestamp_now();
    state["stopped_at"] = timestamp_now();
    state["source"] = source;
    state["reason"] = "LLM runtime stopped on browser shutdown";

    write_runtime_state(state);
    return {"ok": True, "runtime": state};
}

"""
Recording layer — state machine, data model, validation, and persistence tests.

Original tests cover 11 requirements (state machine + data model).
New tests cover 20 requirements (continuation/stop_policy validation + persistence):
