}

node Ticket {
    has ticket_id: str = "";
    has category: str = "";
    has description: str = "";
    has urgency: str = "medium";
    has status: str = "open";
    has ai_summary: str = "";
    has ai_diagnosis: str = "";
    has recommended_action: str = "";
    has tenant_reply: str = "";
    has owner_alert: str = "";
    has created_at: str = "";
    has resolved_at: str = "";
    has vendor_name: str = "";
    has estimated_cost: float = 0.0;
}

node Vendor {
    has name: str = "";
    has category: str = "";
    has phone: str = "";
    has email: str = "";
    has rating: float = 0.0;
    has avg_cost: float = 0.0;
