        "Goals:\n"
        "- answer clearly\n"
        "- keep messages short unless asked for detail\n"
        "- stay grounded in the provided workspace files\n"
    );
}


def slugify(value: str) -> str {
    base = value.strip().lower();
    chars: list[str] = [];
    last_dash = False;

    for char in base {
        if char.isalnum() {
            chars.append(char);
            last_dash = False;
        } elif not last_dash {
            chars.append("-");
            last_dash = True;
        }
    }

    slug = "".join(chars).strip("-");
    return slug if slug else "claw";
}


