"""Agency engine data models for Trace."""

enum AutonomyLevel {
    OBSERVE,
    SUGGEST,
    DRAFT,
    ACT_APPROVED,
    AUTOMATE
}

node AgencyPolicy {
    has domain: str = "";
    has autonomy_level: AutonomyLevel = AutonomyLevel.OBSERVE;
    has constraints: list[str] = [];
    has total_actions: int = 0;
}

node PendingAction {
    has action_type: str = "";
    has description: str = "";
    has confidence: float = 0.0;
    has domain: str = "";
    has created_at: str = "";
    has approved: bool = False;
    has executed: bool = False;
}

"""Behavior and timing engine data models for Trace."""

enum EnergyLevel {
    PEAK,
    HIGH,
    MODERATE,
    LOW,
    DEPLETED
}

node BehaviorProfile {
    has productivity_hours: list[float] = [];
    has procrastination_triggers: list[str] = [];
    has response_time_avg: float = 0.0;
    has current_energy: EnergyLevel = EnergyLevel.MODERATE;
    has wake_time: str = "07:00";
    has sleep_time: str = "23:00";
}

node InterventionRecord {
    has intervention_type: str = "";
    has scheduled_time: str = "";
