"""Memory engine data models for Trace."""

enum MemoryType {
    EVENT,
    PERSON,
    EMOTION,
    VALUE,
    THEME,
    DECISION,
    HABIT,
    PERIOD,
    PREFERENCE
}

enum RelationType {
    TEMPORAL,
    CAUSAL,
    EMOTIONAL,
