def run_status_from_text(status_text: str) -> RunStatus {
    lower = status_text.lower();
    if lower in {"resolved", "passed", "success", "succeeded"} {
        return RunStatus.RESOLVED;
    }
    if lower in {"submitted"} {
        return RunStatus.SUBMITTED;
    }
    if lower in {"interrupted"} {
        return RunStatus.INTERRUPTED;
    }
    if "limit" in lower {
        return RunStatus.LIMITS_EXCEEDED;
    }
    if lower in {"failed", "error", "error_exit"} {
        return RunStatus.ERROR_EXIT;
    }
    if "error" in lower or "exception" in lower or "retry" in lower or "traceback" in lower or "process" in lower {
        return RunStatus.ERROR_EXIT;
    }
    return RunStatus.UNKNOWN;
}

def _int_metadata_value(metadata: dict[str, any], key: str, fallback: int = 0) -> int {
    value = metadata.get(key);
    if value is None {
        return fallback;
    }
    if isinstance(value, int) {
        return value;
    }
    try {
        return int(float(str(value)));
    } except Exception {
        return fallback;
    }
}

def _float_metadata_value(metadata: dict[str, any], key: str, fallback: float = 0.0) -> float {
    value = metadata.get(key);
    if value is None {
        return fallback;
    }
    if isinstance(value, float) {
        return value;
    }
    if isinstance(value, int) {
        return float(value);
    }
    try {
        return float(str(value));
    } except Exception {
        return fallback;
    }
}

def run_status_name(value: RunStatus) -> str {
    match value {
        case RunStatus.RESOLVED: return "resolved";
        case RunStatus.SUBMITTED: return "submitted";
        case RunStatus.INTERRUPTED: return "interrupted";
        case RunStatus.LIMITS_EXCEEDED: return "limits_exceeded";
        case RunStatus.ERROR_EXIT: return "error_exit";
        case _: return "unknown";
    }
}

def error_type_from_text(text: str) -> str {
    lower = text.lower();
    if "syntaxerror" in lower or "invalid syntax" in lower {
        return "SyntaxError";
    }
    if "importerror" in lower or "module not found" in lower {
        return "ImportError";
    }
    if "traceback" in lower {
        return "Traceback";
    }
    if "failed" in lower {
        return "TestFailure";
    }
    return "ErrorSignal";
}

def test_status_from_text(text: str) -> str {
    lower = text.lower();
    if " passed" in lower or lower.startswith("passed") or "1 passed" in lower {
        return "passed";
    }
    if "failed" in lower or "error" in lower or "traceback" in lower {
        return "failed";
    }
    return "unknown";
}

def patch_stats(text: str) -> dict[str, any] {
    adds = 0;
    dels = 0;
    for line in text.split("\n") {
        if line.startswith("+++") or line.startswith("---") {
            continue;
        }
        if line.startswith("+") {
            adds += 1;
        } elif line.startswith("-") {
            dels += 1;
        }
    }
    return {"adds": adds, "dels": dels};
}

def list_batch_runs(batch: Batch) -> list[Run] {
    return sorted(
        [batch ->:HasRun:->][?:Run],
        key=lambda item: any -> any : item.run_id,
    );
}

def list_run_steps(run_node: Run) -> list[Step] {
    return sorted(
        [run_node ->:HasStep:->][?:Step],
        key=lambda item: any -> any : item.idx,
    );
}

def list_step_files(step_node: Step) -> list[FileArtifact] {
    return sorted(
        [step_node ->:TouchesFile:->][?:FileArtifact],
        key=lambda item: any -> any : item.path,
    );
}

def list_step_patches(step_node: Step) -> list[Patch] {
    return [step_node ->:ProducesPatch:->][?:Patch];
}

def list_step_tests(step_node: Step) -> list[TestEvent] {
    return [step_node ->:RunsTest:->][?:TestEvent];
}

def list_step_errors(step_node: Step) -> list[ErrorEvent] {
    return [step_node ->:RaisesError:->][?:ErrorEvent];
}

def list_run_hypotheses(run_node: Run) -> list[FailureHypothesis] {
    return [run_node ->:SupportsHypothesis:->][?:FailureHypothesis];
}

def list_run_clusters(run_node: Run) -> list[Cluster] {
    return [run_node ->:InCluster:->][?:Cluster];
}

def list_batch_clusters(batch: Batch) -> list[Cluster] {
    clusters: list[Cluster] = [];
    seen: set[str] = set();
    for run_node in list_batch_runs(batch) {
        for cluster_node in list_run_clusters(run_node) {
            if cluster_node.cluster_id in seen {
                continue;
            }
            seen.add(cluster_node.cluster_id);
            clusters.append(cluster_node);
        }
    }
    return sorted(clusters, key=lambda item: any -> any : item.cluster_id);
}

def list_cluster_patches(cluster_node: Cluster) -> list[MemoryPatch] {
    return sorted(
        [cluster_node ->:SuggestsPatch:->][?:MemoryPatch],
        key=lambda item: any -> any : item.patch_id,
    );
}

def run_batch_id_value(run_node: Run, fallback: str = "") -> str {
    metadata_batch_id = str(run_node.metadata.get("batch_id") or "");
    if metadata_batch_id {
        return metadata_batch_id;
    }
    if hasattr(run_node, "batch_id") and str(run_node.batch_id or "") {
        return str(run_node.batch_id);
    }
    return fallback;
}

def find_batch_node(root_node: any, target_batch_id: str) -> any {
    batches = [root_node ->:HasBatch:->][?:Batch, batch_id == target_batch_id];
    if batches {
        return batches[0];
    }
    return None;
}

def find_run_node(root_node: any, target_run_id: str, target_batch_id: str = "") -> any {
    if target_batch_id {
        batch = find_batch_node(root_node, target_batch_id);
        if batch is None {
            return None;
        }
        runs = [batch ->:HasRun:->][?:Run, run_id == target_run_id];
        if runs {
            return runs[0];
        }
        return None;
    }

    matches: list[Run] = [];
    for batch in [root_node ->:HasBatch:->][?:Batch] {
        runs = [batch ->:HasRun:->][?:Run, run_id == target_run_id];
        if runs {
            matches.extend(runs);
        }
    }
    if len(matches) == 1 {
        return matches[0];
    }
    return None;
}

def find_batch_for_run(root_node: any, target_run_id: str, target_batch_id: str = "") -> any {
    if target_batch_id {
        batch = find_batch_node(root_node, target_batch_id);
        if batch is None {
            return None;
        }
        runs = [batch ->:HasRun:->][?:Run, run_id == target_run_id];
        if runs {
            return batch;
        }
        return None;
    }
    matches: list[Batch] = [];
    for batch in [root_node ->:HasBatch:->][?:Batch] {
        runs = [batch ->:HasRun:->][?:Run, run_id == target_run_id];
        if runs {
            matches.append(batch);
        }
    }
    if len(matches) == 1 {
        return matches[0];
    }
    return None;
}

def find_cluster_node(batch: Batch, target_cluster_id: str) -> any {
    for cluster_node in list_batch_clusters(batch) {
        if cluster_node.cluster_id == target_cluster_id {
            return cluster_node;
        }
    }
    return None;
}

def upsert_cluster_patch(cluster_node: Cluster, patch_data: dict[str, any]) -> dict[str, any] {
    stable_patch_id = str(patch_data.get("patch_id") or (cluster_node.cluster_id + ":memory_patch"));
    existing = None;
    for patch_node in list_cluster_patches(cluster_node) {
        if patch_node.patch_id == stable_patch_id {
            existing = patch_node;
            break;
        }
    }

    if existing is None {
        cluster_node +>: SuggestsPatch(weight=float(patch_data.get("confidence") or 0.0)) :+> (
            patch_node := MemoryPatch(
                patch_id=stable_patch_id,
                scope=str(patch_data.get("scope") or "cluster"),
                title=str(patch_data.get("title") or cluster_node.label),
                diff_text=str(patch_data.get("diff_text") or ""),
                confidence=float(patch_data.get("confidence") or 0.0),
            )
        );
        if cluster_node.cluster_id not in GENERATED_PATCH_REGISTRY {
            GENERATED_PATCH_REGISTRY[cluster_node.cluster_id] = [];
        }
        if stable_patch_id not in GENERATED_PATCH_REGISTRY[cluster_node.cluster_id] {
            GENERATED_PATCH_REGISTRY[cluster_node.cluster_id].append(stable_patch_id);
        }
        commit();
        return {
            "patch_id": patch_node.patch_id,
            "created": True,
        };
    }

    existing.scope = str(patch_data.get("scope") or existing.scope);
    existing.title = str(patch_data.get("title") or existing.title);
    existing.diff_text = str(patch_data.get("diff_text") or existing.diff_text);
    existing.confidence = float(patch_data.get("confidence") or existing.confidence);
    if cluster_node.cluster_id not in GENERATED_PATCH_REGISTRY {
        GENERATED_PATCH_REGISTRY[cluster_node.cluster_id] = [];
    }
    if stable_patch_id not in GENERATED_PATCH_REGISTRY[cluster_node.cluster_id] {
        GENERATED_PATCH_REGISTRY[cluster_node.cluster_id].append(stable_patch_id);
    }
    commit();
    return {
        "patch_id": existing.patch_id,
        "created": False,
    };
}

def _file_node(path: str, file_nodes: dict[str, any]) -> any {
    if path in file_nodes {
        return file_nodes[path];
    }
    file_node = FileArtifact(
        path=path,
        basename=Path(path).name,
        ext=Path(path).suffix,
    );
    file_nodes[path] = file_node;
    return file_node;
}

def _attach_failure_hypotheses(run_node: Run, fingerprint: dict[str, any]) -> None {
    scores = fingerprint["failure_class_scores"];
    run_batch_id = run_batch_id_value(run_node);
    for label in scores {
        score = float(scores[label]);
        if score <= 0.0 {
            continue;
        }
        run_node +>: SupportsHypothesis(weight=score) :+> FailureHypothesis(
            hyp_id=f"{run_batch_id}:{run_node.run_id}:{label}",
            label=failure_class_to_enum(str(label)),
            score=score,
            rationale=f"Deterministic score for {label}",
        );
    }
}

def _run_detail_hydrated(run_node: Run) -> bool {
    return bool(run_node.metadata.get("traceforge_detail_hydrated"));
}

def _attach_step_artifacts(step_node: Step, file_nodes: dict[str, any], parsed_step: any, run_id: str, batch_id: str) -> None {
    linked_files: list[any] = [];
    for file_path in parsed_step.touched_files {
        file_node = _file_node(file_path, file_nodes);
        step_node +>: TouchesFile() :+> file_node;
        linked_files.append(file_node);
    }

    if parsed_step.patch_text {
        stats = patch_stats(parsed_step.patch_text);
        patch_file_path = parsed_step.touched_files[0] if parsed_step.touched_files else "";
        patch_node = Patch(
            patch_id=f"{batch_id}:{run_id}:patch:{parsed_step.index}",
            file_path=patch_file_path,
            adds=stats["adds"],
            dels=stats["dels"],
            parse_ok=not ("syntaxerror" in parsed_step.patch_text.lower() or "invalid syntax" in parsed_step.patch_text.lower()),
            patch_hash=hash_text(parsed_step.patch_text),
        );
        step_node +>: ProducesPatch() :+> patch_node;
        if linked_files {
            patch_node +>: PatchesFile() :+> linked_files[0];
        }
    }

    if parsed_step.test_text {
        failing_tests = [];
        for token in extract_file_tokens(parsed_step.test_text) {
            if "::" in token or token.startswith("tests/") {
                failing_tests.append(token);
            }
        }
        step_node +>: RunsTest() :+> TestEvent(
            test_id=f"{batch_id}:{run_id}:test:{parsed_step.index}",
            command=truncate_text(parsed_step.test_text, 240),
            status=test_status_from_text(parsed_step.test_text),
            failing_tests=failing_tests,
            excerpt=truncate_text(parsed_step.test_text, 240),
        );
    }

    if parsed_step.error_text {
        step_node +>: RaisesError() :+> ErrorEvent(
            error_id=f"{batch_id}:{run_id}:error:{parsed_step.index}",
            error_type=error_type_from_text(parsed_step.error_text),
            message=truncate_text(parsed_step.error_text, 240),
            severity=Severity.ERROR,
        );
    }
}

def _attach_run_steps(run_node: Run, parsed_run: ParsedRun, file_nodes: dict[str, any]) -> None {
    seen_hashes: set[str] = set();
    previous_step_node = None;
    run_batch_id = run_batch_id_value(run_node);
    for parsed_step in parsed_run.steps {
        is_repeated = parsed_step.content_hash in seen_hashes;
        seen_hashes.add(parsed_step.content_hash);
        run_node +>: HasStep(order=parsed_step.index) :+> (step_node := Step(
            step_id=f"{run_batch_id}:{parsed_run.run_id}:step:{parsed_step.index}",
            idx=parsed_step.index,
            kind=step_kind_to_enum(parsed_step.kind),
            role=parsed_step.role,
            phase=parsed_step.phase,
            excerpt=parsed_step.excerpt,
            raw_offset=parsed_step.index,
            content_hash=parsed_step.content_hash,
            repeated=is_repeated,
        ));
        if previous_step_node is not None {
            previous_step_node +>: NextStep() :+> step_node;
        }
        previous_step_node = step_node;
        _attach_step_artifacts(step_node, file_nodes, parsed_step, parsed_run.run_id, run_batch_id);
    }
}

def hydrate_run_graph(run_node: Run) -> bool {
    if _run_detail_hydrated(run_node) {
        return False;
    }
    existing_steps = list_run_steps(run_node);
    if existing_steps {
        metadata = dict(run_node.metadata);
        metadata["traceforge_detail_hydrated"] = True;
        run_node.metadata = metadata;
        commit();
        return False;
    }
    parsed_run = parse_run(run_node.raw_path, run_node.run_id);
    _attach_run_steps(run_node, parsed_run, {});
    metadata = dict(run_node.metadata);
    metadata["traceforge_detail_hydrated"] = True;
    run_node.metadata = metadata;
    commit();
    return True;
}

def _create_run_node(batch: Batch, parsed_run: ParsedRun, order: int) -> dict[str, any] {
    fingerprint = fingerprint_to_dict(compute_run_fingerprint(parsed_run));
    primary_failure = dominant_failure_label(fingerprint);
    critical = localize_critical_step(parsed_run, fingerprint);
    summary = build_run_digest(parsed_run, fingerprint);
    metadata = dict(parsed_run.metadata);
    metadata["traceforge_detail_hydrated"] = False;
    metadata["batch_id"] = batch.batch_id;

    batch +>: HasRun(order=order) :+> (run_node := Run(
        run_id=parsed_run.run_id,
        batch_id=batch.batch_id,
        instance_id=parsed_run.instance_id,
        task_title=parsed_run.task_title,
        raw_path=parsed_run.source_path,
        metadata=metadata,
        exit_status=run_status_from_text(str(parsed_run.metadata.get("exit_status") or parsed_run.metadata.get("status") or "")),
        api_calls=_int_metadata_value(parsed_run.metadata, "api_calls", 0),
        cost=_float_metadata_value(parsed_run.metadata, "instance_cost", 0.0),
        step_count=len(parsed_run.steps),
        unique_files=int(fingerprint["num_unique_files"]),
        fingerprint=fingerprint,
        primary_failure=failure_class_to_enum(primary_failure),
        critical_step_idx=int(critical["critical_step_idx"]),
        summary=summary,
    ));

    _attach_failure_hypotheses(run_node, fingerprint);
    return {
        "run_node": run_node,
        "run_id": parsed_run.run_id,
        "task_title": parsed_run.task_title,
        "fingerprint": fingerprint,
        "primary_failure": primary_failure,
        "summary": summary,
        "critical": critical,
    };
}

def _batch_graph_is_current(batch: Batch) -> bool {
    for run_node in list_batch_runs(batch) {
        if run_batch_id_value(run_node) != batch.batch_id {
            return False;
        }
    }
    return True;
}

def _attach_clusters(batch: Batch, run_records: list[dict[str, any]], batch_id: str) -> None {
    clusters = build_clusters(run_records, batch_id);
    run_node_map: dict[str, any] = {};
    record_map: dict[str, dict[str, any]] = {};
    assigned_run_ids: set[str] = set();
    for record in run_records {
        run_node_map[record["run_id"]] = record["run_node"];
        record_map[record["run_id"]] = record;
    }

    for cluster in clusters {
        cluster_node = Cluster(
            cluster_id=cluster["cluster_id"],
            label=cluster["label"],
            failure_class=failure_class_to_enum(str(cluster["failure_class"])),
            size=int(cluster["size"]),
            medoid_run_id=str(cluster["medoid_run_id"]),
            summary=str(cluster["summary"]),
        );
        run_ids = cluster["run_ids"];
        for run_id in run_ids {
            run_node = run_node_map[run_id];
            run_node.cluster_id = cluster["cluster_id"];
            run_node +>: InCluster() :+> cluster_node;
            assigned_run_ids.add(run_id);
        }

        for pair in cluster["similar_pairs"] {
            left_id = str(pair["left_run_id"]);
            right_id = str(pair["right_run_id"]);
            score = float(pair["score"]);
            if score <= 0.0 {
                continue;
            }
            run_node_map[left_id] +>: SimilarRun(score=score) :+> run_node_map[right_id];
            run_node_map[right_id] +>: SimilarRun(score=score) :+> run_node_map[left_id];
        }
    }

    unassigned_by_family: dict[str, list[dict[str, any]]] = {};
    for record in run_records {
        run_id = str(record["run_id"]);
        if run_id in assigned_run_ids {
            continue;
        }
        family = str(record["primary_failure"] or "UNKNOWN");
        if family not in unassigned_by_family {
            unassigned_by_family[family] = [];
        }
        unassigned_by_family[family].append(record);
    }

    for family in unassigned_by_family {
        family_records = unassigned_by_family[family];
        fallback_cluster_id = f"{batch_id}:{family.lower()}:fallback";
        fallback_cluster = Cluster(
            cluster_id=fallback_cluster_id,
            label=failure_class_label(family) + " fallback",
            failure_class=failure_class_to_enum(family),
            size=len(family_records),
            medoid_run_id=str(family_records[0]["run_id"]),
            summary=f"{failure_class_label(family)} fallback cluster with {len(family_records)} run(s).",
        );
        for record in family_records {
            run_node = record["run_node"];
            run_node.cluster_id = fallback_cluster_id;
            run_node +>: InCluster() :+> fallback_cluster;
        }
    }
}

def invalidate_batch_graph(root_node: any, target_batch_id: str) -> dict[str, any] {
    existing = find_batch_node(root_node, target_batch_id);
    if existing is None {
        return {
            "batch_id": target_batch_id,
            "deleted": False,
            "status": "missing",
        };
    }

    cluster_nodes = list_batch_clusters(existing);
    run_nodes = list_batch_runs(existing);
    for cluster_node in cluster_nodes {
        if cluster_node.cluster_id in GENERATED_PATCH_REGISTRY {
            GENERATED_PATCH_REGISTRY[cluster_node.cluster_id] = [];
        }
        for patch_node in list_cluster_patches(cluster_node) {
            del patch_node;
        }
    }
    for run_node in run_nodes {
        for hypothesis in list_run_hypotheses(run_node) {
            del hypothesis;
        }
        for step_node in list_run_steps(run_node) {
            for patch_node in list_step_patches(step_node) {
                del patch_node;
            }
            for test_node in list_step_tests(step_node) {
                del test_node;
            }
            for error_node in list_step_errors(step_node) {
                del error_node;
            }
            del step_node;
        }
        del run_node;
    }
    for cluster_node in cluster_nodes {
        del cluster_node;
    }
    root_node del--> existing;
    del existing;
    commit();
    return {
        "batch_id": target_batch_id,
        "deleted": True,
        "status": "invalidated",
    };
}

def ensure_batch_graph(root_node: any, target_batch_id: str, force_rebuild: bool = False) -> dict[str, any] {
    existing = find_batch_node(root_node, target_batch_id);
    if existing is not None and not force_rebuild {
        if not _batch_graph_is_current(existing) {
            invalidate_batch_graph(root_node, target_batch_id);
        } else {
            return {
                "batch": existing,
                "created": False,
                "status": "existing_graph",
            };
        }
    }
    existing = find_batch_node(root_node, target_batch_id);
    if existing is not None and force_rebuild {
        invalidate_batch_graph(root_node, target_batch_id);
    }
    existing = find_batch_node(root_node, target_batch_id);
    if existing is not None {
        return {
            "batch": existing,
            "created": False,
            "status": "existing_graph",
        };
    }

    batch_meta = batch_summary(target_batch_id);
    if batch_meta["status"] != "ready" {
        return {
            "batch": None,
            "created": False,
            "status": "missing",
        };
    }

    root_node +>: HasBatch() :+> (batch := Batch(
        batch_id=target_batch_id,
        name=str(batch_meta["name"]),
        source_format=str(batch_meta["source_format"]),
        created_at=current_timestamp(),
        run_count=int(batch_meta["run_count"]),
    ));

    run_records: list[dict[str, any]] = [];
    for (order, path) in enumerate(batch_files(target_batch_id)) {
        parsed_run = parse_run(path);
        run_records.append(_create_run_node(batch, parsed_run, order));
    }
    _attach_clusters(batch, run_records, target_batch_id);
    commit();
    return {
        "batch": batch,
        "created": True,
        "status": "recompiled" if force_rebuild else "compiled",
    };
}

def run_graph_stats(run_node: Run) -> dict[str, any] {
    steps = list_run_steps(run_node);
    file_count = 0;
    patch_count = 0;
    test_count = 0;
    error_count = 0;
    artifact_edges = 0;
    for step_node in steps {
        step_files = list_step_files(step_node);
        step_patches = list_step_patches(step_node);
        step_tests = list_step_tests(step_node);
        step_errors = list_step_errors(step_node);
        file_count += len(step_files);
        patch_count += len(step_patches);
        test_count += len(step_tests);
        error_count += len(step_errors);
        artifact_edges += len(step_files) + len(step_patches) + len(step_tests) + len(step_errors);
    }
    return {
        "status": "graph_compiled",
        "node_counts": {
            "Run": 1,
            "Step": len(steps),
            "FileArtifact": file_count,
            "Patch": patch_count,
            "TestEvent": test_count,
            "ErrorEvent": error_count,
            "FailureHypothesis": len(list_run_hypotheses(run_node)),
        },
        "edge_counts": {
            "HasStep": len(steps),
            "NextStep": max(len(steps) - 1, 0),
            "ArtifactLinks": artifact_edges,
            "SupportsHypothesis": len(list_run_hypotheses(run_node)),
        },
    };
}

import from pathlib { Path }
import from zipfile { ZipFile }
import from traceforge.parser { parse_run, path_run_stem }

glob SAMPLE_ROOT: str = "demo_runs";
glob UPLOAD_ROOT: str = "uploads";

def _normalize_batch_name(name: str) -> str {
    if name.endswith("_batch") {
        return name.removesuffix("_batch");
    }
    return name;
}

def _batch_name_from_id(batch_id: str) -> str {
    if batch_id.startswith("sample-") {
        return batch_id.removeprefix("sample-");
    }
    if batch_id.startswith("upload-") {
        return batch_id.removeprefix("upload-");
    }
    return batch_id;
}

def _batch_kind(batch_id: str) -> str {
    if batch_id.startswith("sample-") {
        return "sample";
    }
    if batch_id.startswith("upload-") {
        return "upload";
    }
    return "unknown";
}

def _traj_files_in_dir(batch_dir: Path) -> list[str] {
    if not batch_dir.exists() or not batch_dir.is_dir() {
        return [];
    }
    return [str(path) for path in sorted(batch_dir.rglob("*.traj.json")) if path.is_file()];
}

def sample_batch_path(name: str = "starter") -> str {
    return f"{SAMPLE_ROOT}/{name}_batch";
}

def _upload_batch_path(name: str) -> str {
    direct = Path(UPLOAD_ROOT) / name;
    if direct.exists() and direct.is_dir() {
        return str(direct);
    }
    suffixed = Path(UPLOAD_ROOT) / (name + "_batch");
    if suffixed.exists() and suffixed.is_dir() {
        return str(suffixed);
    }
    return str(direct);
}

def batch_path(batch_id: str) -> str {
    name = _batch_name_from_id(batch_id);
    kind = _batch_kind(batch_id);
    if kind == "sample" {
        return sample_batch_path(name);
    }
    if kind == "upload" {
        return _upload_batch_path(name);
    }
    return "";
}

def batch_files(batch_id: str) -> list[str] {
    batch_dir = batch_path(batch_id);
    if not batch_dir {
        return [];
    }
    return _traj_files_in_dir(Path(batch_dir));
}

def sample_batch_files(name: str = "starter") -> list[str] {
    return batch_files("sample-" + name);
}

def sample_file_run_id(path: str) -> str {
    return path_run_stem(path);
}

def _batch_run_ids(files: list[str]) -> list[str] {
    return [sample_file_run_id(path) for path in files];
}

def _build_batch_summary(batch_id: str, source_path: str, source_format: str = "mini-swe-agent") -> dict[str, any] {
    files = batch_files(batch_id);
    run_ids = _batch_run_ids(files);
    return {
        "batch_id": batch_id,
        "name": _batch_name_from_id(batch_id),
        "source_format": source_format,
        "run_count": len(files),
        "run_ids": run_ids,
        "sample_path": source_path,
        "status": ("ready") if files else ("missing"),
        "next_step": "Use ParseBatch, AnalyzeBatch, or GetRunView on one of the discovered runs.",
    };
}

def sample_batch_summary(name: str = "starter") -> dict[str, any] {
    batch_id = "sample-" + name;
    return _build_batch_summary(batch_id, sample_batch_path(name));
}

def available_upload_batch_ids() -> list[str] {
    root_dir = Path(UPLOAD_ROOT);
    if not root_dir.exists() or not root_dir.is_dir() {
        return [];
    }
    batch_ids: list[str] = [];
    for path in sorted(root_dir.iterdir()) {
        if not path.is_dir() {
            continue;
        }
        if _traj_files_in_dir(path) {
            batch_ids.append("upload-" + _normalize_batch_name(path.name));
        }
    }
    return batch_ids;
}

def _resolve_upload_dir(filename: str) -> str {
    direct = Path(filename);
    candidates = [
        direct,
        Path(UPLOAD_ROOT) / filename,
        Path(UPLOAD_ROOT) / (filename + "_batch"),
    ];
    for candidate in candidates {
        if candidate.exists() and candidate.is_dir() and _traj_files_in_dir(candidate) {
            return str(candidate);
        }
    }
    return "";
}

def _path_under_upload_root(path: str) -> bool {
    try {
        return str(Path(path).resolve()).startswith(str(Path(UPLOAD_ROOT).resolve()));
    } except Exception {
        return False;
    }
}

def _managed_upload_alias_name(path: str) -> str {
    return _normalize_batch_name(Path(path).name);
}

def _ensure_managed_upload_dir(path: str) -> dict[str, str] {
    resolved_path = str(Path(path).resolve());
    if _path_under_upload_root(resolved_path) {
        return {
            "resolved_path": resolved_path,
            "managed_path": path,
            "managed_name": _managed_upload_alias_name(path),
            "managed": "false",
        };
    }

    root_dir = Path(UPLOAD_ROOT);
    root_dir.mkdir(parents=True, exist_ok=True);
    base_name = _managed_upload_alias_name(resolved_path);
    candidate = root_dir / base_name;
    suffix = 2;
    while candidate.exists() and not str(candidate.resolve()) == resolved_path {
        candidate = root_dir / (base_name + "_" + str(suffix));
        suffix += 1;
    }

    if not candidate.exists() {
        candidate.symlink_to(resolved_path, target_is_directory=True);
    }
    return {
        "resolved_path": resolved_path,
        "managed_path": str(candidate),
        "managed_name": _normalize_batch_name(candidate.name),
        "managed": "true",
    };
}

def _resolve_upload_archive(filename: str) -> str {
    direct = Path(filename);
    candidates = [
        direct,
        Path(UPLOAD_ROOT) / filename,
    ];
    if not str(direct).lower().endswith(".zip") {
        candidates.append(Path(str(direct) + ".zip"));
        candidates.append(Path(UPLOAD_ROOT) / (filename + ".zip"));
    }
    for candidate in candidates {
        if candidate.exists() and candidate.is_file() and str(candidate).lower().endswith(".zip") {
            return str(candidate);
        }
    }
    return "";
}

def _extract_upload_archive(archive_path: str) -> str {
    archive = Path(archive_path);
    target_dir = Path(UPLOAD_ROOT) / archive.stem;
    target_dir.mkdir(parents=True, exist_ok=True);
    zip_file = ZipFile(str(archive), "r");
    zip_file.extractall(str(target_dir));
    zip_file.close();
    return str(target_dir);
}

def upload_batch_summary(filename: str = "") -> dict[str, any] {
    available = available_upload_batch_ids();
    if not filename {
        return {
            "batch_id": "",
            "status": "awaiting_folder",
            "message": "Provide a folder name, folder path, or zip archive under uploads/ that contains *.traj.json files.",
            "available_uploads": available,
        };
    }

    resolved = _resolve_upload_dir(filename);
    resolved_archive = "";
    ingest_mode = "folder";
    if not resolved {
        resolved_archive = _resolve_upload_archive(filename);
        if resolved_archive {
            resolved = _extract_upload_archive(resolved_archive);
            ingest_mode = "zip";
        }
    }
    if not resolved {
        return {
            "batch_id": "",
            "filename": filename,
            "status": "missing",
            "message": "No local upload folder or zip archive with *.traj.json files was found for that name or path.",
            "available_uploads": available,
        };
    }

    managed = _ensure_managed_upload_dir(resolved);
    batch_name = managed["managed_name"];
    batch_id = "upload-" + batch_name;
    summary = _build_batch_summary(batch_id, managed["managed_path"]);
    summary["resolved_path"] = managed["managed_path"];
    summary["source_path"] = managed["resolved_path"];
    summary["managed_alias"] = managed["managed_path"];
    summary["managed_alias_created"] = managed["managed"] == "true";
    summary["ingest_mode"] = ingest_mode;
    if resolved_archive {
        summary["resolved_archive"] = resolved_archive;
    }
    summary["available_uploads"] = available_upload_batch_ids();
    return summary;
}

def batch_summary(batch_id: str) -> dict[str, any] {
    if _batch_kind(batch_id) == "sample" {
        return sample_batch_summary(_batch_name_from_id(batch_id));
    }
    if _batch_kind(batch_id) == "upload" {
        return upload_batch_summary(batch_path(batch_id));
    }
    return {
        "batch_id": batch_id,
        "status": "missing",
        "message": "Batch ID was not recognized.",
    };
}

def batch_catalog_summary() -> dict[str, any] {
    entries: list[dict[str, any]] = [];
    for batch_id in all_known_batch_ids() {
        summary = batch_summary(batch_id);
        entries.append(
            {
                "batch_id": summary["batch_id"],
                "name": summary["name"],
                "source_format": summary["source_format"],
                "run_count": summary["run_count"],
                "status": summary["status"],
                "path": summary.get("resolved_path") or summary.get("sample_path") or "",
                "kind": _batch_kind(batch_id),
            }
        );
    }
    return {
        "status": "ready" if entries else "missing",
        "batches": entries,
        "batch_count": len(entries),
    };
}

def parse_batch_summary(batch_id: str) -> dict[str, any] {
    files = batch_files(batch_id);
    if files {
        parsed_runs = [];
        for path in files {
            run = parse_run(path);
            parsed_runs.append(
                {
                    "run_id": run.run_id,
                    "instance_id": run.instance_id,
                    "task_title": run.task_title,
                    "step_count": len(run.steps),
                    "turn_count": len(run.turns),
                    "source_path": run.source_path,
                    "metadata": run.metadata,
                }
            );
        }
        return {
            "batch_id": batch_id,
            "status": "parsed",
            "run_count": len(parsed_runs),
            "runs": parsed_runs,
        };
    }
    return {
        "batch_id": batch_id,
        "status": "missing",
        "message": "No trajectories were found for that batch.",
    };
}

def all_known_batch_ids() -> list[str] {
    sample_batches: list[str] = [];
    sample_root = Path(SAMPLE_ROOT);
    if sample_root.exists() and sample_root.is_dir() {
        for path in sorted(sample_root.iterdir()) {
            if not path.is_dir() {
                continue;
            }
            if not _traj_files_in_dir(path) {
                continue;
            }
            sample_batches.append("sample-" + _normalize_batch_name(path.name));
        }
    }
    return sample_batches + available_upload_batch_ids();
}

def batch_ids_for_run(run_id: str) -> list[str] {
    batch_ids: list[str] = [];
    for batch_id in all_known_batch_ids() {
        for path in batch_files(batch_id) {
            if sample_file_run_id(path) == run_id {
                batch_ids.append(batch_id);
                break;
            }
        }
    }
    return batch_ids;
}

def batch_id_for_run(run_id: str) -> str {
    matches = batch_ids_for_run(run_id);
    if len(matches) == 1 {
        return matches[0];
    }
    return "";
}

def run_source_path(run_id: str, batch_id: str = "") -> str {
    chosen_batch_id = batch_id;
    if not chosen_batch_id {
        chosen_batch_id = batch_id_for_run(run_id);
    }
    if not chosen_batch_id {
        return "";
    }
    for path in batch_files(chosen_batch_id) {
        if sample_file_run_id(path) == run_id {
            return path;
        }
    }
    return "";
}

import from os { getenv }
import from traceforge.analysis { cluster_view_summary, run_view_summary }
import from traceforge.graph_build {
    ensure_batch_graph,
    failure_class_name,
    find_cluster_node,
    upsert_cluster_patch
}
import from traceforge.parser { truncate_text }
import from traceforge.provider_config { configured_provider_key }
import from traceforge.schema { ClusterLabel, ComparisonVerdict, FailureClass, MemoryPatchProposal, RunDiagnosis }

def choose_failure_class(text: str) -> FailureClass by llm();

def draft_cluster_label(text: str) -> ClusterLabel by llm();

def draft_memory_patch(text: str) -> MemoryPatchProposal by llm();

def propose_run_diagnosis(text: str) -> RunDiagnosis by llm();

def compare_run_diagnoses(text: str) -> ComparisonVerdict by llm();

def llm_enabled() -> bool {
    return str(configured_provider_key("openai") or getenv("OPENAI_API_KEY") or "") != "";
}

def diagnosis_reason(failure_class: str) -> str {
    reasons = {
        "PREMATURE_COMPLETION": "the run moved to submission before validating that the failing state had recovered",
        "INVALID_PATCH": "the patch introduced or preserved a syntax-level failure that the run never repaired",
        "WRONG_FILE_FOCUS": "the run spent effort on files that did not reduce the target failure",
        "OSCILLATION_LOOP": "the run repeated the same search or file-touch pattern without creating recovery evidence",
        "TOOL_MISUSE": "tool interactions kept returning failure signals and the run never corrected the workflow",
        "STALE_CONTEXT_OR_BAD_PLAN": "the run stayed in planning or inspection too long without decisive repo interaction",
        "REQUIREMENT_DRIFT": "the run drifted away from the issue target and never came back to a validating path",
        "UNKNOWN": "the failure pattern is not yet classified strongly enough for a tighter explanation",
    };
    return reasons.get(failure_class, reasons["UNKNOWN"]);
}

def cluster_rule_lines(failure_class: str) -> list[str] {
    if failure_class == "PREMATURE_COMPLETION" {
        return [
            "Before submitting, rerun at least one targeted failing test if any test failed earlier.",
            "Do not submit if the latest visible state lacks post-patch validation.",
        ];
    }
    if failure_class == "INVALID_PATCH" {
        return [
            "After applying a patch, run the targeted test before submitting.",
            "Do not submit when the latest output still shows syntax, import, or traceback failures.",
        ];
    }
    if failure_class == "OSCILLATION_LOOP" {
        return [
            "After two repeated search or same-file inspection cycles with no new evidence, change strategy.",
            "If the same file has been touched repeatedly without recovery, re-rank candidate files from failing tests and errors.",
        ];
    }
    if failure_class == "WRONG_FILE_FOCUS" {
        return [
            "Prioritize files named in failing tests, stack traces, or direct issue context before editing secondary files.",
            "If edits do not reduce the original failure signal, stop and re-rank the target files.",
        ];
    }
    if failure_class == "TOOL_MISUSE" {
        return [
            "Treat repeated non-zero tool outcomes as a strategy failure and adjust before continuing.",
            "Do not keep issuing malformed or irrelevant commands after the same failure repeats.",
        ];
    }
    if failure_class == "STALE_CONTEXT_OR_BAD_PLAN" {
        return [
            "Limit consecutive planning or search-only turns without touching the repo or validating a hypothesis.",
            "After prolonged inspection, commit to one concrete file-level hypothesis and test it.",
        ];
    }
    if failure_class == "REQUIREMENT_DRIFT" {
        return [
            "Keep edits anchored to the failing test, stack trace, or issue target.",
            "If later steps stop mentioning the original failure context, pause and re-establish the target before editing again.",
        ];
    }
    return [
        "Prefer targeted validation before submission.",
        "Escalate to a new strategy when repeated steps stop producing new evidence.",
    ];
}

def _join_tokens(items: list[any], limit: int = 3) -> str {
    chosen: list[str] = [];
    for item in items {
        if len(chosen) >= limit {
            break;
        }
        chosen.append(str(item));
    }
    return ", ".join(chosen);
}

def _critical_quote(run_view: dict[str, any]) -> str {
    for step in run_view["critical_evidence_window"] {
        if int(step["idx"]) == int(run_view["critical_step_idx"]) {
            return str(step["excerpt"]);
        }
    }
    if len(run_view["critical_evidence_window"]) > 0 {
        return str(run_view["critical_evidence_window"][0]["excerpt"]);
    }
    return str(run_view["summary"]);
}

def _cluster_support_records(root_node: any, cluster_view: dict[str, any]) -> list[dict[str, any]] {
    batch_id = str(cluster_view.get("batch_id") or str(cluster_view["cluster_id"]).split(":")[0]);
    support_records: list[dict[str, any]] = [];
    for run_item in cluster_view["representative_runs"] {
        if len(support_records) >= 3 {
            break;
        }
        run_view = run_view_summary(root_node, str(run_item["run_id"]), batch_id);
        if run_view["status"] == "stub" {
            continue;
        }
        support_records.append(
            {
                "run_id": run_view["run_id"],
                "batch_id": run_view["batch_id"],
                "critical_step_idx": run_view["critical_step_idx"],
                "quote": _critical_quote(run_view),
                "top_files": run_view["artifacts"]["fingerprint"].get("top_files", []),
                "top_tests": run_view["artifacts"]["fingerprint"].get("top_test_names", []),
                "top_errors": run_view["artifacts"]["fingerprint"].get("top_error_keywords", []),
            }
        );
    }
    return support_records;
}

def _supported_steps(records: list[dict[str, any]]) -> list[int] {
    steps: list[int] = [];
    for record in records {
        step_idx = int(record["critical_step_idx"]);
        if step_idx >= 0 and step_idx not in steps {
            steps.append(step_idx);
        }
    }
    return steps;
}

def _evidence_lines(cluster_view: dict[str, any], support_records: list[dict[str, any]]) -> list[str] {
    lines: list[str] = [];
    for record in support_records {
        lines.append(
            str(record["run_id"])
            + "@"
            + str(record["critical_step_idx"])
            + ": "
            + str(record["quote"])
        );
    }
    if cluster_view["recurring_tests"] {
        lines.append(
            "Recurring tests: "
            + _join_tokens([item[0] for item in cluster_view["recurring_tests"]], 3)
        );
    }
    if cluster_view["recurring_errors"] {
        lines.append(
            "Recurring errors: "
            + _join_tokens([item[0] for item in cluster_view["recurring_errors"]], 3)
        );
    }
    if cluster_view["recurring_files"] {
        lines.append(
            "Recurring files: "
            + _join_tokens([item[0] for item in cluster_view["recurring_files"]], 3)
        );
    }
    return lines;
}

def _evidence_grounded_rule_records(cluster_view: dict[str, any], support_records: list[dict[str, any]]) -> list[dict[str, any]] {
    failure_class = str(cluster_view["failure_class"]);
    base_rules = cluster_rule_lines(failure_class);
    recurring_tests = [item[0] for item in cluster_view["recurring_tests"]];
    recurring_errors = [item[0] for item in cluster_view["recurring_errors"]];
    recurring_files = [item[0] for item in cluster_view["recurring_files"]];
    step_refs = _supported_steps(support_records);
    evidence_anchor = _join_tokens(
        [
            str(record["run_id"]) + "@" + str(record["critical_step_idx"])
            for record in support_records
        ],
        3,
    );
    evidence_quote = _join_tokens([str(record["quote"]) for record in support_records], 2);
    records: list[dict[str, any]] = [];

    for (index, rule_text) in enumerate(base_rules) {
        refined_rule = rule_text;
        if failure_class == "PREMATURE_COMPLETION" and recurring_tests {
            refined_rule = "Before submitting after failures in " + _join_tokens(recurring_tests, 2) + ", rerun at least one targeted failing test.";
        } elif failure_class == "INVALID_PATCH" and recurring_errors {
            refined_rule = "Do not keep a patch live when errors like " + _join_tokens(recurring_errors, 2) + " still appear after the edit.";
        } elif failure_class == "WRONG_FILE_FOCUS" and recurring_files {
            refined_rule = "Prioritize files like " + _join_tokens(recurring_files, 2) + " before editing secondary files.";
        } elif failure_class == "OSCILLATION_LOOP" and recurring_files {
            refined_rule = "If the run revisits " + _join_tokens(recurring_files, 2) + " without reducing failures, stop and re-rank targets.";
        } elif failure_class == "TOOL_MISUSE" and recurring_errors {
            refined_rule = "Treat repeated tool failures such as " + _join_tokens(recurring_errors, 2) + " as a strategy reset signal, not a reason to repeat the same command.";
        }

        records.append(
            {
                "title": str(cluster_view["label"]) + " rule " + str(index + 1),
                "rationale": "Supported by " + evidence_anchor + ". Evidence: " + evidence_quote,
                "rule_text": refined_rule,
                "supported_by_steps": step_refs,
                "confidence": 0.66 if len(step_refs) >= 2 else 0.6,
            }
        );
    }
    return records;
}

def _run_evidence_pack(run_view: dict[str, any]) -> str {
    lines: list[str] = [];
    lines.append("TraceForge run evidence pack");
    lines.append("Run ID: " + str(run_view["run_id"]));
    lines.append("Task: " + str(run_view["task_title"]));
    lines.append("Primary failure candidate: " + str(run_view["primary_failure"]));
    lines.append("Critical step candidate: " + str(run_view["critical_step_idx"]));
    lines.append("Summary: " + str(run_view["summary"]));
    lines.append("Fingerprint:");
    lines.append(str(run_view["artifacts"]["fingerprint"]));
    lines.append("Critical evidence window:");
    for step in run_view["critical_evidence_window"] {
        lines.append(
            "Step "
            + str(step["idx"])
            + " ["
            + str(step["phase"])
            + "]: "
            + str(step["excerpt"])
        );
    }
    return truncate_text("\n".join(lines), 2200);
}

def _cluster_evidence_pack(cluster_view: dict[str, any]) -> str {
    lines: list[str] = [];
    lines.append("TraceForge cluster evidence pack");
    lines.append("Cluster ID: " + str(cluster_view["cluster_id"]));
    lines.append("Cluster label candidate: " + str(cluster_view["label"]));
    lines.append("Failure class: " + str(cluster_view["failure_class"]));
    lines.append("Cluster size: " + str(cluster_view["size"]));
    lines.append("Summary: " + str(cluster_view["summary"]));
    lines.append("Recurring signals:");
    for signal in cluster_view["recurring_signals"] {
        lines.append("- " + str(signal));
    }
    lines.append("Representative runs:");
    for run_item in cluster_view["representative_runs"] {
        lines.append(
            "- "
            + str(run_item["run_id"])
            + ": "
            + str(run_item["summary"])
        );
    }
    return truncate_text("\n".join(lines), 2000);
}

def _deterministic_diagnosis(run_view: dict[str, any]) -> dict[str, any] {
    evidence = [];
    for step in run_view["critical_evidence_window"] {
        evidence.append(
            {
                "step_idx": step["idx"],
                "artifact": step["phase"],
                "quote": step["excerpt"],
            }
        );
    }
    failure_class = str(run_view.get("primary_failure") or "UNKNOWN");
    return {
        "run_id": run_view["run_id"],
        "failure_class": failure_class,
        "critical_step_idx": run_view["critical_step_idx"],
        "irreversible_because": diagnosis_reason(failure_class),
        "evidence": evidence,
        "confidence": 0.68 if run_view["critical_step_idx"] >= 0 else 0.2,
        "status": "deterministic_diagnosis",
        "llm_used": False,
        "evidence_pack": _run_evidence_pack(run_view),
    };
}

def _deterministic_cluster_label(cluster_view: dict[str, any]) -> dict[str, any] {
    return {
        "cluster_id": cluster_view["cluster_id"],
        "label": cluster_view["label"],
        "summary": cluster_view["summary"],
        "failure_class": cluster_view["failure_class"],
        "confidence": 0.7,
        "status": "deterministic_cluster_label",
        "llm_used": False,
        "evidence_pack": _cluster_evidence_pack(cluster_view),
    };
}

def _deterministic_patch(root_node: any, cluster_view: dict[str, any]) -> dict[str, any] {
    support_records = _cluster_support_records(root_node, cluster_view);
    rules = _evidence_grounded_rule_records(cluster_view, support_records);
    evidence_lines = _evidence_lines(cluster_view, support_records);
    diff_lines = [
        "--- AGENTS.md",
        "+++ AGENTS.md",
        "@@",
        "+## " + str(cluster_view["label"]),
        "+### Evidence Anchors",
    ];
    if evidence_lines {
        for line in evidence_lines {
            diff_lines.append("+- " + line);
        }
    } else {
        diff_lines.append("+- No representative evidence was available; using recurring cluster signals only.");
    }
    diff_lines.append("+### Rules");
    for rule in rules {
        diff_lines.append("+- " + str(rule["rule_text"]));
    }
    return {
        "cluster_id": cluster_view["cluster_id"],
        "scope": "cluster",
        "cluster_label": cluster_view["label"],
        "summary": "Operational memory patch synthesized from representative runs, critical-step evidence, and recurring cluster signals.",
        "rules": rules,
        "diff_text": "\n".join(diff_lines),
        "confidence": 0.66 if len(rules) > 0 else 0.5,
        "status": "deterministic_patch",
        "llm_used": False,
        "evidence_pack": _cluster_evidence_pack(cluster_view) + "\nEvidence anchors:\n" + "\n".join(evidence_lines),
    };
}

def _store_patch_response(root_node: any, cluster_id: str, response: dict[str, any]) -> dict[str, any] {
    batch_id = cluster_id.split(":")[0];
    compiled = ensure_batch_graph(root_node, batch_id);
    if compiled["batch"] is not None {
        cluster_node = find_cluster_node(compiled["batch"], cluster_id);
        if cluster_node is not None {
            stored = upsert_cluster_patch(
                cluster_node,
                {
                    "patch_id": cluster_id + ":memory_patch",
                    "scope": str(response["scope"]),
                    "title": str(response["cluster_label"]) + " memory patch",
                    "diff_text": str(response["diff_text"]),
                    "confidence": float(response["confidence"]),
                },
            );
            response["stored_patch_id"] = stored["patch_id"];
            response["stored_in_graph"] = True;
            response["stored_patch_created"] = stored["created"];
            return response;
        }
    }
    response["stored_in_graph"] = False;
    return response;
}

def diagnose_run_summary(root_node: any, run_id: str, batch_id: str = "") -> dict[str, any] {
    run_view = run_view_summary(root_node, run_id, batch_id);
    if run_view["status"] == "stub" {
        return {
            "run_id": run_id,
            "status": "missing",
            "message": "Run was not found.",
        };
    }

    fallback = _deterministic_diagnosis(run_view);
    if not llm_enabled() {
        return fallback;
    }

    try {
        predicted = choose_failure_class(fallback["evidence_pack"]);
        predicted_name = failure_class_name(predicted);
        return {
            "run_id": fallback["run_id"],
            "failure_class": predicted_name,
            "critical_step_idx": fallback["critical_step_idx"],
            "irreversible_because": diagnosis_reason(predicted_name),
            "evidence": fallback["evidence"],
            "confidence": 0.8 if fallback["critical_step_idx"] >= 0 else 0.35,
            "status": "llm_validated_diagnosis",
            "llm_used": True,
            "evidence_pack": fallback["evidence_pack"],
        };
    } except Exception as err {
        fallback["llm_error"] = str(err);
        return fallback;
    }
}

def diagnose_cluster_summary(root_node: any, cluster_id: str) -> dict[str, any] {
    cluster_view = cluster_view_summary(root_node, cluster_id);
    if cluster_view["status"] == "missing" {
        return {
            "cluster_id": cluster_id,
            "status": "missing",
            "message": "Cluster was not found.",
        };
    }

    fallback = _deterministic_cluster_label(cluster_view);
    if not llm_enabled() {
        return fallback;
    }

    try {
        labeled = draft_cluster_label(fallback["evidence_pack"]);
        return {
            "cluster_id": cluster_id,
            "label": labeled.label,
            "summary": labeled.summary,
            "failure_class": cluster_view["failure_class"],
            "confidence": labeled.confidence,
            "status": "llm_cluster_label",
            "llm_used": True,
            "evidence_pack": fallback["evidence_pack"],
        };
    } except Exception as err {
        fallback["llm_error"] = str(err);
        return fallback;
    }
}

def compile_memory_patch_summary(root_node: any, cluster_id: str) -> dict[str, any] {
    cluster_view = cluster_view_summary(root_node, cluster_id);
    if cluster_view["status"] == "missing" {
        return {
            "cluster_id": cluster_id,
            "status": "missing",
            "message": "Cluster was not found.",
        };
    }

    fallback = _deterministic_patch(root_node, cluster_view);
    if not llm_enabled() {
        return _store_patch_response(root_node, cluster_id, fallback);
    }

    try {
        proposal = draft_memory_patch(fallback["evidence_pack"]);
        output_rules = [];
        max_confidence = 0.64;
        for rule in proposal.rules {
            rule_confidence = float(rule.confidence);
            if rule_confidence > max_confidence {
                max_confidence = rule_confidence;
            }
            output_rules.append(
                {
                    "title": rule.title,
                    "rationale": rule.rationale,
                    "rule_text": rule.rule_text,
                    "supported_by_steps": rule.supported_by_steps,
                    "confidence": rule.confidence,
                }
            );
        }

        chosen_diff_text = proposal.diff_text;
        if not chosen_diff_text {
            chosen_diff_text = fallback["diff_text"];
        }
        chosen_cluster_label = proposal.cluster_label;
        if not chosen_cluster_label {
            chosen_cluster_label = cluster_view["label"];
        }

        llm_response = {
            "cluster_id": cluster_id,
            "scope": proposal.scope or "cluster",
            "cluster_label": chosen_cluster_label,
            "summary": proposal.summary,
            "rules": output_rules if output_rules else fallback["rules"],
            "diff_text": chosen_diff_text,
            "confidence": max_confidence,
            "status": "llm_patch",
            "llm_used": True,
            "evidence_pack": fallback["evidence_pack"],
        };
        return _store_patch_response(root_node, cluster_id, llm_response);
    } except Exception as err {
        fallback["llm_error"] = str(err);
        return _store_patch_response(root_node, cluster_id, fallback);
    }
}

import json;
import hashlib;
import from pathlib { Path }

obj RawTurn {
    has index: int;
    has role: str;
    has content: str;
    has raw: dict[str, any] = {};
}

obj ParsedStep {
    has index: int;
    has role: str = "other";
    has kind: str = "OTHER";
    has phase: str = "other";
    has excerpt: str = "";
    has content_hash: str = "";
    has assistant_content: str = "";
    has trailing_turns: list[RawTurn] = [];
    has touched_files: list[str] = [];
    has command_text: str = "";
    has patch_text: str = "";
    has test_text: str = "";
    has error_text: str = "";
    has submit_text: str = "";
}

obj ParsedRun {
    has run_id: str;
    has source_path: str;
    has raw: dict[str, any] = {};
    has turns: list[RawTurn] = [];
    has steps: list[ParsedStep] = [];
    has metadata: dict[str, any] = {};
    has instance_id: str = "";
    has task_title: str = "";
}

def truncate_text(text: str, limit: int = 280) -> str {
    clean = text.strip();
    if len(clean) <= limit {
        return clean;
    }
    return clean[: max(limit - 3, 0)].rstrip() + "...";
}

def unique_strings(items: list[str]) -> list[str] {
    seen: set[str] = set();
    output: list[str] = [];
    for item in items {
        if item in seen {
            continue;
        }
        seen.add(item);
        output.append(item);
    }
    return output;
}

def path_run_stem(path: str) -> str {
    name = Path(path).name;
    if name.endswith(".traj.json") {
        return name.removesuffix(".traj.json");
    }
    return Path(path).stem;
}

def load_trajectory_file(path: str) -> dict[str, any] {
    text = Path(path).read_text(encoding="utf-8");
    data = json.loads(text);
    if not isinstance(data, dict) {
        raise ValueError("trajectory file must decode to a JSON object");
    }
    return data;
}

def _turn_role(item: dict[str, any]) -> str {
    role = item.get("role");
    if role is None {
        role = item.get("speaker");
    }
    if role is None {
        role = item.get("type");
    }
    if role is None {
        role = "other";
    }
    return str(role).lower();
}

def _tool_call_name(call: dict[str, any]) -> str {
    function_payload = call.get("function");
    if isinstance(function_payload, dict) {
        name = function_payload.get("name");
        if name is not None and str(name) {
            return str(name);
        }
    }
    name = call.get("name");
    if name is not None and str(name) {
        return str(name);
    }
    return "tool_call";
}

def _tool_call_arguments(call: dict[str, any]) -> str {
    function_payload = call.get("function");
    if isinstance(function_payload, dict) {
        arguments = function_payload.get("arguments");
        if arguments is not None and str(arguments) {
            return str(arguments);
        }
    }
    arguments = call.get("arguments");
    if arguments is not None and str(arguments) {
        return str(arguments);
    }
    return "";
}

def _tool_call_summary(item: dict[str, any]) -> str {
    tool_calls = item.get("tool_calls");
    if not isinstance(tool_calls, list) {
        return "";
    }
    rendered: list[str] = [];
    for call in tool_calls {
        if not isinstance(call, dict) {
            continue;
        }
        line = "- " + _tool_call_name(call);
        arguments = _tool_call_arguments(call);
        if arguments {
            line += " args=" + truncate_text(arguments, 160);
        }
        rendered.append(line);
    }
    if not rendered {
        return "";
    }
    return "Tool calls:\n" + "\n".join(rendered);
}

def _turn_content(item: dict[str, any]) -> str {
    parts: list[str] = [];
    role = _turn_role(item);
    if role == "tool" {
        tool_name = item.get("name");
        if tool_name is not None and str(tool_name) {
            parts.append("Tool: " + str(tool_name));
        }
        tool_call_id = item.get("tool_call_id");
        if tool_call_id is not None and str(tool_call_id) {
            parts.append("Tool call id: " + str(tool_call_id));
        }
    }

    content = item.get("content");
    if content is None {
        content = item.get("text");
    }
    if content is None {
        content = item.get("message");
    }
    content_text = "";
    if content is not None {
        if isinstance(content, str) {
            content_text = content;
        } else {
            content_text = json.dumps(content);
        }
    }
    if content_text {
        parts.append(content_text);
    }

    tool_call_text = _tool_call_summary(item);
    if tool_call_text {
        parts.append(tool_call_text);
    }

    return "\n".join([part for part in parts if part]).strip();
}

def extract_turns(raw: dict[str, any]) -> list[RawTurn] {
    items: list[any] = [];
    candidates = [
        raw.get("trajectory"),
        raw.get("messages"),
        raw.get("history"),
        raw.get("turns"),
    ];
    for candidate in candidates {
        if isinstance(candidate, list) {
            items = candidate;
            break;
        }
    }

    turns: list[RawTurn] = [];
    for (index, item) in enumerate(items) {
        if not isinstance(item, dict) {
            continue;
        }
        item_dict = dict(item);
        turns.append(
            RawTurn(
                index=index,
                role=_turn_role(item_dict),
                content=_turn_content(item_dict),
                raw=item_dict,
            )
        );
    }
    return turns;
}

def hash_text(text: str) -> str {
    return hashlib.sha256(text.encode("utf-8")).hexdigest();
}

def _contains_any(lower: str, tokens: list[str]) -> bool {
    for token in tokens {
        if token in lower {
            return True;
        }
    }
    return False;
}

def _nonempty_lines(text: str) -> list[str] {
    lines: list[str] = [];
    for raw_line in text.split("\n") {
        line = raw_line.strip();
        if line {
            lines.append(line);
        }
    }
    return lines;
}

def _looks_like_shell_command(text: str) -> bool {
    lower = text.lower().strip();
    if not lower {
        return False;
    }
    prefixes = [
        "$ ",
        "python ",
        "pytest ",
        "py.test ",
        "bash ",
        "sh ",
        "git ",
        "ls ",
        "find ",
        "grep ",
        "rg ",
        "sed ",
        "cat ",
        "head ",
        "tail ",
        "apply_patch",
    ];
    if _contains_any(lower, ["returncode", "exit code", "non-zero exit", "command failed"]) {
        return True;
    }
    for line in _nonempty_lines(text) {
        lower_line = line.lower();
        for prefix in prefixes {
            if lower_line.startswith(prefix) {
                return True;
            }
        }
    }
    return False;
}

def _looks_like_patch_payload(text: str) -> bool {
    lower = text.lower();
    if _contains_any(lower, ["apply_patch", "diff --git", "*** begin patch", "@@ ", "--- ", "+++ "]) {
        return True;
    }
    plus_lines = 0;
    minus_lines = 0;
    for line in text.split("\n") {
        if line.startswith("+++") or line.startswith("---") {
            continue;
        }
        if line.startswith("+") {
            plus_lines += 1;
        } elif line.startswith("-") {
            minus_lines += 1;
        }
    }
    return plus_lines + minus_lines >= 3;
}

def _looks_like_test_signal(text: str) -> bool {
    lower = text.lower();
    return _contains_any(
        lower,
        [
            "pytest",
            "py.test",
            "test session starts",
            "collected ",
            "::",
            " passed",
            " failed",
            "assert ",
            "failing tests",
        ],
    );
}

def _looks_like_error_signal(text: str) -> bool {
    lower = text.lower();
    return _contains_any(
        lower,
        [
            "traceback",
            "exception",
            "syntaxerror",
            "importerror",
            "module not found",
            "assertionerror",
            "error:",
            " error ",
            "failed",
        ],
    );
}

def _looks_like_submit_signal(text: str) -> bool {
    lower = text.lower();
    return _contains_any(
        lower,
        [
            "submit",
            "final answer",
            "final response",
            "ready to submit",
            "i will submit",
            "i'll submit",
            "submitting now",
        ],
    );
}

def _looks_like_inspect_signal(text: str) -> bool {
    lower = text.lower();
    return _contains_any(lower, ["grep ", "ls ", "find ", "read ", "inspect", "open ", "cat ", "sed ", "rg "]);
}

def infer_kind(role: str, text: str) -> str {
    lower = text.lower();
    if _looks_like_submit_signal(text) {
        return "SUBMIT";
    }
    if _looks_like_patch_payload(text) {
        return "EDIT";
    }
    if _looks_like_test_signal(text) {
        return "TEST";
    }
    if _looks_like_error_signal(text) {
        return "ERROR";
    }
    if _looks_like_shell_command(text) {
        return "COMMAND";
    }
    if role in {"tool", "command"} {
        return "TOOL";
    }
    if role == "system" {
        return role.upper();
    }
    if role in {"assistant", "agent"} {
        return "ASSISTANT";
    }
    return "OTHER";
}

def infer_phase(text: str) -> str {
    if _looks_like_submit_signal(text) {
        return "submit";
    }
    if _looks_like_patch_payload(text) {
        return "edit";
    }
    if _looks_like_test_signal(text) {
        return "test";
    }
    if _looks_like_error_signal(text) {
        return "error";
    }
    if _looks_like_inspect_signal(text) {
        return "inspect";
    }
    if _looks_like_shell_command(text) {
        return "command";
    }
    return "reason";
}

def extract_file_tokens(text: str) -> list[str] {
    tokens: list[str] = [];
    for chunk in text.replace("`", " ").split() {
        cleaned = chunk.strip(" ,:;()[]{}<>");
        if not cleaned {
            continue;
        }
        if "/" in cleaned or "::" in cleaned {
            tokens.append(cleaned);
            continue;
        }
        if (
            cleaned.endswith(".py")
            or cleaned.endswith(".md")
            or cleaned.endswith(".json")
            or cleaned.endswith(".toml")
            or cleaned.endswith(".yaml")
            or cleaned.endswith(".yml")
        ) {
            tokens.append(cleaned);
        }
    }
    return unique_strings(tokens);
}

def step_text(step: ParsedStep) -> str {
    parts: list[str] = [];
    if step.assistant_content {
        parts.append(step.assistant_content);
    }
    for turn in step.trailing_turns {
        if turn.content {
            parts.append(turn.content);
        }
    }
    return "\n".join(parts);
}

def step_has_command(step: ParsedStep) -> bool {
    return bool(step.command_text);
}

def step_has_patch(step: ParsedStep) -> bool {
    return bool(step.patch_text);
}

def step_has_test(step: ParsedStep) -> bool {
    return bool(step.test_text);
}

def step_has_error(step: ParsedStep) -> bool {
    return bool(step.error_text);
}

def step_has_submit(step: ParsedStep) -> bool {
    return bool(step.submit_text);
}

def _final_kind_from_step(step: ParsedStep, full_text: str) -> str {
    if step_has_submit(step) {
        return "SUBMIT";
    }
    if step_has_patch(step) {
        return "EDIT";
    }
    if step_has_test(step) {
        return "TEST";
    }
    if step_has_error(step) {
        return "ERROR";
    }
    if step_has_command(step) {
        return "COMMAND";
    }
    return infer_kind(step.role, full_text);
}

def _final_phase_from_step(step: ParsedStep, full_text: str) -> str {
    if step_has_submit(step) {
        return "submit";
    }
    if step_has_patch(step) {
        return "edit";
    }
    if step_has_test(step) {
        return "test";
    }
    if step_has_error(step) {
        return "error";
    }
    if step_has_command(step) and _looks_like_inspect_signal(step.command_text) {
        return "inspect";
    }
    if step_has_command(step) {
        return "command";
    }
    return infer_phase(full_text);
}

def finalize_step(step: ParsedStep) -> ParsedStep {
    text = step_text(step);
    if not step.content_hash {
        step.content_hash = hash_text(text);
    }
    if not step.excerpt {
        step.excerpt = truncate_text(text);
    }
    step.touched_files = extract_file_tokens(text);
    command_matches: list[str] = [];
    patch_matches: list[str] = [];
    test_matches: list[str] = [];
    error_matches: list[str] = [];
    submit_matches: list[str] = [];
    payloads: list[str] = [];
    if step.assistant_content {
        payloads.append(step.assistant_content);
    }
    for turn in step.trailing_turns {
        if turn.content {
            payloads.append(turn.content);
        }
    }
    for payload in payloads {
        if _looks_like_shell_command(payload) {
            command_matches.append(payload);
        }
        if _looks_like_patch_payload(payload) {
            patch_matches.append(payload);
        }
        if _looks_like_test_signal(payload) {
            test_matches.append(payload);
        }
        if _looks_like_error_signal(payload) {
            error_matches.append(payload);
        }
        if _looks_like_submit_signal(payload) {
            submit_matches.append(payload);
        }
    }
    if command_matches {
        step.command_text = truncate_text("\n".join(command_matches), 600);
    }
    if patch_matches {
        step.patch_text = truncate_text("\n".join(patch_matches), 600);
    }
    if test_matches {
        step.test_text = truncate_text("\n".join(test_matches), 600);
    }
    if error_matches {
        step.error_text = truncate_text("\n".join(error_matches), 600);
    }
    if submit_matches {
        step.submit_text = truncate_text("\n".join(submit_matches), 280);
    }
    step.kind = _final_kind_from_step(step, text);
    step.phase = _final_phase_from_step(step, text);
    return step;
}

def segment_steps(turns: list[RawTurn]) -> list[ParsedStep] {
    steps: list[ParsedStep] = [];
    current = ParsedStep(index=0);
    has_current = False;

    for turn in turns {
        is_assistant = turn.role in {"assistant", "agent"};
        if is_assistant {
            if has_current {
                steps.append(finalize_step(current));
            }
            current = ParsedStep(index=len(steps));
            has_current = True;
            current.role = turn.role;
            current.assistant_content = turn.content;
            current.excerpt = truncate_text(turn.content);
            current.content_hash = hash_text(turn.content);
            continue;
        }

        if not has_current {
            current = ParsedStep(index=len(steps));
            has_current = True;
            current.role = turn.role;
        }

        current.trailing_turns.append(turn);
        current.excerpt = truncate_text((current.excerpt + "\n" + turn.content).strip());
        if turn.content {
            if current.content_hash {
                current.content_hash = hash_text(current.content_hash + turn.content);
            } else {
                current.content_hash = hash_text(turn.content);
            }
        }
    }

    if has_current {
        steps.append(finalize_step(current));
    }

    return steps;
}

def inferred_task_title(turns: list[RawTurn]) -> str {
    for turn in turns {
        if turn.role != "user" or not turn.content {
            continue;
        }
        first_line = turn.content.split("\n")[0].strip();
        if not first_line {
            continue;
        }
        if first_line.lower().startswith("task:") {
            return truncate_text(first_line[5:].strip(), 160);
        }
        return truncate_text(first_line, 160);
    }
    return "";
}

def _int_or_default(value: int | float | str | None, fallback: int = 0) -> int {
    if value is None or value == "" {
        return fallback;
    }
    return int(float(value));
}

def _float_or_default(value: int | float | str | None, fallback: float = 0.0) -> float {
    if value is None or value == "" {
        return fallback;
    }
    return float(value);
}

def _normalized_metadata(raw: dict[str, any]) -> dict[str, any] {
    metadata = raw.get("metadata");
    if not isinstance(metadata, dict) {
        metadata = {};
    }
    normalized = dict(metadata);

    info = raw.get("info");
    if isinstance(info, dict) {
        exit_status = info.get("exit_status");
        if exit_status is not None and str(exit_status) {
            normalized["status"] = str(exit_status);
            normalized["exit_status"] = str(exit_status);
        }

        traceback_text = info.get("traceback");
        if traceback_text is not None and str(traceback_text) {
            normalized["traceback"] = str(traceback_text);
        }

        submission = info.get("submission");
        submission_text = str(submission) if submission is not None else "";
        if submission_text {
            normalized["submission"] = submission_text;
        }

        mini_version = info.get("mini_version");
        if mini_version is not None and str(mini_version) {
            normalized["mini_version"] = str(mini_version);
        }

        model_stats = info.get("model_stats");
        if isinstance(model_stats, dict) {
            api_calls_value = model_stats.get("api_calls");
            instance_cost_value = model_stats.get("instance_cost");
            normalized["api_calls"] = _int_or_default(api_calls_value, normalized.get("api_calls", 0));
            normalized["instance_cost"] = _float_or_default(instance_cost_value, normalized.get("instance_cost", 0.0));
        }
    }

    trajectory_format = raw.get("trajectory_format");
    if trajectory_format is not None and str(trajectory_format) {
        normalized["trajectory_format"] = str(trajectory_format);
    }
    if "status" in normalized and "exit_status" not in normalized {
        normalized["exit_status"] = str(normalized["status"]);
    }
    return normalized;
}

def parse_run(source_path: str, run_id: str = "") -> ParsedRun {
    raw = load_trajectory_file(source_path);
    turns = extract_turns(raw);
    steps = segment_steps(turns);
    metadata = _normalized_metadata(raw);
    info_dict: dict[str, any] = {};
    raw_info = raw.get("info");
    if isinstance(raw_info, dict) {
        info_dict = raw_info;
    }
    chosen_run_id = run_id;
    if not chosen_run_id {
        raw_run_id = raw.get("run_id");
        raw_instance_id = raw.get("instance_id");
        if raw_run_id is not None and str(raw_run_id) {
            chosen_run_id = str(raw_run_id);
        } elif raw_instance_id is not None and str(raw_instance_id) {
            chosen_run_id = str(raw_instance_id);
        } else {
            chosen_run_id = path_run_stem(source_path);
        }
    }
    return ParsedRun(
        run_id=chosen_run_id,
        source_path=source_path,
        raw=raw,
        turns=turns,
        steps=steps,
        metadata=metadata,
        instance_id=str(raw.get("instance_id") or info_dict.get("instance_id") or ""),
        task_title=str(raw.get("task_title") or raw.get("task") or info_dict.get("task_title") or inferred_task_title(turns)),
    );
}

import json;
import from os { environ, getenv }
import from pathlib { Path }
import from shutil { which }
import from subprocess { run }

def _provider_config_dir() -> any {
    return Path(".traceforge");
}

def _provider_config_path() -> any {
    return _provider_config_dir().joinpath("provider_settings.json");
}

def _default_provider_config() -> dict[str, any] {
    return {
        "preferred_provider": "auto",
        "openai": {
            "api_key": "",
            "model": "gpt-5.4",
        },
        "anthropic": {
            "api_key": "",
            "model": "claude-sonnet-4-20250514",
        },
        "codex": {
            "model": "gpt-5.4",
            "cli_path": "",
        },
    };
}

def _normalize_provider_name(name: str) -> str {
    lowered = str(name or "auto").lower();
    return lowered if lowered in {"auto", "openai", "anthropic", "codex"} else "auto";
}

def _load_provider_config() -> dict[str, any] {
    payload = _default_provider_config();
    path = _provider_config_path();
    if not path.exists() {
        return payload;
    }
    try {
        loaded = json.loads(path.read_text(encoding="utf-8"));
    } except Exception {
        return payload;
    }
    if not isinstance(loaded, dict) {
        return payload;
    }

    payload["preferred_provider"] = _normalize_provider_name(str(loaded.get("preferred_provider") or "auto"));
    for provider in ["openai", "anthropic", "codex"] {
        provider_payload = loaded.get(provider);
        if not isinstance(provider_payload, dict) {
            continue;
        }
        for field in payload[provider].keys() {
            if field in provider_payload and provider_payload[field] is not None {
                payload[provider][field] = str(provider_payload[field] or "");
            }
        }
    }
    return payload;
}

def _write_provider_config(payload: dict[str, any]) -> None {
    config_dir = _provider_config_dir();
    config_dir.mkdir(parents=True, exist_ok=True);
    _provider_config_path().write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8");
}

def _masked_secret(secret: str) -> str {
    if not secret {
        return "";
    }
    if len(secret) <= 8 {
        return "*" * len(secret);
    }
    return secret[:4] + "..." + secret[-4:];
}

def configured_provider_key(provider: str) -> str {
    provider_name = _normalize_provider_name(provider);
    if provider_name not in {"openai", "anthropic"} {
        return "";
    }
    config = _load_provider_config();
    saved = str(config[provider_name].get("api_key") or "");
    if saved {
        return saved;
    }
    if provider_name == "openai" {
        return str(getenv("OPENAI_API_KEY") or "");
    }
    return str(getenv("ANTHROPIC_API_KEY") or "");
}

def configured_provider_model(provider: str, requested_model: str = "") -> str {
    if requested_model {
        return str(requested_model);
    }
    provider_name = _normalize_provider_name(provider);
    if provider_name not in {"openai", "anthropic", "codex"} {
        return "";
    }
    config = _load_provider_config();
    saved = str(config[provider_name].get("model") or "");
    if saved {
        return saved;
    }
    if provider_name == "openai" {
        return str(getenv("TRACEFORGE_OPENAI_MODEL") or getenv("OPENAI_MODEL") or "gpt-5.4");
    }
    if provider_name == "anthropic" {
        return str(getenv("TRACEFORGE_ANTHROPIC_MODEL") or getenv("ANTHROPIC_MODEL") or "claude-sonnet-4-20250514");
    }
    return str(getenv("TRACEFORGE_CODEX_MODEL") or getenv("CODEX_MODEL") or "gpt-5.4");
}

def configured_codex_cli_path() -> str {
    config = _load_provider_config();
    saved = str(config["codex"].get("cli_path") or "");
    if saved and Path(saved).exists() {
        return saved;
    }
    discovered = which("codex");
    return str(discovered or "");
}

def _key_source(provider: str) -> str {
    provider_name = _normalize_provider_name(provider);
    config = _load_provider_config();
    saved = str(config.get(provider_name, {}).get("api_key") or "");
    if saved {
        return "saved";
    }
    if provider_name == "openai" and getenv("OPENAI_API_KEY") {
        return "env";
    }
    if provider_name == "anthropic" and getenv("ANTHROPIC_API_KEY") {
        return "env";
    }
    return "none";
}

def _sync_runtime_environment() -> None {
    config = _load_provider_config();
    openai_key = str(config["openai"].get("api_key") or "");
    anthropic_key = str(config["anthropic"].get("api_key") or "");
    openai_model = str(config["openai"].get("model") or "");
    anthropic_model = str(config["anthropic"].get("model") or "");
    codex_model = str(config["codex"].get("model") or "");

    if openai_key {
        environ["OPENAI_API_KEY"] = openai_key;
    }
    if anthropic_key {
        environ["ANTHROPIC_API_KEY"] = anthropic_key;
    }
    if openai_model {
        environ["TRACEFORGE_OPENAI_MODEL"] = openai_model;
    }
    if anthropic_model {
        environ["TRACEFORGE_ANTHROPIC_MODEL"] = anthropic_model;
    }
    if codex_model {
        environ["TRACEFORGE_CODEX_MODEL"] = codex_model;
    }
}

def _codex_status() -> dict[str, any] {
    cli_path = configured_codex_cli_path();
    if not cli_path {
        return {
            "available": False,
            "logged_in": False,
            "cli_path": "",
            "version": "",
            "login_status": "Codex CLI not found on PATH.",
            "model": configured_provider_model("codex"),
        };
    }

    version = "";
    login_status = "";
    logged_in = False;
    try {
        version_run = run([cli_path, "--version"], capture_output=True, text=True, check=False, timeout=15);
        version = str(version_run.stdout or version_run.stderr or "").strip();
    } except Exception as err {
        version = "Version check failed: " + str(err);
    }

    try {
        login_run = run([cli_path, "login", "status"], capture_output=True, text=True, check=False, timeout=15);
        login_status = str(login_run.stdout or login_run.stderr or "").strip();
        lowered = login_status.lower();
        logged_in = int(login_run.returncode) == 0 and "logged in" in lowered and "not logged in" not in lowered;
    } except Exception as err {
        login_status = "Login status failed: " + str(err);
    }

    return {
        "available": True,
        "logged_in": logged_in,
        "cli_path": cli_path,
        "version": version,
        "login_status": login_status or "No login status available.",
        "model": configured_provider_model("codex"),
    };
}

def provider_resolution_summary(provider: str = "auto", model: str = "") -> dict[str, any] {
    preferred = _normalize_provider_name(provider);
    if preferred in {"openai", "anthropic", "codex"} {
        if preferred == "codex" {
            codex = _codex_status();
            return {
                "provider": "codex",
                "model": configured_provider_model("codex", model),
                "available": bool(codex["available"] and codex["logged_in"]),
                "source": "explicit",
            };
        }
        resolved_model = configured_provider_model(preferred, model);
        return {
            "provider": preferred,
            "model": resolved_model,
            "available": bool(configured_provider_key(preferred) and resolved_model),
            "source": "explicit",
        };
    }

    config = _load_provider_config();
    preferred_saved = _normalize_provider_name(str(config.get("preferred_provider") or "auto"));
    candidates: list[str] = [];
    if preferred_saved in {"openai", "anthropic", "codex"} {
        candidates.append(preferred_saved);
    } elif preferred_saved == "auto" {
        candidates.append("codex");
    }
    for candidate in ["codex", "openai", "anthropic"] {
        if candidate not in candidates {
            candidates.append(candidate);
        }
    }

    for candidate in candidates {
        if candidate == "codex" {
            codex = _codex_status();
            if codex["available"] and codex["logged_in"] {
                return {
                    "provider": "codex",
                    "model": configured_provider_model("codex", model),
                    "available": True,
                    "source": "auto",
                };
            }
            continue;
        }
        resolved_model = configured_provider_model(candidate, model);
        if configured_provider_key(candidate) and resolved_model {
            return {
                "provider": candidate,
                "model": resolved_model,
                "available": True,
                "source": "auto",
            };
        }
    }

    return {
        "provider": "",
        "model": "",
        "available": False,
        "source": "auto",
    };
}

def provider_status_summary() -> dict[str, any] {
    _sync_runtime_environment();
    config = _load_provider_config();
    openai_key = configured_provider_key("openai");
    anthropic_key = configured_provider_key("anthropic");
    resolved = provider_resolution_summary();
    codex = _codex_status();
    return {
        "status": "ready",
        "config_path": str(_provider_config_path()),
        "preferred_provider": _normalize_provider_name(str(config.get("preferred_provider") or "auto")),
        "resolved_provider": str(resolved.get("provider") or ""),
        "resolved_model": str(resolved.get("model") or ""),
        "resolved_available": bool(resolved.get("available")),
        "providers": {
            "openai": {
                "label": "OpenAI",
                "available": bool(openai_key and configured_provider_model("openai")),
                "key_present": bool(openai_key),
                "key_source": _key_source("openai"),
                "key_preview": _masked_secret(openai_key),
                "model": configured_provider_model("openai"),
            },
            "anthropic": {
                "label": "Anthropic / Claude",
                "available": bool(anthropic_key and configured_provider_model("anthropic")),
                "key_present": bool(anthropic_key),
                "key_source": _key_source("anthropic"),
                "key_preview": _masked_secret(anthropic_key),
                "model": configured_provider_model("anthropic"),
            },
            "codex": {
                "label": "Codex CLI",
                "available": bool(codex["available"]),
                "logged_in": bool(codex["logged_in"]),
                "cli_path": str(codex["cli_path"]),
                "version": str(codex["version"]),
                "login_status": str(codex["login_status"]),
                "model": str(codex["model"]),
            },
        },
    };
}

def save_provider_config_summary(
    preferred_provider: str = "auto",
    openai_api_key: str = "",
    openai_model: str = "",
    anthropic_api_key: str = "",
    anthropic_model: str = "",
    codex_model: str = "",
    codex_cli_path: str = "",
    clear_openai_key: bool = False,
    clear_anthropic_key: bool = False,
) -> dict[str, any] {
    config = _load_provider_config();
    config["preferred_provider"] = _normalize_provider_name(preferred_provider);

    if clear_openai_key {
        config["openai"]["api_key"] = "";
    } elif openai_api_key {
        config["openai"]["api_key"] = str(openai_api_key);
    }
    if openai_model {
        config["openai"]["model"] = str(openai_model);
    }

    if clear_anthropic_key {
        config["anthropic"]["api_key"] = "";
    } elif anthropic_api_key {
        config["anthropic"]["api_key"] = str(anthropic_api_key);
    }
    if anthropic_model {
        config["anthropic"]["model"] = str(anthropic_model);
    }

    if codex_model {
        config["codex"]["model"] = str(codex_model);
    }
    if codex_cli_path {
        config["codex"]["cli_path"] = str(codex_cli_path);
    }

    _write_provider_config(config);
    _sync_runtime_environment();
    summary = provider_status_summary();
    summary["status"] = "saved";
    summary["message"] = "Provider settings saved locally.";
    return summary;
}

import from pathlib { Path }
import from traceforge.parser { truncate_text }
import from traceforge.analysis {
    batch_overview_summary,
    cluster_view_summary,
    run_view_summary
}
import from traceforge.eval { compare_run_harness_summary }
import from traceforge.llm_ops { compile_memory_patch_summary }

def export_report_summary(root_node: any, batch_id: str) -> dict[str, any] {
    overview = batch_overview_summary(root_node, batch_id);
    if overview["status"] == "missing" {
        return {
            "batch_id": batch_id,
            "status": "missing",
            "message": "Batch was not found.",
        };
    }

    sorted_families = sorted(
        overview["family_counts"].items(),
        key=lambda item: any -> any : (-item[1], item[0]),
    );
    lead_family = "UNKNOWN";
    if len(sorted_families) > 0 {
        lead_family = sorted_families[0][0];
    }
    highlight_run = {};
    has_highlight_run = False;
    if len(overview["runs"]) > 0 {
        highlight_run = overview["runs"][0];
        has_highlight_run = True;
    }

    lines: list[str] = [
        "# TraceForge Batch Report",
        "",
        f"- Batch ID: `{batch_id}`",
        f"- Run count: {overview['run_count']}",
        f"- Cluster count: {overview['cluster_count']}",
        f"- Dominant failure family: {lead_family}",
        "",
        "## Demo Highlights",
        "",
        "TraceForge compiles coding-agent trajectories into a Jac graph, groups recurring failure motifs, localizes likely critical steps, and synthesizes reusable AGENTS.md memory patches.",
        "",
        "### Batch Snapshot",
        "",
        f"- Active batch: `{batch_id}`",
        f"- Runs analyzed: {overview['run_count']}",
        f"- Clusters formed: {overview['cluster_count']}",
        f"- Leading failure family: {lead_family}",
        "",
        "## Failure Families",
    ];

    for family in sorted(overview["family_counts"]) {
        lines.append(f"- {family}: {overview['family_counts'][family]}");
    }

    if overview["top_files"] {
        lines.extend([
            "",
            "## Frequent Artifacts",
            "",
            "### Top Files",
        ]);
        for item in overview["top_files"] {
            lines.append(f"- {item[0]} ({item[1]})");
        }
    }

    if overview["top_errors"] {
        lines.extend([
            "",
            "### Top Error Keywords",
        ]);
        for item in overview["top_errors"] {
            lines.append(f"- {item[0]} ({item[1]})");
        }
    }

    if overview["top_tests"] {
        lines.extend([
            "",
            "### Top Tests",
        ]);
        for item in overview["top_tests"] {
            lines.append(f"- {item[0]} ({item[1]})");
        }
    }

    lines.extend([
        "",
        "## Clusters",
    ]);

    for cluster in overview["clusters"] {
        detail = cluster_view_summary(root_node, cluster["cluster_id"]);
        patch = compile_memory_patch_summary(root_node, cluster["cluster_id"]);
        patch_mode = "deterministic";
        if patch["llm_used"] {
            patch_mode = "typed_llm";
        }
        lines.append(f"### {detail['label']}");
        lines.append("");
        lines.append(f"- Cluster ID: `{detail['cluster_id']}`");
        lines.append(f"- Failure class: {detail['failure_class']}");
        lines.append(f"- Size: {detail['size']}");
        lines.append(f"- Medoid run: `{detail['medoid_run_id']}`");
        lines.append(f"- Stored patch count: {detail['stored_patch_count']}");
        lines.append(f"- Patch synthesis mode: {patch_mode}");
        if detail["recurring_signals"] {
            lines.append("- Recurring signals:");
            for signal in detail["recurring_signals"] {
                lines.append(f"  - {signal}");
            }
        }
        if detail["recurring_files"] {
            lines.append("- Recurring files:");
            for item in detail["recurring_files"] {
                lines.append(f"  - {item[0]} ({item[1]})");
            }
        }
        if detail["recurring_errors"] {
            lines.append("- Recurring errors:");
            for item in detail["recurring_errors"] {
                lines.append(f"  - {item[0]} ({item[1]})");
            }
        }
        if detail["recurring_tests"] {
            lines.append("- Recurring tests:");
            for item in detail["recurring_tests"] {
                lines.append(f"  - {item[0]} ({item[1]})");
            }
        }
        if detail["representative_runs"] {
            lines.append("- Representative runs:");
            run_counter = 0;
            for run_item in detail["representative_runs"] {
                if run_counter >= 3 {
                    break;
                }
                lines.append(f"  - {run_item['run_id']}: critical step {run_item['critical_step_idx']} | {run_item['summary']}");
                run_counter += 1;
            }
        }
        lines.append("");
        lines.append("#### AGENTS.md Patch");
        lines.append("");
        lines.append(f"- Summary: {patch['summary']}");
        lines.append(f"- Stored in graph: {patch['stored_in_graph']}");
        lines.append(f"- Patch ID: `{patch['stored_patch_id']}`");
        lines.append("");
        lines.append("```diff");
        lines.append(str(patch["diff_text"]));
        lines.append("```");
        lines.append("");
    }

    representative_run_ids: list[str] = [];
    if has_highlight_run {
        representative_run_ids.append(str(highlight_run["run_id"]));
    }
    for cluster in overview["clusters"] {
        medoid_run_id = str(cluster["medoid_run_id"]);
        if medoid_run_id and medoid_run_id not in representative_run_ids {
            representative_run_ids.append(medoid_run_id);
        }
        if len(representative_run_ids) >= 6 {
            break;
        }
    }

    lines.extend([
        "## Representative Runs",
        "",
        f"- Selected runs shown: {len(representative_run_ids)} of {overview['run_count']}",
        "",
    ]);

    for run_id in representative_run_ids {
        run_detail = run_view_summary(root_node, run_id, batch_id);
        if run_detail["status"] == "missing" {
            continue;
        }
        run_item = {
            "run_id": run_detail["run_id"],
            "task_title": run_detail["task_title"],
            "primary_failure": run_detail["primary_failure"],
            "critical_step_idx": run_detail["critical_step_idx"],
            "summary": run_detail["summary"],
        };
        lines.append(f"### {run_item['run_id']}");
        lines.append("");
        lines.append(f"- Task: {run_item['task_title']}");
        lines.append(f"- Primary failure: {run_item['primary_failure']}");
        lines.append(f"- Critical step: {run_item['critical_step_idx']}");
        lines.append(f"- Summary: {run_item['summary']}");
        lines.append(f"- Source path: `{run_detail['source_path']}`");
        if run_detail["critical_evidence_window"] {
            lines.append("- Critical evidence window:");
            for step in run_detail["critical_evidence_window"] {
                lines.append(f"  - Step {step['idx']} [{step['phase']}]: {step['excerpt']}");
            }
        }
        lines.append("");
    }

    lines.extend([
        "## Baseline Comparison Snapshot",
        "",
    ]);

    if has_highlight_run {
        comparison = compare_run_harness_summary(root_node, highlight_run["run_id"], batch_id);
        lines.append(f"### Run `{highlight_run['run_id']}`");
        lines.append("");
        lines.append(f"- Comparison mode: {comparison['comparison_mode']}");
        lines.append("- Raw baseline diagnosis:");
        lines.append(f"  - {comparison['baseline']['diagnosis']}");
        lines.append(f"  - Baseline mode: {comparison['baseline']['mode']}");
        lines.append(f"  - Specificity: {comparison['baseline']['specificity']}");
        lines.append(f"  - Estimated input size: {comparison['baseline']['pack_token_estimate']} tokens");
        if comparison["baseline"]["blind_spots"] {
            lines.append("  - Blind spots:");
            for item in comparison["baseline"]["blind_spots"] {
                lines.append(f"    - {item}");
            }
        }
        lines.append("- Structured diagnosis:");
        lines.append(f"  - Structured mode: {comparison['structured']['mode']}");
        lines.append(f"  - Failure class: {comparison['structured']['failure_class']}");
        lines.append(f"  - Critical step: {comparison['structured']['critical_step_idx']}");
        lines.append(f"  - Specificity: {comparison['structured']['specificity']}");
        lines.append(f"  - Estimated input size: {comparison['structured']['pack_token_estimate']} tokens");
        lines.append(f"  - Why better: {comparison['structured']['why_better']}");
        if comparison["structured"]["support_points"] {
            lines.append("  - Support points:");
            for item in comparison["structured"]["support_points"] {
                lines.append(f"    - {item}");
            }
        }
        if comparison["structured"]["evidence_window"] {
            lines.append("  - Evidence window:");
            for step in comparison["structured"]["evidence_window"] {
                lines.append(f"    - Step {step['idx']} [{step['phase']}]: {step['excerpt']}");
            }
        }
        lines.append("- Verifier:");
        lines.append(f"  - Winner: {comparison['verifier']['winner']}");
        lines.append(f"  - Rationale: {comparison['verifier']['rationale']}");
    } else {
        lines.append("No runs were available for comparison.");
    }

    lines.extend([
        "",
        "## Demo Talking Points",
        "",
        "- Open the batch overview first to show that the failures are grouped rather than shown as raw logs.",
        "- Jump into the leading cluster to show recurring signals, the medoid, and the generated AGENTS.md patch.",
        "- Open a representative run and point to the highlighted critical step window.",
        "- Close on the fair comparison to show the same-schema raw transcript arm versus TraceForge retrieval, then read the verifier verdict.",
    ]);

    export_dir = Path("exports");
    export_dir.mkdir(exist_ok=True);
    export_path = export_dir.joinpath(batch_id + ".md");
    export_text = "\n".join(lines).strip() + "\n";
    export_path.write_text(export_text, encoding="utf-8");
    preview_text = truncate_text(export_text, 1200);
    return {
        "batch_id": batch_id,
        "status": "exported",
        "path": str(export_path),
        "cluster_count": overview["cluster_count"],
        "run_count": overview["run_count"],
        "preview": preview_text,
    };
}

